window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-psiquiatria-psi-unico"]={"block":"medcurso:medcurso-psiquiatria-psi-unico","label":"Medcurso · PSI UNICO","count":426,"questions":[{"id":"medcurso-psiquiatria-psi-unico-345469","number":"345469","sourceNumber":"345469","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente de 44 anos, com história de que possui episódios que duram semanas, em\nque se sente eufórico, sem necessidade de\nsono, apresentando gastos excessivos,\nhipersexualizado e ouvindo vozes de comando para se matar, relata também que esses episódios\nalternam com quadros em que se sente depressivo, com anedonia e desânimo. Assinalar a\nalternativa que contém a medicação mais adequada para iniciar a esse paciente:","options":{"A":"Fluoxetina.","B":"Amitriptilina.","C":"Prometazina.","D":"Carbonato de lítio."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-281106","number":"281106","sourceNumber":"281106","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Dentre os inibidores seletivos da recaptação de seretonina, aquele que exibe maior\nefeito anticolinérgico é:","options":{"A":"fluoxetina.","B":"paroxetina.","C":"sertralina.","D":"fluvoxamina.","E":"citalopram."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-291807","number":"291807","sourceNumber":"291807","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 62 anos de idade, comparece à Unidade Básica de Saúde, UBS, pois deseja\nfazer avaliação para neoplasia de próstata,\napós colega de trabalho ter tido a doença. Relata que\nacorda, eventualmente, uma vez à noite para urinar, mas nega outros sintomas. Mantém calibre do\njato urinário normal e nega gotejamento terminal. O paciente é casado, tem vida sexual ativa, sem\nproblemas. Tem antecedentes de uretrite na juventude, tratada com antibióticos. Nega história\nfamiliar de CA de Próstata, embora relate que sua mãe teve câncer de mama. Ex tabagista, tendo\nabandonado o hábito há 20 anos. Carga tabágica prévia: 16 anos/maço. Nega etilismo. Nunca fez\nexames para Cancer de próstata. A carga tabágica de 16 anos/maço indica que esse paciente\nfumou:","options":{"A":"Dezesseis maços por ano no período em que fumou.","B":"Um maço por dia, durante 16 anos de tabagismo .","C":"Pelo menos um maço/dia desde os 16 anos de idade.","D":"Dez cigarros por dia por periodo de 8 anos."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-283350","number":"283350","sourceNumber":"283350","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"No sua UBS, numa manhã de sexta-feira, aquele dia separado só para as visitas\ndomiciliares chega uma senhora desesperada,\nchorando muito, inconsolável; a equipe\ndesesperada e com medo já coloca a paciente em uma sala e chama o seu preceptor! Esse por\nsua vez, pensando esta ser uma excelente oportunidade para você demonstrar seus\nconhecimentos de saúde mental na atenção primária em saúde, com uma leve sudorese e um frio\nna barriga você se direciona a sala; A paciente em questão é Dona Joaquina, 65 anos, cliente\nantiga, conhecida por semanalmente ir na UBS renovar a receitinha de clonazepam 2mg e de\nnimesulida; a consulta se inicia: \"O que está se passando com a senhora Dona Joaquina?\" A\npaciente já um pouco recomposta inicia: \"Doutor, meu amado filho saiu de casa faz 1 mês! Desde\nentão todo dia tô tendo falta de ar sabe?! Meu peito dói, dá tipo um vazio, minha artrose do joelho\ntá atacada, meu corpo inteiro e qualquer coisa tô chorando sabe doutor?! Acho que tô com aquela\ntal de depressão sabe, porque é só eu passar no quartinho dele, e já vem essas coisas ruim tudim\ndenovo e o choro vem fácil! Vim aqui doutor pra ver se o senhor me passa algum remédio pra dar\nfim nesse choro sabe? Aquele tal de antidepressivo que o pessoal fala, podia ser até esse que\nminha vizinha toma, esse amitril de 25mg\". Após alguns minutos de consulta a paciente refere\nanedonia, astenia, alteração no apetite, sono e concentração além de um evidente humor\ndeprimido associado à ideias de desesperança e ruína, caracterizando um quadro depressivo\ngrave, qual a conduta frente a essa nova evidência:","options":{"A":"Prescrever ISRS, pois além de baixa incidência de efeitos colaterais, essa classe possui pouca\ninteração medicamentosa, o que é um ponto a favor em sua prescrição para idosos.","B":"Solicitar atendimento psicológico, pois apesar dos sintomas referidos a causa desses foi o\ndistanciamento do filho e ajudando a paciente a superar tal perda é provável que se obtenha a\ncompleta remissão dos sintomas.","C":"Iniciar a Amitriptilina, pois é um fármaco com intenso efeito anti-colinérgico dado esse que\nfortalece sua segurança na prescrição para idosos.","D":"A paciente apresente sinais e sintomas clássicos de uma psicose afetiva e por isso um\n\nestabilizador de humor como o Carbonato de Lítio seria o indicado para o caso em questão."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-283357","number":"283357","sourceNumber":"283357","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente idoso de 69 anos internado na UPA da Sobral com sintomas de agitação e\nagressividade com 2 dias de evolução, segundo a filha do paciente. Realizados exames de\nhemograma e de radiografia de tórax, que evidenciaram uma leucocitose de 14.400 com desvio à\nesquerda e uma radiografia com infiltrado em terço médio e base direita. Foi realizada internação\ndo paciente com diagnóstico de Delirium hiperativo secundário à pneumonia. Para tratamento da\npneumonia foi iniciado antibioticoterapia, e a conduta mais adequado para o tratamento do delirium\né a prescrição de:","options":{"A":"Benzodiazepínicos.","B":"Antidepressivo atípico.","C":"Antipsicótico.","D":"Anticolinesterásico."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-247172","number":"247172","sourceNumber":"247172","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente do sexo feminino, 20 anos, é trazida para consulta ambulatorial por sua mãe\ncom queixa de amenorreia há cinco meses. A\npaciente faz dieta para emagrecer desde os 16 anos,\npesa rigorosamente o volume de comida em seu prato a cada refeição e frequenta academia de\nginástica diariamente por pelo menos 2 horas durante os últimos três anos. Seu índice de massa\ncorporal é de 18kg/m². Assinale a alternativa CORRETA, que apresenta a hipótese diagnóstica\nmais provável.","options":{"A":"Bulimia nervosa.","B":"Amenorreia induzida por exercícios.","C":"Transtorno obsessivo compulsivo.","D":"Amenorreia primária.","E":"Anorexia nervosa."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-247173","number":"247173","sourceNumber":"247173","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente do sexo feminino, 32 anos, procura emergência com queixa de desconforto\ntorácico súbito, palpitações e sensação de\ndesmaio. Relata que \"tem a sensação de que vai\nmorrer\" Apresenta temperatura de 36,7 ºC, pressão arterial de 145/90 mmHg; frequência cardíaca\nde 104 bpm. Esta é a terceira visita recente à emergência com as mesmas queixas. Nega uso de\ndrogas ou de medicações de uso contínuo. A avaliação clínico-laboratorial excluiu condição\ncardíaca como causa dos sintomas. Assinale a alternativa CORRETA, que apresenta,\nrespectivamente, o diagnóstico mais provável e o tratamento farmacológico mais apropriado para a\ncondição.","options":{"A":"Transtorno do pânico - Propranolol.","B":"Transtorno do pânico - Sertralina.","C":"Hipocondria - Clonazepam.","D":"Reação aguda ao estresse - Clonidina.","E":"Reação aguda ao estresse - Clonazepam."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-251898","number":"251898","sourceNumber":"251898","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Numa manhã de segunda-feira, você na segunda semana de sua atuação como\nresidente de medicina de família e\ncomunidade, entra em seu consultório Dona Maria, 25 anos,\nvocê como bom residente inicia a consulta como uma pergunta aberta para que a paciente sinta-se\nconfortável; \"Como posso lhe ajudar Dona Maria?\". A paciente já fragilizada pelo seu sofrimento\nmental começa a lacrimejar e depois de enxugar as lágrimas discorre: \"Olha doutor, tudo começou\nhá 1 ano atrás, quando perdi minha mãe sabe?! E as coisas pioraram há 1 mês quando meu\nmarido me deixou, desde então aqui aculá sinto um aperto no peito sabe?! O coração acelera\nparece que vai sair pela boca, dá uma falta de ar, eu queria alguma coisa pra esse sufocamento\npassar, preciso seguir a vida!\". Baseado no diálogo, responda a questão: diante as informações\nacima, qual seria a conduta mais adequada para a paciente?","options":{"A":"Dar seguimento com a consulta e questionar sobre a rede social da paciente, possíveis sintomas\nque prejudiquem a qualidade de vida e suas\natividades diárias, assim como perguntar sobre\nideações e pensamentos suicidas.","B":"Iniciar imediatamente tratamento medicamentoso, já que a paciente apresenta taquicardia, que é\num dos sintomas clássicos de transtorno de ansiedade generalizada.","C":"Encaminhar para internação psiquiátrica visto que a paciente levou a hipótese de dificuldade de\nseguir a vida e isso significa que a mesma pode estar pensando em suicídio.","D":"Direcionar a paciente em questão a um CAPS (Centro de Atenção Psicossocial), pois o mesmo\né o mais atualizado e indicado dispositivo\nna RAPS (Rede de Atenção Psicossocial) para atender\npaciente com qualquer tipo de transtorno/sofrimento mental."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-251899","number":"251899","sourceNumber":"251899","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Numa manhã de segunda-feira você na segunda semana de sua atuação como\nresidente de medicina de família e\ncomunidade entra em seu consultório Dona Maria, 25 anos, você\ncomo bom residente inicia a consulta como uma pergunta aberta para que a paciente sinta-se\nconfortável; \"Como posso lhe ajudar Dona Maria?\" A paciente já fragilizada pelo seu sofrimento\nmental começa a lacrimejar e depois de enxugar as lágrimas discorre: \"Olha doutor, tudo começou\nhá 1 ano atrás, quando perdi minha mãe sabe?! E as coisas pioraram há 1 mês quando meu\nmarido me deixou, desde então aqui aculá sinto um aperto no peito sabe?! O coração acelera\nparece que vai sair pela boca dá uma falta de ar, eu queria alguma coisa pra esse sufocamento\npassar, preciso seguir a vida!\" Baseado no diálogo, responda a questão: Supondo que na paciente\nacima você diagnosticou como depressão grave, porém a mesma está gestante, levando em conta\nessa nova informação, qual seria a conduta e/ou fármaco de melhor escolha:","options":{"A":"Encaminhar apenas para psicoterapia, pois nenhum fármaco é completamente seguro na\ngestação.","B":"Ácido Valpróico, pois a paciente apresenta claras ideações suicidas e tal fármaco é\ncomprovadamente efetivo em tais sintomas.","C":"Iniciar Sertralina e agendar retorno em 15 dias para reavaliar.","D":"Encaminhar para internação nos Leitos de Saúde Mental da sua cidade visto a gravidade do\ntranstorno em questão."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-217723","number":"217723","sourceNumber":"217723","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sr. João procura a Unidade acompanhamento do filho André de 18 anos. Relata que há\ncerca de 3 dias o filho está agitado, com pensamentos delirantes, não dorme e sai de casa sem\nrumo. O pai diz que há três meses vem percebendo alteração no comportamento do filho que às\nvezes falava sozinho, com dificuldade de concentração, insônia e abandono do emprego e da\nescola. Sem história de uso de álcool ou outras drogas. Durante a consulta André tem discurso\ndesorganizado e fala delirante. Não há relatos de agressões contra si próprio ou contra terceiros.\n\nTem boa rede de suporte familiar. Não apresenta alterações no exame físico. A conduta mais\nadequada para este caso é:","options":{"A":"Introduzir antidepressivo, discutir caso em equipe para acompanhamento regular e orientar\nretorno em 20 a 30 dias.","B":"Introduzir antipsicótico, orientar familiares sobre o quadro, possíveis efeitos adversos do\nmedicamento e para retorno breve, se possível em 24 horas.","C":"Explicar à família que se trata de uma urgência psiquiátrica e encaminhar para internação\nhospitalar.","D":"Encaminhar para psicoterapia e considerar uso de antipsicótico caso os sintomas não melhorem\nou persistam por mais 3 meses."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-183149","number":"183149","sourceNumber":"183149","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Dentre os inibidores seletivos da recaptação de serotonina, aquele que exibe maior\nefeito anticolinérgico é:","options":{"A":"Paroxetina.","B":"Citalopram.","C":"Fluvoxamina.","D":"Fluoxetina.","E":"Sertralina."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-183224","number":"183224","sourceNumber":"183224","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A associação medicamentosa mais comumente utilizada no tratamento da síndrome do\npânico é:","options":{"A":"tranilcipramina e haloperidol.","B":"haloperidol e benzodiazepínico.","C":"tranilcipramina e clomipramina.","D":"clomipramina e benzodiazepínico.","E":"benzodiazepínico e fenobarbital."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-159107","number":"159107","sourceNumber":"159107","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"No acolhimento de uma Unidade Básica de Saúde chega uma mulher de 47 anos,\ntrêmula, com tontura, sudorética, com palidez\nperioral, náusea e sensação de urgência evacuatória.\nApresenta taquicardia e taquipneia, porém, o restante dos sinais vitais está sem alteração. O\ndiagnóstico mais provável é de ansiedade. Diante do caso apresentado, considere as alternativas\npara a conduta do médico. I. Encaminhar a paciente ao psiquiatra. II. Prescrever tratamento\nfarmacológico inicial. III. Solicitar exames para tranquilizar a paciente. IV. Avaliar a correlação\ndos\nsintomas com desencadeante para o quadro clínico. Quais estão corretas?","options":{"A":"Apenas I e II.","B":"Apenas I e III.","C":"Apenas II e III.","D":"Apenas II e IV."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-108675","number":"108675","sourceNumber":"108675","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O paciente com personalidade Paranóide apresenta as seguintes características de\ncomportamento:","options":{"A":"Desconfiança e suspeita;","B":"Afastamento das relações sociais, com uma amplitude restrita de expressão emocional;","C":"Excentricidades no comportamento e distorções cognitivas;","D":"Submissão e comportamento apegado."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-108627","number":"108627","sourceNumber":"108627","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O tabagismo é um dos principais fatores de risco à saúde do ser humano, contribuindo\nconsideravelmente para a ocorrência de casos de Câncer de Pulmão, Doença Arterial Coronariana,\nDoença Pulmonar Obstrutiva Crônica, dentre diversos outros agravos à saúde. As modalidades\nabaixo constituem possibilidades para o tratamento do tabagismo, EXCETO:","options":{"A":"Bupropiona;","B":"Alprazolan;","C":"Aconselhamento;","D":"Adesivo de nicotina."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-84497","number":"84497","sourceNumber":"84497","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"As queixas de tristeza, sensação de depressão e perturbações depressivas em geral\nconsistem em motivo frequente de procura dos serviços de atenção primária. Sobre estas\ncondições, assinale a alternativa incorreta:","options":{"A":"Os casos mais graves devem ser identificados a partir dos chamados \"alertas vermelhos\":\nisolamento social, prostração intensa, grande perda de peso, sintomas psicóticos, tentativa de\nsuicídio ou plano de suicídio elaborado.","B":"Casos mais graves devem ter indicação imediata de medicamentos antidepressivos e\nmobilização de rede familiar/social de auxílio ao paciente.","C":"Em casos de menor gravidade, os medicamentos antidepressivos não devem ser iniciados antes\nda abordagem mais aprofundada dos sintomas e do\ncontexto do sofrimento.","D":"Os inibidores de recaptação da serotonina apresentam maior efetividade que os antidepressivos\ntricíclicos no tratamento da depressão.","E":"Casos mais graves deverão ser abordados em conjunto com as equipes dos Centros de Atenção\nPsicossocial (CAPS) ou outras equipes de saúde mental."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-372075","number":"372075","sourceNumber":"372075","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A dependência de Cocaína se caracteriza pela presença de um padrão de consumo\ncompulsivo, geralmente voltado para o alívio ou evitação de sintomas provocados pela abstinência.\nSendo correto que:","options":{"A":"Ela se torna mais importante do que parte ou mesmo a totalidade das atividades e\ncompromissos sociais do indivíduo, que passa a\ntratá-los sem negligência ou abandono a fim de\nnão privilegiar o uso.","B":"Ela se torna mais importante do que parte ou mesmo a totalidade das atividades e\ncompromissos sociais do indivíduo, que passa a\ntratá-los com negligência ou abandono a fim de\ndesprestigiar o uso.","C":"Ela se torna sem importância em relação às atividades e compromissos sociais do indivíduo, que\npassa a tratá-los com negligência ou\nabandono a fim de privilegiar o uso.","D":"Ela se torna mais importante do que parte ou mesmo a totalidade das atividades e\ncompromissos sociais do indivíduo, que passa a\ntratá-los com negligência ou abandono a fim de\nprivilegiar o uso."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-372076","number":"372076","sourceNumber":"372076","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A síndrome de abstinência da Cocaína pode ser definida:","options":{"A":"Como um conjunto de sinais e sintomas de desconforto físico e não psíquico, que aparecem\nquando o consumo da substância é reduzido ou\ninterrompido.","B":"Como um conjunto de sinais e sintomas de desconforto físico e psíquico, que aparecem quando\no consumo da substância é reduzido ou\ninterrompido.","C":"Como um conjunto de sinais e sintomas de desconforto físico e psíquico, que desaparecem\nquando o consumo da substância é reduzido ou\ninterrompido.","D":"Como um conjunto de sinais e sintomas de desconforto físico e psíquico, que aparecem quando\no consumo da substância é aumentado."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-369510","number":"369510","sourceNumber":"369510","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 77 anos de idade, portador de hipertensão arterial sistêmica, diabetes mellitus\ntipo 2, ansiedade e depressão, está sob\ntratamento farmacológico com múltiplas medicações,\nincluindo anti-hipertensivos (losartana e amlodipina) diurético (furosemida), hipoglicemiante orais\n(glibenclamida. metformina,dapaglifozina), ansiolítico (alprazolan) e antidepressivo (venlafaxina).\nO\npaciente mantém boa funcionalidade e cognição mas, durante uma consulta de rotina na Unidade\nBásica de Saúde, relata fadiga constante, fraqueza muscular, câimbras, dificuldade de deambular,\nperda de concentração e episódios ocasionais de tontura. Quanto ao manejo da depressão nesse\npaciente, que apresenta múltiplas comorbidades, indique a conduta terapêutica mais adequada:","options":{"A":"Aumentar a dose do antidepressivo atual.","B":"Iniciar um antipsicótico atípico.","C":"Realizar terapia cognitivo-comportamental (TCC).","D":"Prescrever um ansiolítico de ação rápida."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-313468","number":"313468","sourceNumber":"313468","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Quanto à Terapia de reposição de nicotina combinada (CTRN) é importante destacar\nque a TRN, seja isolada ou em combinação, só\ndeve ser iniciada na data em que o paciente deixar\nde fumar. Sendo correto que:","options":{"A":"A TRN deve ser usada de forma concomitante com o cigarro ou outros derivados de tabaco.","B":"A TRN deve ser usada de forma concomitante com o cigarro e não de outros derivados de\ntabaco.","C":"A TRN não deve ser usada de forma concomitante com o cigarro ou outros derivados de tabaco.","D":"A TRN sempre deve ser usada de forma concomitante com outros derivados de tabaco."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-314235","number":"314235","sourceNumber":"314235","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Cabe ressaltar que o formato do aconselhamento estruturado/abordagem intensiva\npara a cessação total do tabagismo deve\nconsiderar, preferencialmente, a disponibilidade e\nviabilidade dos indivíduos, dos profissionais e dos serviços de saúde. Esse tratamento deve ser\nbaseado na terapia cognitivo-comportamental e realizado em sessões periódicas, de preferência\nem grupo de apoio, podendo também ser individual. Indique o item correto:","options":{"A":"Consiste em fornecer informações sobre os riscos do tabagismo e os benefícios de parar de\nfumar, e no estímulo ao autocontrole ou\nauto manejo para que os indivíduos possam administrar o\nciclo da dependência.","B":"Consiste em não fornecer informações sobre os riscos do tabagismo e os benefícios de parar de\nfumar, e no estímulo ao autocontrole ou auto manejo para que os indivíduos possam administrar o\nciclo da dependência.","C":"Consiste em fornecer informações sobre os riscos do tabagismo e não os benefícios de parar de\nfumar, e no estímulo ao autocontrole ou auto manejo para que os indivíduos possam administrar o\nciclo da dependência.","D":"Consiste em fornecer informações sobre os riscos do tabagismo e os benefícios de parar de\nfumar, e no estímulo ao autocontrole não no auto manejo para que os indivíduos possam\nadministrar o ciclo da dependência."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-314239","number":"314239","sourceNumber":"314239","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Todos os indivíduos em tratamento para a cessação do tabagismo devem receber\naconselhamento terapêutico estruturado/abordagem intensiva. Indique o item correto:","options":{"A":"O aconselhamento terapêutico da dependência à nicotina envolve intervenção não\nfarmacológica que visa o entendimento do\nproblema e a melhora no manejo dos sintomas de\nabstinência.","B":"O aconselhamento terapêutico da dependência à nicotina não envolve intervenção não\nfarmacológica que visa o entendimento do problema e a melhora no manejo dos sintomas de\nabstinência.","C":"O aconselhamento terapêutico da dependência à nicotina envolve intervenção não\nfarmacológica que visa o entendimento do\nproblema e não a melhora no manejo dos sintomas de\nabstinência.","D":"O aconselhamento terapêutico da dependência à nicotina envolve intervenção farmacológica\nque visa o entendimento do problema e a melhora\nno manejo dos sintomas de abstinência."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-275976","number":"275976","sourceNumber":"275976","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Com relação a depressão ? condição de disfunção neurológica relacionada ao humor e\nmediada por alterações neuroquímicas, pode-se afirmar que:","options":{"A":"A depressão é uma condição inteiramente relacionada a fatores exógenos que ocasiona\nmudança da neuroquímica cerebral.","B":"Os fatores exógenos não interferem na condição da patologia.","C":"A patologia está diretamente relacionada com alterações nos níveis de dopamina, serotonina e\nnoradrenalina a nível cerebral.","D":"As principais linhas terapêuticas estão relacionadas a inibição da IMAO( monoamino-oxidase) e\ninibição da recaptação de acetilcolina nas fendas sinápticas.","E":"Nenhuma das alternativas anteriores."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-280402","number":"280402","sourceNumber":"280402","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Há particularidades nas manifestações clínicas entre pessoas idosas: menos humor\ndepressivo e mais tristeza e ou anedonia (perda de capacidade de sentir prazer ou interesse em\nrealizar a maioria das atividades diárias); os sintomas são menos psicológicos e mais somáticos;\nsendo correto que:","options":{"A":"Há mais déficit cognitivo (memória, sobretudo) e de função executiva; e maior frequência de\nassociação com doença física e cerebral (demência). Em linhas gerais, a depressão pode ser\nconsiderada pródromo ou estágio inicial de doenças neurodegenerativas.","B":"Há mais déficit cognitivo (memória, sobretudo) e de função executiva; e menor frequência de\nassociação com doença física e cerebral (demência). Em linhas gerais, a depressão pode ser\nconsiderada pródromo ou estágio inicial de doenças neurodegenerativas.","C":"Há mais déficit cognitivo (memória, sobretudo) e de função executiva; e maior frequência de\nassociação com doença física e cerebral (demência). Em linhas gerais, a depressão não pode ser\nconsiderada pródromo ou estágio inicial de doenças neurodegenerativas.","D":"Há mais déficit cognitivo (memória, sobretudo) e de função executiva; e maior frequência de\nassociação com doença física e cerebral (demência). Em linhas gerais, a depressão pode ser\nconsiderada pródromo , mas nunca como estágio inicial de doenças neurodegenerativas."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-279042","number":"279042","sourceNumber":"279042","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre os fármacos recomendados para o tratamento de manifestações relacionadas à\nabstinência alcoólica na população pediátrica, assinale a alternativa que apresenta uma droga não\nindicada nesse caso.","options":{"A":"Propofol.","B":"Fenobarbital.","C":"Fenitoina.","D":"Diazepam."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-280416","number":"280416","sourceNumber":"280416","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre as manifestações clínicas da síndrome de abstinência de opioide, assinale a\nalternativa incorreta.","options":{"A":"Diarreia.","B":"Irritabilidade.","C":"Bradipneia.","D":"Confusão mental."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-278627","number":"278627","sourceNumber":"278627","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Assinale a alternativa incorreta em relação ao delirium em pediatria.","options":{"A":"O delirium é uma disfunção muito estudada nas UTIs em adultos, porém ainda pouco avaliada\nna pediatria.","B":"Um dos fatores de risco conhecidos para delirium é o uso de midazolan; portanto, deve ser\nrealizado com parcimônia, e, se possível, considerar o uso de outros sedativos.","C":"Apesar de o delirium ainda ser pouco diagnosticado e monitorado nas UTIs pediátricas, há\nescalas para sem aplicadas, como a p-CAM e CAP-D, para diagnóstico e seguimento dos\npacientes.","D":"As medidas comportamentais, como mobilização precoce e promoção do ciclo sono-vigília,\npouco interferem na prevenção do delirium."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-278629","number":"278629","sourceNumber":"278629","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Assinale a alternativa incorreta sobre sintomas comuns em pacientes com abstinência\nalcoólica.","options":{"A":"Cefaleia.","B":"Tremores.","C":"Piloereção.","D":"Agitação."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-252936","number":"252936","sourceNumber":"252936","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 43 anos de idade, pedreiro, vai à Unidade Básica de Saúde a pedido da\ncompanheira de 32 anos de idade. O casal tem dois filhos e vivem juntos há 6 anos. Segundo a\nmulher, o paciente vem bebendo muito todos os fins de semana, chegando em casa bêbado e\npassando mal. Não consegue ir trabalhar às segundas-feiras e já foi ameaçado de perder o\nemprego. Durante a consulta informa que iniciou consumo alcoólico aos 14 anos de idade e vem\naumentando nos últimos anos. O pai do paciente faleceu de cirrose e tem dois irmãos que\nconsomem álcool em grande quantidade. O paciente diz que sabe que bebe demais porque\napresenta náuseas com vômitos e dores de cabeça. Bebe cerveja, pelo menos 24 latas e\naguardente, cerca de 15 doses por dia, aos sábados e domingos. Informa se sentir aborrecido com\na pressão da mulher e que a sua própria mãe já havia dito que precisaria de hospitalização para\nparar de beber. Entretanto diz que tem controle sobre o consumo de álcool e que pode parar se\nquiser, não precisando de internamento. Ao exame físico, apresenta-se emagrecido, com perda de\nmassa muscular e tremores finos nas mãos. Considerando o protocolo mais usado de diagnóstico\nda Síndrome de Dependência ao Álcool, a informação que precisaria ser coletada para completar a\nconsulta é se o paciente","options":{"A":"tem prejuízo financeiro com os gastos com a bebida.","B":"já agrediu esposa, filhos ou outras pessoas do núcleo familiar, após beber.","C":"precisa beber pela manhã para melhorar os sintomas de mal estar.","D":"já sofreu acidentes pessoais ou no trabalho após uso de álcool."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-252937","number":"252937","sourceNumber":"252937","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 43 anos de idade, pedreiro, vai à Unidade Básica de Saúde a pedido da\ncompanheira de 32 anos de idade. O casal tem dois filhos e vivem juntos há 6 anos. Segundo a\nmulher, o paciente vem bebendo muito todos os fins de semana, chegando em casa bêbado e\npassando mal. Não consegue ir trabalhar às segundas-feiras e já foi ameaçado de perder o\nemprego. Durante a consulta informa que iniciou consumo alcoólico aos 14 anos de idade e vem\naumentando nos últimos anos. O pai do paciente faleceu de cirrose e tem dois irmãos que\nconsomem álcool em grande quantidade. O paciente diz que sabe que bebe demais porque\napresenta náuseas com vômitos e dores de cabeça. Bebe cerveja, pelo menos 24 latas e\naguardente, cerca de 15 doses por dia, aos sábados e domingos. Informa se sentir aborrecido com\na pressão da mulher e que a sua própria mãe já havia dito que precisaria de hospitalização para\nparar de beber. Entretanto diz que tem controle sobre o consumo de álcool e que pode parar se\nquiser, não precisando de internamento. Ao exame físico, apresenta-se emagrecido, com perda de\nmassa muscular e tremores finos nas mãos. Com base na informação do paciente sobre o quanto\nbebe nos fins de semana, o consumo mínimo do paciente, em doses de álcool puro, pelo padrão\nnacional (que considera 14g de alcool por dose), é estimado em","options":{"A":"10 doses.","B":"20 doses.","C":"30 doses.","D":"40 doses."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-252938","number":"252938","sourceNumber":"252938","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 43 anos de idade, pedreiro, vai à Unidade Básica de Saúde a pedido da\ncompanheira de 32 anos de idade. O casal tem dois filhos e vivem juntos há 6 anos. Segundo a\nmulher, o paciente vem bebendo muito todos os fins de semana, chegando em casa bêbado e\npassando mal. Não consegue ir trabalhar às segundas-feiras e já foi ameaçado de perder o\nemprego. Durante a consulta informa que iniciou consumo alcoólico aos 14 anos de idade e vem\naumentando nos últimos anos. O pai do paciente faleceu de cirrose e tem dois irmãos que\nconsomem álcool em grande quantidade. O paciente diz que sabe que bebe demais porque\napresenta náuseas com vômitos e dores de cabeça. Bebe cerveja, pelo menos 24 latas e\naguardente, cerca de 15 doses por dia, aos sábados e domingos. Informa se sentir aborrecido com\na pressão da mulher e que a sua própria mãe já havia dito que precisaria de hospitalização para\nparar de beber. Entretanto diz que tem controle sobre o consumo de álcool e que pode parar se\nquiser, não precisando de internamento. Ao exame físico, apresenta-se emagrecido, com perda de\nmassa muscular e tremores finos nas mãos. Considerando a estratégia comportamental cognitiva\nmais empregada na Atenção Básica à Saúde para controle da Síndrome de Dependência Alcoólica\ne outras Dependências Químicas, pode se dizer que esse paciente encontra-se no estágio","options":{"A":"pré-contemplativo.","B":"contemplativo.","C":"de preparação.","D":"de manutenção."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-252939","number":"252939","sourceNumber":"252939","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"\"O uso de drogas, na atualidade, é uma preocupação mundial. Entre 2000 e 2015,\nhouve um crescimento de 60% no número de\nmortes causadas diretamente pelo uso de drogas,\nsendo este dado o recorte de apenas uma das consequências do problema. Tal condição extrapola\nas questões individuais e se constitui como um grave problema de saúde pública, com reflexos nos\ndiversos segmentos da sociedade. Os serviços de segurança pública, educação, saúde, sistema de\njustiça, assistência social, dentre outros, e os espaços familiares e sociais são repetidamente\nafetados, direta ou indiretamente, pelos reflexos e pelas consequências do uso das drogas.\"\nBRASIL, Presidência da República, DECRETO LEI Nº 9.761, DE ABRIL DE 2019, publicado no\nDOU em 11/04/2019. O Decreto Lei 9.761, de abril de 2019, modifica a abordagem da questão do\nuso de drogas no seguinte aspecto:","options":{"A":"Passa a considerar o uso medicinal dos derivados da maconha como lícito.","B":"Cria novos Centros de Referência para o tratamento de drogas no setor público.","C":"Propõe maiores impostos para a comercialização de bebidas alcóolicas.","D":"Exclui a \"\"redução de danos\"\" como estratégia das políticas públicas."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-252940","number":"252940","sourceNumber":"252940","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"\"O uso de drogas, na atualidade, é uma preocupação mundial. Entre 2000 e 2015,\nhouve um crescimento de 60% no número de\nmortes causadas diretamente pelo uso de drogas,\nsendo este dado o recorte de apenas uma das consequências do problema. Tal condição extrapola\nas questões individuais e se constitui como um grave problema de saúde pública, com reflexos nos\ndiversos segmentos da sociedade. Os serviços de segurança pública, educação, saúde, sistema de\njustiça, assistência social, dentre outros, e os espaços familiares e sociais são repetidamente\nafetados, direta ou indiretamente, pelos reflexos e pelas consequências do uso das drogas.\"\nBRASIL, Presidência da República, DECRETO LEI Nº 9.761, DE ABRIL DE 2019, publicado no\nDOU em 11/04/2019. O Decreto em tela corrobora um dos posicionamentos da população brasileira\ncom relação ao problema de saúde causado pelo uso de drogas ilícitas. Essa consideração é feita\ncom a afirmativa de que:","options":{"A":"O uso de drogas ilícitas deve ser punido criminalmente de forma mais efetiva.","B":"O tratamento dos usuários de drogas deve ser mantido de forma gratuita.","C":"As drogas licitas, como o tabaco, têm importância menor que as drogas ilícitas.","D":"Os gastos com tratamento deveriam ser empregados no combate ao tráfico."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-215495","number":"215495","sourceNumber":"215495","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Marque a alternativa INCORRETA em relação ao delirium.","options":{"A":"Ocorre em cerca de 20% das crianças.","B":"O uso de dexmedetomidina tem sido citado no tratamento do delirium em pediatria.","C":"O tratamento é realizado com haloperidol e clonidina.","D":"É de difícil diagnóstico em pediatria, provavelmente subestimado."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-212191","number":"212191","sourceNumber":"212191","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Foram relatados os seguintes dados sobre óbitos referentes a uma população de 4.500\nhomens da faixa etária de 30-59 anos: 8 óbitos em não fumantes; 25 óbitos entre os que fumavam\naté meio maço de cigarros por dia; 38 óbitos entre os que fumavam de meio a um maço por dia, e\n74 óbitos entre os que fumavam mais de um maço por dia. Nesse contexto, assinale a alternativa\ncorreta.","options":{"A":"O tabagismo aumenta a mortalidade.","B":"Existe uma relação dose-resposta entre tabagismo e morte.","C":"A relação entre o tabagismo e os coeficientes de mortalidade é linear.","D":"Para interpretar esses dados, é necessário saber a idade no momento da morte.","E":"Para interpretar esses dados, as informações devem estar expressas em coeficientes."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-180123","number":"180123","sourceNumber":"180123","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente do sexo masculino, 17 anos, refere que ouve ?vozes? dentro da sua cabeça\nque mandam dar três passos para trás a cada vez\nque visualizar um carro vermelho; essas\n\n?vozes? também mandam repetir ?não, não, não? diante de notícias catastróficas que ouça, a fim\nde evitar que essas situações noticiadas aconteçam com ele ou membros de sua família. Diante do\ncaso exposto, qual o diagnóstico pensado pelo psiquiatra que atendeu este paciente, bem como a\nterapêutica indicada?","options":{"A":"Esquizofrenia paranoide; haloperidol 10 mg/dia","B":"Transtorno de ansiedade generalizada; paroxetina 20 mg/dia","C":"Transtorno obsessivo-compulsivo; fluoxetina 40 mg/dia","D":"Esquizofrenia simples; risperidona 6 mg/dia","E":"Transtorno obsessivo-compulsivo; amitriptilina 50 mg/dia"},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-180139","number":"180139","sourceNumber":"180139","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente do sexo feminino, 33 anos, procura o psiquiatra pela primeira vez em sua vida\npor sentir tristeza acentuada, dificuldade para conciliar o sono, falta de disposição para o\ntrabalho e\ndiminuição de energia para atividades do lar. Além dessas queixas, relata também episódios de\nchoro fácil imotivado, certo grau de impaciência, afastamento de atividades antes consideradas\nprazerosas e crenças negativas sobre si mesma: ?Dr, ?às vezes penso que seria melhor não\nexistir...? Relata essas queixas há cerca de dois meses. Tentou ir ao psiquiatra antes, mas no\nPosto de Saúde de sua casa não tinha vaga para atendimento psiquiátrico antes. Diante do caso\nexposto, qual a terapêutica indicada?","options":{"A":"Carbolitium","B":"Haloperidol","C":"Bromazepam","D":"Sertralina","E":"Ácido valpróico"},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-180147","number":"180147","sourceNumber":"180147","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente do sexo feminino, 33 anos, procura o psiquiatra pela primeira vez em sua vida\npor sentir tristeza acentuada, dificuldade para conciliar o sono, falta de disposição para o\ntrabalho e\ndiminuição de energia para atividades do lar. Além dessas queixas, relata também episódios de\nchoro fácil imotivado, certo grau de impaciência, afastamento de atividades antes consideradas\nprazerosas e crenças negativas sobre si mesma: ?Dr, ?às vezes penso que seria melhor não\nexistir...? Relata essas queixas há cerca de dois meses. Tentou ir ao psiquiatra antes, mas no\nPosto de Saúde de sua casa não tinha vaga para atendimento psiquiátrico antes. No final da\nconsulta da paciente citada no caso acima, o médico lembra-se de fazer determinada perguntada,\nnecessária para a elucidação diagnóstico em questão. Qual seria essa pergunta?","options":{"A":"?A Senhora já fez uso de drogas ilícitas??","B":"?Alguma vez já apresentou episódios de elação do humor e logorréia?","C":"?A Senhora ouve vozes alucinatórias imperativas??","D":"?Alguma vez a Senhora já permaneceu algum tempo sem conseguir deambular após evento\nestressor??","E":"?A Senhora apresenta alucinações auditivas??"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-181340","number":"181340","sourceNumber":"181340","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Dadas as afirmativas quanto aos tipos de receitas para prescrição de substâncias\ncontroladas, segundo a Agência Nacional de\nVigilância Sanitária (ANVISA), I. As anfetaminas, os\nbenzodiazepínicos e barbitúricos são prescritos em receituário azul, em via única. II. As\nsubstâncias\nantirretrovirais são prescritas em receituário branco, em duas vias. III. Os analgésicos opioides e\nantagonistas são prescritos em receita amarela, em via única. verifica-se que está(ão) correta(s)","options":{"A":"I, II e III.","B":"I e III, apenas.","C":"II e III, apenas.","D":"II, apenas.","E":"I, apenas."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-182780","number":"182780","sourceNumber":"182780","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Ocorre que na ultima década, trabalhos já chamavam a atenção para uma associação\nentre Esquizofrenia e Diabetes Mellitus tipo 2 (DM2).\nSendo, entretanto, INADEQUADO o que se\nafirma na alternativa:","options":{"A":"Certas populações com genes poderiam ativar esse mecanismo, diminuindo com isso o\nmetabolismo basal, com consequente aumento das gorduras visceral e total. Os trabalhos mais\nconsistentes relatam que os pacientes com esquizofrenia e distúrbios afetivos apresentam 1,5 a 2\nvezes maior prevalência de diabetes e obesidade do que a população geral.","B":"Devido ao aumento atual da oferta alimentar, cria-se, portanto, um ambiente propício para o\ndesenvolvimento da síndrome metabólica.","C":"Ocorre descrição de dezenas de genes criando alterações em diversos níveis do metabolismo,\ncom ações específicas ou por meio de interação\nentre eles, ocupando, desse modo, papel\nfundamental na etiologia e progressão da síndrome metabólica.","D":"Há mais de uma década, trabalhos já chamavam a atenção para uma associação entre\nEsquizofrenia e Diabetes Mellitus tipo 2\n(DM2), pendentemente de fármacos, com relato inclusive\nda alta probabilidade da interferência do tratamento medicamentoso."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-152644","number":"152644","sourceNumber":"152644","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Ataques recorrentes e inesperados de ansiedade grave, medo de enlouquecer ou\nmorrer, sensação de asfixia, vertigem, ondas de\ncalor, com exames clínicos normais ou que não\njustificam o quadro:","options":{"A":"Fobia ou ansiedade social.","B":"Transtorno dissociativo.","C":"Transtorno de pânico.","D":"Transtorno de somatização.","E":"Transtorno de ansiedade generalizada."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-152648","number":"152648","sourceNumber":"152648","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Alteração do conteúdo do pensamento ou juízo de realidade presente em transtornos\ncomo a esquizofrenia:","options":{"A":"Neologismo.","B":"Delírio.","C":"Incoerência.","D":"Alucinação.","E":"Roubo do pensamento."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-161177","number":"161177","sourceNumber":"161177","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Os Benzodiazepínicos (BZDs) devem seu nome à sua estrutura molecular constituída\npor um anel benzeno e, como podem produzir\ntolerância e dependência, sua aplicação deve ser\nbastante criteriosa, mesmo sendo classificado como uma substância de baixa toxicidade e,\nportanto, segura. Dentre os dados epidemiológicos a seguir, aponte o único que esteja\nINCORRETO.","options":{"A":"Maior a incidência em mulheres acima de 50 anos com problemas médicos e psiquiátricos.","B":"Atualmente, 1 em cada 10 adultos recebe prescrições de BZDs a cada ano, a maioria por\nPsiquiatras.","C":"Os BZDs são responsáveis por cerca de 50% de toda a prescrição de psicotrópicos.","D":"Estima-se que cada clínico tenha em sua lista 50 pacientes dependentes de Benzodiazepínicos."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-161182","number":"161182","sourceNumber":"161182","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Nas indicações de uso de benzodiazepínicos, este deve ser feito sob cuidados médicos\ne avaliado o custo-benefício de tal prescrição,\nincluindo dose e tempo de uso. Deve-se evitar seu\nuso prolongado (mais de três meses), pois isto aumenta a possibilidade de tolerância e\ndependência, sendo o seu uso contraindicado:","options":{"A":"sem predisposição genética.","B":"com uso de outras medicações.","C":"associado ao álcool.","D":"levando em consideração as características da personalidade."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-161188","number":"161188","sourceNumber":"161188","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em referência aos métodos para combater a dependência de benzodiazepínicos,\nassinale a alternativa contendo o método que NÃO se\nmostra funcional.","options":{"A":"Para a maioria dos pacientes, a redução rápida é o melhor método de retirada.","B":"O processo palatino, que pode durar até seis meses.","C":"Em casos selecionados de abuso de grande quantidade de comprimidos, pode ser\nrecomendável a substituição por BZD de meia-vida longa.","D":"Em casos selecionados de abuso de drogas de meia-vida curta, pode ser recomendável a\nsubstituição por BZD de meia-vida longa."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-161160","number":"161160","sourceNumber":"161160","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A Encefalopatia de Wernicke-Korsakov é a complicação esperada em:","options":{"A":"Descolamento prematuro de placenta.","B":"Placenta prévia.","C":"Hiperemese gravídica severa.","D":"Diabete gestacional."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-161141","number":"161141","sourceNumber":"161141","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A causa do delirium em pacientes críticos é multifatorial e está associada a vários\nfatores de risco, que podem ser divididos em\ntrês grandes grupos: fatores predisponentes do\npróprio paciente; fatores relacionados à gravidade da doença; fatores iatrogênicos ou inerentes ao\npróprio ambiente de UTI. Os fatores de risco em crianças ainda são pouco descritos, porém,\nimagina-se que sejam semelhantes aos observados em adultos. Nas crianças, os principais fatores\nde risco são os seguintes, EXCETO,","options":{"A":"Dor.","B":"Ansiedade de separação.","C":"Privação do sono (ruídos, frio e luz).","D":"Baixo uso de sedativos e analgésicos."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-161163","number":"161163","sourceNumber":"161163","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O delirium pode ser definido como:","options":{"A":"Uma apresentação crônica de um quadro de psicose em pacientes internados em UTI pediátrica.","B":"Um distúrbio de consciência que se desenvolve de forma insidiosa com piora à noite.","C":"Um distúrbio cognitivo e da consciência que se desenvolve de forma aguda e flutuante.","D":"Uma incapacidade súbita de repassar informações, como perda de memória."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-134097","number":"134097","sourceNumber":"134097","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente com histórico de uso de anfetamina para exercícios físicos extenuantes\ndá entrada no hospital com agitação, miose e\nsudorese. Sua pressão arterial é de 210 x\n\n120 mmHg e sua frequência cardíaca é de 180 bpm. Qual das medicações abaixo listadas\napresenta contraindicação para essa situação?","options":{"A":"Metoprolol.","B":"Nitroprussiato.","C":"Diazepam.","D":"Diltiazem."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-134878","number":"134878","sourceNumber":"134878","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O abandono do tabagismo é uma recomendação muito importante na prevenção da\ndoença cardiovascular, cerebrovascular e renal.\nSobre o manejo de tabagistas, é CORRETO\nafirmar que,","options":{"A":"é necessário informar sobre os malefícios do hábito de fumar. Caso a pessoa não esteja\ndisposta a cessar o hábito neste momento, o médico deve usar terapia medicamentosa para\najudá-lo.","B":"o objetivo do tratamento farmacológico é minimizar os sintomas da síndrome de abstinência.","C":"fumantes que fumam o primeiro cigarro depois de uma hora ao acordar devem receber\ntratamento medicamentoso no início do acompanhamento.","D":"muitas vezes a monoterapia não é eficaz, e a pessoa necessita utilizar mais de uma droga para\nobter êxito no tratamento."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-110581","number":"110581","sourceNumber":"110581","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Segundo o CID 10, para o diagnóstico de episódio depressivo leve, dois de três\nsintomas têm que estar presentes por pelo menos duas semanas. Estes três sintomas são:","options":{"A":"Baixa auto-estima, humor deprimido e crises de choro;","B":"Perda do apetite, insônia terminal e hipotimia;","C":"Atos auto-lesivos, auto-estima baixa e anedonia;","D":"Perda de interesse, atenção reduzida e fraqueza generalizada;","E":"Anedonia, humor deprimido e fatigabilidade\naumentada."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-110589","number":"110589","sourceNumber":"110589","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Ataques recorrentes e inesperados de ansiedade grave, medo de enlouquecer ou\nmorrer, sensação de asfixia, vertigem, ondas de calor, com exames clínicos normais ou que\nnão justificam o quadro:","options":{"A":"Fobia ou Ansiedade Social;","B":"Transtorno Dissociativo;","C":"Transtorno de Pânico;","D":"Transtorno de Somatização;","E":"Transtorno de Ansiedade Generalizada."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-110014","number":"110014","sourceNumber":"110014","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A abordagem sugerida como mínima pelo Ministério da Saúde para utilização rotineira\ndos Profissionais de Saúde em programas de controle\ndo Tabagismo é caracterizada por objetivos\nque têm a finalidade de:","options":{"A":"avaliar o grau de dependência da Nicotina, avaliar o estágio de capacidade respiratória e\ncardíaca,embasando a conduta a ser tomada em relação ao caso.","B":"avaliar o nível de Nicotinemia pela dosagem da cotinina urinária para avaliar o consumo diário de\nnicotina pela contagem do número de cigarros fumados.","C":"avaliar o perfil de saúde mental do fumante em busca de co-morbidades que interfiram na\nmanutençãodo vício, identificar as lesões pulmonares já encontradas pela classificaçãodos\nenfisemas, modelo transteórico de mudança de comportamento.","D":"identificar os fumantes, avaliar o grau de dependência da nicotina e avaliar o estágio de\nmudança de comportamento."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-86626","number":"86626","sourceNumber":"86626","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente 23 anos, sexo feminino, fez uso de antidepressivo tricíclico como tentativa de\nsuicídio, chega à unidade hospitalar 40 minutos após o evento: Exame físico: confusa, taquicárdica,\npupilas midriáticas e hipotensa apresentando convulsões. Assinale as alternativas CORRETAS em\nrelação à conduta terapêutica (emergências clínicas): I ? Indução do vômito; II ? Lavagem gástrica\nseguida de carvão ativado na primeira hora; III ? Uso de benzodiazepínicos.","options":{"A":"Apenas afirmativas II e III estão corretas.","B":"Apenas afirmativa II está correta.","C":"Apenas afirmativas I e III estão corretas.","D":"Apenas afirmativa III está correta.","E":"Todas afirmativas estão corretas."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-86795","number":"86795","sourceNumber":"86795","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em relação à dependência do álcool, assinale a alternativa correta.","options":{"A":"Exames laboratoriais não têm papel nenhum na avaliação do paciente dependente do álcool;","B":"O CAGE é um exame usado para triagem do uso abusivo de álcool. ?C? corresponde a Cut\nDown, ou seja, se o paciente já sentiu\nnecessidade de diminuir a quantidade de bebida ou parar\nde beber. ?A? corresponde a Annoyed, ou seja, se o paciente já se sentiu incomodado ao ter seu\nmodo de beber criticado. ?G? corresponde a Guilty, ou seja, se o paciente já se sentiu culpado\npela maneira como costuma beber. ?E? corresponde a Eager, ou seja, se o paciente já sentiu\nforte necessidade de consumo de álcool em momentos inadequados.","C":"O diazepam é o melhor benzodiazepínico para uso no tratamento da intoxicação aguda pelo\nálcool;","D":"Pacientes com Síndrome de Abstinência do Álcool Nível II devem ser tratados em nível\nhospitalar.","E":"Pacientes com quadro de intoxicação aguda pelo álcool devem receber rotineiramente soro\nglicosado para evitar risco de hipoglicemia."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-86598","number":"86598","sourceNumber":"86598","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Kátia, 46 anos, ensino fundamental incompleto, dona de casa, moradora da periferia de\numa grande metrópole, há oito meses vem\nsentindo cansaço, fraqueza e falta de ânimo para as\natividades diárias. Refere perda de 6 kg em seis meses e não consegue dormir direito. Procura o\nposto de saúde e consegue ser consultada no mesmo dia. Chora durante a entrevista. Relata\nproblemas com o marido que perdeu o emprego há 6 meses e que voltou a beber demais. Relata,\ntambém, saudade do filho que não vê há 10 meses, porque ele mora em outra cidade e tem uma\nvida difícil. Nega uso de medicamentos e refere episódios semelhantes anteriormente. Com base\nno caso apresentado, assinale a alternativa correta.","options":{"A":"Estabelecer uma boa comunicação com a paciente não contribui para o sucesso do tratamento.","B":"Não se deve perguntar à Kátia sobre ideação suicida, pois isto pode induzi-la a tomar tal\natitude.","C":"O estado de humor, manifestações de ansiedade, de mania e de hipomania não devem fazer\nparte do exame clínico de Kátia.","D":"Entrevistas com frequência semanal no início do tratamento provocarão menor adesão da\npaciente.","E":"A melhora da paciente com uso do antidepressivo ocorrerá provavelmente entre a segunda e a\nquarta semana de uso."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-298285","number":"298285","sourceNumber":"298285","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A maioria das pessoas experimenta pelo menos um sintoma a cada 2 semanas e não\nconsidera consultar um profissional de saúde devido aos sintomas. Apenas uma minoria das\npessoas que experimentam um sintoma consulta um profissional de saúde, sendo que a maioria\ndos sintomas não é explicada pela doença. Pacientes com ?sintomas inexplicados? costumam\ngerar grande apreensão diagnóstica por parte do médico. A melhor maneira de manejar estes\npacientes é:","options":{"A":"Boa comunicação paciente-médico, não diferenciada da comunicação com os demais pacientes","B":"Indicar terapia cognitivo-comportamental","C":"Tranquilização","D":"Prescrever antidepressivos"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-151924","number":"151924","sourceNumber":"151924","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A Portaria 571, 2013 dispõe sobre as seguintes diretrizes do acompanhamento das\npessoas tabagistas no âmbito do SUS, EXCETO:","options":{"A":"Desenvolvimento de estratégias de autocuidado dos tabagistas, promovendo sua autonomia e\ncorresponsabilização dos atores envolvidos.","B":"Acolhimento e apoio terapêutico adequados na rede de atenção secundária à saúde com acesso\nà terapia de reposição de nicotina, se\nnecessário.","C":"Que tabagismo é um importante fator de risco para doenças crônicas e seu tratamento\napresenta um bom custo-efetividade como medida\npreventiva.","D":"Articulação de ações intersetoriais para promoção à saúde e educação permanente e\ncapacitação das equipes de saúde para companhamento dos tabagistas."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-129736","number":"129736","sourceNumber":"129736","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente com 30 anos, diagnóstico de lúpus eritematoso sistêmico, submetida à\npulsoterapia, apresenta alterações de comportamento: sente-se perseguida pelas enfermeiras e\npelos colegas de quarto. Durante a noite ficou agitada e tentou fugir do hospital. A provável\nsituação clínica em questão é:","options":{"A":"A paciente tem um quadro de esquizofrênia paranóide, que é frequente em lúpus eritematoso\nsistêmico.","B":"Deve-se transferi-la para unidade de acompanhamento psiquiátrico, pois o tratamento do\ntranstorno psiquiátrico é prioritário.","C":"Eclosão de um quadro mental indica bom prognóstico para a evolução do lúpus eritematoso\nsistêmico.","D":"A alteração de comportamento pode estar relacionada à atividade da doença de base e ao\ntratamento."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-107897","number":"107897","sourceNumber":"107897","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"São medicações de primeira linha no tratamento medicamentoso de um paciente\ntabagista.","options":{"A":"Nortriptilina e tiotropio;","B":"Tiotropio e bupropriona;","C":"Adesivo de nicotina e bupropiona;","D":"Salbutamol spray e bupropiona."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-80925","number":"80925","sourceNumber":"80925","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 43 anos, alcoolista crônico foi encontrado com rebaixamento do estado de\nconsciência e levado ao Pronto-Socorro pelo Resgate. Ainda na ambulância, recebeu 50 ml de\nglicose a 50% endovenoso, com melhora do quadro, persistindo alguma confusão. Como se\nencontrava febril, foi necessário internação para investigação melhor do quadro. No dia seguinte, o\npaciente agravou o estado de confusão mental, agora com nistagmo multidirecional, paralisia do VI\npar craniano à esquerda e ataxia cerebelar. Assinale a alternativa CORRETA:","options":{"A":"Provável quadro de hematoma subdural crônico.","B":"O quadro pode ter agravado por se tratar de Meningite bacteriana.","C":"O agravo se deve à Síndrome de Wernicke, decorrente da deficiência de tiamina.","D":"É quadro típico de demência alcoólica.","E":"A causa do agravo pode ser devida à mielinóllise pontina central."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-61491","number":"61491","sourceNumber":"61491","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"São medicações de primeira linha no tratamento medicamentoso de um paciente\ntabagista:","options":{"A":"Nortripitilina e tiotrópio.","B":"Tiotrópio e bupropiona.","C":"Tiotrópio e vareniclina.","D":"Salbutamol spray e bupropiona.","E":"Adesivo de nicotina e bupropiona."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-26664","number":"26664","sourceNumber":"26664","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em relação à eficácia dos medicamentos antidepressivos, pode-se dizer que os:","options":{"A":"benzodiazepínicos são mais eficazes que os outros tipos de drogas","B":"tricíclicos são superiores aos inibidores seletivos de recaptação de serotonina","C":"a eletroconvulsoterapia é menos efetiva no tratamento de depressões graves","D":"inibidores seletivos da recaptação de serotonina são superiores aos tricíclicos","E":"inibidores seletivos da recaptação de serotonina são equivalentes aos tricíclicos"},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-26667","number":"26667","sourceNumber":"26667","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Cláudio tem 42 anos, está obeso, com a pressão arterial de 150 x 100 mmHg. Vem ao\nconsultório por apresentar uma síndrome gripal há 10 dias. É tabagista desde os 16 anos. Fuma 02\nmaços/dia e acende o primeiro cigarro logo após acordar. Quando perguntado sobre o desejo de\nparar de fumar, diz que já tentou, mas sem sucesso. Deseja tentar de novo. Você o orienta a,\nEXCETO:","options":{"A":"fazer terapia cognitivo-comportamental com o psicólogo da unidade de referência","B":"terapia medicamentosa pode ser feita com medicamentos não nicotínicos ou com a reposição de\nnicotina, mas não com ambos","C":"pode usar medicação para auxiliar a parar de fumar, desde que sua pressão arterial esteja\ncontrolada","D":"se tiver úlcera péptica não deve usar goma de mascar e nicotina","E":"vir em consultas semanais na unidade de saúde da família para aconselhamento durante um\nmês, o que aumenta a chance de abandono do fumo."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-13242","number":"13242","sourceNumber":"13242","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma mulher de 66 anos, portadora de câncer de mama, com metástases ósseas, está\nem tratamento quimioterápico há seis meses. Para controle das dores, faz uso de antiinflamatórios\nnão- esteroidais, codeína em doses moderadas e bisfosfonatos. Foi trazida para consulta pelos\nfamiliares porque há um mês apresenta-se sem interesse pelas tarefas do dia-a-dia, diz que está\nsem esperança, só pensa em morrer e quer interromper o tratamento oncológico. A conduta\napropriada nesse caso é:","options":{"A":"Concordar com os sentimentos da paciente, respeitar suas vontades, interromper a\nquimioterapia e aumentar a dose de analgésicos.","B":"Discutir com a paciente seus sentimentos atuais, explicar a natureza de seus sintomas e propor\nmedicação antidepressiva.","C":"Evitar discutir os sintomas e os sentimentos da paciente e prescrever ansiolíticos.","D":"Internar a paciente e hiberná-la com sedativos potentes.","E":"Discutir a questão somente com a família e adotar as medidas que forem julgadas pertinentes."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-13252","number":"13252","sourceNumber":"13252","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"No acolhimento de uma Unidade Básica de Saúde (UBS), chegou uma mulher de 47\nanos, trêmula, com tontura, sudorética, com\npalidez perioral, náusea e sensação de urgência\nevacuatória. Apresenta taquicardia e taquipneia, porém, o restante dos sinais vitais está sem\nalteração. O diagnóstico mais provável é ansiedade. Diante do caso a conduta médica deve ser: I .\nencaminhar o paciente ao psiquiatra. II . prescrever tratamento farmacológico inicial. III .\nsolicitar\nexames para tranquilizar a paciente. IV . avaliar a correlação dos sintomas como desencadeante\npara o quadro clínico. Quais estão corretas?","options":{"A":"Apenas I e II.","B":"Apenas II, III e IV.","C":"Apenas II e III.","D":"Apenas III e IV.","E":"Apenas II e IV."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-13280","number":"13280","sourceNumber":"13280","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Deu entrada no pronto-socorro às 3 horas da manhã, um paciente do sexo masculino,\n35 anos de idade, presidiário, trazido por\nagentes penitenciários informando que o paciente estava\ncom diarreia, febre, cãimbras musculares e dificuldade para dormir. Os policiais relataram que o\nmesmo está preso há 10 dias, por uso e tráfico de drogas. Ao exame foi observado: Taquicardia,\nhipertensão arterial, febril, agitação, miose, creção de pelos, lacrimejamento e rinorreia. Qual o\nprovável diagnóstico?","options":{"A":"Abstinência de álcool.","B":"Abstinencia de opioides.","C":"Abstinencia e cocaína.","D":"Intoxicação por benzodiazepínicos.","E":"Nenhuma das anteriores."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-7487","number":"7487","sourceNumber":"7487","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O tabagismo está presente na carcinogênese de vários tumores. Nas sequências\nabaixo qual a que contém apenas órgão/sedes em\nque o fumo é fator determinante no\naparecimento de canceres?","options":{"A":"Colo do útero, vesícula, pâncreas, pulmão, rins e bexiga.","B":"Boca, endométrio, pulmão, mama, estômago e intestino.","C":"Boca, esôfago, pâncreas, pulmão, rins e bexiga.","D":"Colo do útero, endométrio, fígado, vesícula biliar, faringe e pulmão.","E":"Todos os acima têm relação com o tabagismo."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-354390","number":"354390","sourceNumber":"354390","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 35 anos de idade, motorista de transporte por aplicativo, comparece à Unidade\nBásica de Saúde acompanhado da esposa. O paciente vem apresentando episódios frequentes de\nansiedade caracterizados como sudorese excessiva, taquicardia, sensação de formigamento em\nmãos e sensação de morte iminente. Relata que foi vítima de um assalto violento há cerca de\nquatro meses enquanto trabalhava. Embora no momento do assalto tenha se mantido calmo, assim\ncomo no mês subsequente, há três meses tem experimentado os sintomas descritos, além de\nlembranças muito vívidas do evento. Acorda até 4 vezes por noite com pesadelos que relembram o\nepisódio. Não consegue passar pelas áreas onde o assalto ocorreu e sente os sintomas\nmotivadores da consulta ao ouvir barulhos altos semelhantes a tiros ou sirenes, o que tem\ndificultado e, até, impedido o trabalho. Nega sintomas anteriores. Nega alcoolismo ou uso de\ndrogas. Tem história familiar de doença mental - prima com depressão. Sua esposa nota, também,\nque ele está mais retraído e que evita interações sociais. O paciente chegou à UBS em busca de\najuda, afirmando que esses sintomas estão prejudicando, seriamente, sua qualidade de vida e sua\ncapacidade de trabalhar. Diante do relato apresentado, identifique o distúrbio psiquiátrico\nespecífico\napresentado pelo paciente:","options":{"A":"Síndrome do pânico.","B":"Transtorno de estresse pós-traumático.","C":"Reação aguda ao estresse.","D":"Transtorno fóbico."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-354391","number":"354391","sourceNumber":"354391","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 35 anos de idade, motorista de transporte por aplicativo, comparece à Unidade\nBásica de Saúde acompanhado da esposa. O paciente vem apresentando episódios frequentes de\nansiedade caracterizados como sudorese excessiva, taquicardia, sensação de formigamento em\nmãos e sensação de morte iminente. Relata que foi vítima de um assalto violento há cerca de\nquatro meses enquanto trabalhava. Embora no momento do assalto tenha se mantido calmo, assim\ncomo no mês subsequente, há três meses tem experimentado os sintomas descritos, além de\nlembranças muito vívidas do evento. Acorda até 4 vezes por noite com pesadelos que relembram o\nepisódio. Não consegue passar pelas áreas onde o assalto ocorreu e sente os sintomas\nmotivadores da consulta ao ouvir barulhos altos semelhantes a tiros ou sirenes, o que tem\ndificultado e, até, impedido o trabalho. Nega sintomas anteriores. Nega alcoolismo ou uso de\ndrogas. Tem história familiar de doença mental - prima com depressão. Sua esposa nota, também,\nque ele está mais retraído e que evita interações sociais. O paciente chegou à UBS em busca de\najuda, afirmando que esses sintomas estão prejudicando, seriamente, sua qualidade de vida e sua\ncapacidade de trabalhar. Indique o elemento específico da história clínica que possibilita o\ndiagnóstico:","options":{"A":"Revivência rememorativa.","B":"História familiar.","C":"Sintomas psicossomáticos.","D":"Distúrbio do sono."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-354392","number":"354392","sourceNumber":"354392","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 35 anos de idade, motorista de transporte por aplicativo, comparece à Unidade\nBásica de Saúde acompanhado da esposa. O paciente vem apresentando episódios frequentes de\nansiedade caracterizados como sudorese excessiva, taquicardia, sensação de formigamento em\nmãos e sensação de morte iminente. Relata que foi vítima de um assalto violento há cerca de\nquatro meses enquanto trabalhava. Embora no momento do assalto tenha se mantido calmo, assim\ncomo no mês subsequente, há três meses tem experimentado os sintomas descritos, além de\nlembranças muito vívidas do evento. Acorda até 4 vezes por noite com pesadelos que relembram o\nepisódio. Não consegue passar pelas áreas onde o assalto ocorreu e sente os sintomas\nmotivadores da consulta ao ouvir barulhos altos semelhantes a tiros ou sirenes, o que tem\ndificultado e, até, impedido o trabalho. Nega sintomas anteriores. Nega alcoolismo ou uso de\ndrogas. Tem história familiar de doença mental - prima com depressão. Sua esposa nota, também,\nque ele está mais retraído e que evita interações sociais. O paciente chegou à UBS em busca de\najuda, afirmando que esses sintomas estão prejudicando, seriamente, sua qualidade de vida e sua\ncapacidade de trabalhar. Indique o fármaco (droga) disponível no SUS que apresenta melhores\nevidências para tratamento específico do caso:","options":{"A":"Clonazepan.","B":"Fluoxetina.","C":"Amitriptilina.","D":"Quetiapina."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-294496","number":"294496","sourceNumber":"294496","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Adolescente, 15 anos de idade, sexo masculino, vem à UBS trazido pela mãe, que\ninforma modificações no comportamento do menor,\napresentando-se agressivo em casa, e batendo\nnos irmãos menores. Trata-se do primeiro filho de uma prole de quatro, sendo o único do primeiro\ncasamento, com 4 anos de diferença para o segundo irmão. Segundo a mãe, o menor mantinha um\nbom relacionamento em família mas, após ter sido surpreendido, há 3 meses, usando maconha em\ncasa, foi repreendido e teve a mesada suspensa. Não tem contato com o pai. A agressividade se\nagravou ainda mais, após o término do relacionamento com a namorada, de 17 anos, há duas\nsemanas. Desde então, passa grande parte do tempo trancado no quarto; não senta à mesa para\nas refeições e muitas vezes não se alimenta. Tem boa escolaridade e é considerado acima da\nmédia, mas faltou, pelo menos, dois dias à escola nas últimas semanas. Hoje, após uma briga, o\nadolescente mencionou que \"preferia estar morto do que viver desse jeito\". Com relação ao risco de\nsuicídio, expresso na fala do adolescente, pode se afirmar que:","options":{"A":"Há ideação suicida que indica grande risco.","B":"Há ideação suicida passiva e o risco não pode ser previsto.","C":"Não há ideação suicida pois o plano não foi formulado.","D":"Há ideação suicida passiva e vaga, com risco baixo."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-294497","number":"294497","sourceNumber":"294497","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Adolescente, 15 anos de idade, sexo masculino, vem à UBS trazido pela mãe, que\ninforma modificações no comportamento do menor,\napresentando-se agressivo em casa, e batendo\nnos irmãos menores. Trata-se do primeiro filho de uma prole de quatro, sendo o único do primeiro\ncasamento, com 4 anos de diferença para o segundo irmão. Segundo a mãe, o menor mantinha um\nbom relacionamento em família mas, após ter sido surpreendido, há 3 meses, usando maconha em\ncasa, foi repreendido e teve a mesada suspensa. Não tem contato com o pai. A agressividade se\nagravou ainda mais, após o término do relacionamento com a namorada, de 17 anos, há duas\nsemanas. Desde então, passa grande parte do tempo trancado no quarto; não senta à mesa para\nas refeições e muitas vezes não se alimenta. Tem boa escolaridade e é considerado acima da\nmédia, mas faltou, pelo menos, dois dias à escola nas últimas semanas. Hoje, após uma briga, o\nadolescente mencionou que \"preferia estar morto do que viver desse jeito\". Identifique o número de\nfatores epidemiológicos de risco de morte por suicídio nos dados apresentados no caso:","options":{"A":"Oito fatores.","B":"Sete fatores.","C":"Seis fatores.","D":"Cinco fatores."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-294498","number":"294498","sourceNumber":"294498","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Adolescente, 15 anos de idade, sexo masculino, vem à UBS trazido pela mãe, que\ninforma modificações no comportamento do menor,\napresentando-se agressivo em casa, e batendo\nnos irmãos menores. Trata-se do primeiro filho de uma prole de quatro, sendo o único do primeiro\ncasamento, com 4 anos de diferença para o segundo irmão. Segundo a mãe, o menor mantinha um\nbom relacionamento em família mas, após ter sido surpreendido, há 3 meses, usando maconha em\ncasa, foi repreendido e teve a mesada suspensa. Não tem contato com o pai. A agressividade se\nagravou ainda mais, após o término do relacionamento com a namorada, de 17 anos, há duas\nsemanas. Desde então, passa grande parte do tempo trancado no quarto; não senta à mesa para\nas refeições e muitas vezes não se alimenta. Tem boa escolaridade e é considerado acima da\nmédia, mas faltou, pelo menos, dois dias à escola nas últimas semanas. Hoje, após uma briga, o\nadolescente mencionou que \"preferia estar morto do que viver desse jeito\". Com relação à\nepidemiologia das mortes por suicídio no Brasil, pode se afirmar que essas mortes","options":{"A":"independem de classe social e etnia.","B":"ocorrem mais nas zonas rurais que urbanas.","C":"são comuns em jovens e raras em idosos.","D":"são limitadas pela proibição das armas de fogo."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-284562","number":"284562","sourceNumber":"284562","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher, 28 anos de idade, é levada pela polícia a uma Unidade de Pronto Atendimento,\nUPA, por quadro de comportamento violento\n(estava atirando pedras nos carros que passavam).\n\nVem acompanhada da genitora que refere alteração do comportamento, há dois dias. Relata que\nnos últimos meses a paciente vinha\napresentando episódios de irritabilidade, dormindo cerca de 3\nhoras por dia e fez compras não condizentes com a situação econômica da família. Nega\ncomorbidades, uso de medicações, drogas ou quedas. A paciente apresenta-se com\ncomportamento violento, ameaçando a equipe de saúde, e fazendo gestos obscenos. Diz que os\nfamiliares querem interná-la para ficar com todo o dinheiro dela e que é muito rica. Se recusa a\nreceber atendimento médico, não permite ser examinada e não aceita tomar nenhuma medicação.\nEm relação ao quadro de base da paciente, é CORRETO afirmar:","options":{"A":"O diagnóstico de transtorno afetivo bipolar é o mais provável, mesmo sem histórico de\ndepressão.","B":"O quadro provavelmente decorre de um distúrbio orgânico, sendo indicado exame de imagem do\nsistema nervoso central.","C":"Os delírios de grandeza e persecutório apresentados sugerem diagnóstico de esquizofrenia.","D":"A paciente apresenta-se em episódio de histeria, associado a um transtorno psicossomático."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-284563","number":"284563","sourceNumber":"284563","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher, 28 anos de idade, é levada pela polícia a uma Unidade de Pronto Atendimento,\nUPA, por quadro de comportamento violento\n(estava atirando pedras nos carros que passavam).\n\nVem acompanhada da genitora que refere alteração do comportamento, há dois dias. Relata que\nnos últimos meses a paciente vinha\napresentando episódios de irritabilidade, dormindo cerca de 3\nhoras por dia e fez compras não condizentes com a situação econômica da família. Nega\ncomorbidades, uso de medicações, drogas ou quedas. A paciente apresenta-se com\ncomportamento violento, ameaçando a equipe de saúde, e fazendo gestos obscenos. Diz que os\nfamiliares querem interná-la para ficar com todo o dinheiro dela e que é muito rica. Se recusa a\nreceber atendimento médico, não permite ser examinada e não aceita tomar nenhuma medicação.\nCom relação à conduta mais adequada em relação à contenção da paciente, é correto afirmar:","options":{"A":"A contenção não deve ser utilizada já que a paciente se recusa a receber atendimento, e está\nacompanhada.","B":"A contenção não deve ser utilizada até que a paciente seja devidamente examinada.","C":"A contenção física deve ser realizada e evitada a contenção química até a avaliação da\npsiquiatria.","D":"A contenção física deve ser realizada, seguida de injeção de antipsicótico e/ou\nbenzodiazepínico."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-284564","number":"284564","sourceNumber":"284564","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher, 28 anos de idade, é levada pela polícia a uma Unidade de Pronto Atendimento,\nUPA, por quadro de comportamento violento\n(estava atirando pedras nos carros que passavam).\n\nVem acompanhada da genitora que refere alteração do comportamento, há dois dias. Relata que\nnos últimos meses a paciente vinha\napresentando episódios de irritabilidade, dormindo cerca de 3\nhoras por dia e fez compras não condizentes com a situação econômica da família. Nega\ncomorbidades, uso de medicações, drogas ou quedas. A paciente apresenta-se com\ncomportamento violento, ameaçando a equipe de saúde, e fazendo gestos obscenos. Diz que os\nfamiliares querem interná-la para ficar com todo o dinheiro dela e que é muito rica. Se recusa a\nreceber atendimento médico, não permite ser examinada e não aceita tomar nenhuma medicação.\nConsiderando o provável quadro de base, identifique o principal tratamento farmacológico de\nmanutenção.","options":{"A":"Antidepressivo.","B":"Estabilizador do humor.","C":"Benzodiazepinico.","D":"Antipsicótico."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-284623","number":"284623","sourceNumber":"284623","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Estaremos comemorando 20 anos da aprovação da Lei no 10.216, de 6 de abril de\n2001, que operacionalizou os principais\naspectos da Reforma Psiquiátrica, a qual produziu uma\nsérie de ações do panorama assistencial em saúde mental. Entre essas ações constam: \"a abertura\nde um grande número de serviços públicos de base comunitária, redução drástica do número de\nleitos psiquiátricos, inversão do financiamento prioritário dos hospitais para os serviços abertos,\ne\numa maior atenção aos direitos dos pacientes...\"(Gama, J. A Reforma Psiquiátrica e seus críticos.\n\nPhysis Revista de Saúde Coletiva, Rio de Janeiro, 22 [ 4 ]: 1397-1417, 2012) A principal\ncaracterística do modelo físico-reducionista da\nsaúde, aplicada à saúde mental, pode ser descrita\ncomo:","options":{"A":"A busca de equivalentes estruturais neuronais para os fenômenos psíquicos.","B":"A crença nas intervenções físicas (exemplo: eletrochoque) como modelos de tratamento.","C":"A redução dos diagnósticos psiquiátricos àqueles codificados no CID 11.","D":"A consideração dos fenômenos mentais como efeitos das condições sociais."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-284624","number":"284624","sourceNumber":"284624","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Estaremos comemorando 20 anos da aprovação da Lei no 10.216, de 6 de abril de\n2001, que operacionalizou os principais\naspectos da Reforma Psiquiátrica, a qual produziu uma\nsérie de ações do panorama assistencial em saúde mental. Entre essas ações constam: \"a abertura\nde um grande número de serviços públicos de base comunitária, redução drástica do número de\nleitos psiquiátricos, inversão do financiamento prioritário dos hospitais para os serviços abertos,\ne\numa maior atenção aos direitos dos pacientes...\"(Gama, J. A Reforma Psiquiátrica e seus críticos.\n\nPhysis Revista de Saúde Coletiva, Rio de Janeiro, 22 [ 4 ]: 1397-1417, 2012) A principal crítica\nformulada ao modelo de reforma psiquiátrica\naplicado no Brasil, expressa nos diversos documentos\nda Associação Brasileira de Psiquiatria, advém de considerar que","options":{"A":"Os CAPS deveriam ser multiplicados pois são inteiramente adequados ao tratamento.","B":"O SUS não tem qualidade suficiente para o atendimento adequado dos pacientes.","C":"A Atenção Básica a Saúde não consegue resolver os transtornos mentais comuns.","D":"Há desvalorização do cuidado especializado em situações mais graves e emergenciais."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-284631","number":"284631","sourceNumber":"284631","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Situações de uso abusivo de álcool, gerando agravos de saúde, são comuns nas\nunidades básicas de saúde. O profissional de saúde deve estar preparado para acolher esses\npacientes, entendendo sua história, estratificando o grau de dependência ao álcool e planejando,\njunto à equipe multiprofissional, o plano terapêutico singular. Na estratificação do grau de\ndependência do álcool, a ferramenta \"\"CAGE\"\" é geralmente utilizada na entrevista, bem como o\nconceito de dose padrão. No mnemônico CAGE, o G. identifica que:","options":{"A":"O paciente acorda de manhã com necessidade de beber.","B":"O paciente entende que precisa parar de beber.","C":"O paciente se sente culpado por beber.","D":"O paciente já tentou parar de beber."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-284632","number":"284632","sourceNumber":"284632","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Situações de uso abusivo de álcool, gerando agravos de saúde, são comuns nas\nunidades básicas de saúde. O profissional de saúde deve estar preparado para acolher esses\npacientes, entendendo sua história, estratificando o grau de dependência ao álcool e planejando,\njunto à equipe multiprofissional, o plano terapêutico singular. Na estratificação do grau de\ndependência do álcool, a ferramenta \"\"CAGE\"\" é geralmente utilizada na entrevista, bem como o\nconceito de dose padrão. Entende-se por dose-padrão, na investigação do consumo de álcool, a\nquantidade de etanol puro","options":{"A":"consumido por dose independente do tipo de bebida.","B":"capaz de provocar lesão histológica, com especificação por órgão.","C":"capaz de promover efeitos no Sistema Nervoso Central.","D":"capaz de ser detectada em exames como o do \"\"bafômetro\"\"."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-284633","number":"284633","sourceNumber":"284633","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Situações de uso abusivo de álcool, gerando agravos de saúde, são comuns nas\nunidades básicas de saúde. O profissional de\nsaúde deve estar preparado para acolher esses\npacientes, entendendo sua história, estratificando o grau de dependência ao álcool e planejando,\njunto à equipe multiprofissional, o plano terapêutico singular. Na estratificação do grau de\ndependência do álcool, a ferramenta \"\"CAGE\"\" é geralmente utilizada na entrevista, bem como o\nconceito de dose padrão. Para um paciente que tem dependência alcoólica grave e decide parar de\nbeber para prevenir a síndrome de abstinência, o fármaco com via de administração que,\nnecessariamente, deve estar incluído no plano terapêutico singular, é:","options":{"A":"Bupropiona.","B":"Tiamina.","C":"Buspirona.","D":"Carbamazepina."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-49407","number":"49407","sourceNumber":"49407","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 57 anos de idade, tabagista desde os 13 anos de idade, deseja deixar de\nfumar. Consome 20 cigarros/dia, sendo o\nprimeiro antes do café da manhã. Tem sobrepeso. Já\ntentou parar de fumar três vezes, tendo passado até três semanas em abstinência, mas retornou\nposteriormente. Não é etilista, nem tem comorbidade psiquiátrica. Nega uso de drogas. Quanto ao\ntratamento desse paciente, é correto afirmar:","options":{"A":"As tentativas prévias indicam pior prognóstico quanto à adesão ao tratamento.","B":"O tratamento com reposição de nicotina é mais eficaz que com antidepressivos.","C":"O uso de bupropiona deve iniciar antes da data prevista para a parada do tabagismo.","D":"O ganho ponderal associado ao tratamento aumenta os riscos cardiovasculares.","E":"O tratamento farmacológico não é mais eficaz que o aconselhamento psicológico."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-27501","number":"27501","sourceNumber":"27501","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 38 anos de idade, é admitido no pronto atendimento com mal-estar\ncaracterizado como dispneia, sensação de\nmorte iminente, parestesia perioral, taquicardia e\nsudorese. Teve mais três episódios similares nos últimos dois meses, tendo sido atendido em\nemergências e liberado. Nega tabagismo, bebe eventualmente aos fins de semana. Nega\nhipertensão ou diabetes. Ao exame físico, TA 130 X 80 mmHg, PR: 110 bpm cheio e rítmico, FR: 30\nipm, profundas. Glicemia capilar: 89 mg/dl. Saturação de O² ao ar ambiente 98%. ECG: taquicardia\nsinusal. Com relação ao quadro apresentado, é falso afirmar:","options":{"A":"Benzodiazepínicos são úteis no atendimento de urgência.","B":"O risco de suicídio é elevado.","C":"Alcoolismo deve ser considerado como comorbidade.","D":"A resposta terapêutica aos antidepressivos é rápida.","E":"O uso de antidepressivos pode produzir mais sintomas na fase aguda."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-13306","number":"13306","sourceNumber":"13306","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher, 34 anos de idade, após briga como marido, ingere cerca de 50 ml de água\nsanitária. Apresenta-se no PA ansiosa e agitada,\nporém lúcida, com queixa de dor abdominal. O\natendimento de emergência não mostra alterações nos dados vitais e nos demais dados do exame\nfísico. A melhor conduta é:","options":{"A":"fazer endoscopia digestiva alta, se normal, dar alta hospitalar","B":"medicar com antiácidos e dar alta, pois a dose não é tóxica","C":"internar em terapia intensiva, tendo em vista o risco de pneumonite química","D":"manter no PA até segurança de acompanhamento no domicílio e avaliação psicológica","E":"internar e fazer exames de imagens, tendo em vista o risco de perfuração visceral"},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-283847","number":"283847","sourceNumber":"283847","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A respeito do Delirium tremens, é correto afirmar que","options":{"A":"as alucinações mais comuns são as auditivas ou táteis.","B":"pode ser piorado pelo uso de benzodiazepínicos.","C":"acontece nas abstinências ao álcool ou cocaína.","D":"o tratamento é com tiamina.","E":"a mortalidade é elevada, variando de 5-25%."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-249728","number":"249728","sourceNumber":"249728","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Considerando as doenças pulmonares que têm o tabagismo como um dos seus fatores\nde risco, analise as opções a seguir e\nidentifique com V as Verdadeiras e com F as Falsas.\n\n( ) Linfangioleiomiomatose.\n\n( ) Fibrose pulmonar idiopática.\n\n( ) Pneumonia intersticial descamativa.\n\n( ) Histiocitose de células de Langerhans.\n\n( ) Doença Pulmonar Obstrutiva Crônica (DPOC).\n\nA alternativa que contém a sequência CORRETA, de cima para baixo, é:","options":{"A":"F V F V V.","B":"F V V V V.","C":"F F V F F.","D":"V F F F F.","E":"V V V V V."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-250025","number":"250025","sourceNumber":"250025","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O uso de tabaco na população idosa é comum e é causa importante de morbidade e\nmortalidade. Somente não podemos aceitar que:","options":{"A":"O tabagismo constitui-se em fator de risco (FR) para a demência e seu abandono pode reduzir a\ncarga de demência.","B":"A exposição passiva ao fumo também pode aumentar o risco de demência.","C":"Fumantes idosos apresentam maior intenção em abandonar o cigarro se comparados aos\njovens.","D":"Fumantes idosos têm maior probabilidade de sucesso quando tentam parar de fumar."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-181162","number":"181162","sourceNumber":"181162","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Devido à importante associação dos antipsicóticos atípicos com os componentes da\nsíndrome metabólica, é importante o conhecimento acerca da relação entre substâncias\nantipsicóticas e diabetes, somente não sendo recomendado o seguinte:","options":{"A":"Avaliação do risco-benefício.","B":"Dentro da avaliação dos efeitos adversos, vários fatores devem ser valorizados, tais como\nnatureza da condição psiquiátrica do paciente,\nmetas, histórico do fármaco, adesão, efetividade da\nmedicação, comorbidades e custo.","C":"Os riscos das implicações clínicas dos componentes da síndrome metabólica não devem\ninfluenciar a escolha do fármaco.","D":"O monitoramento deve ocorrer se possível, antes da prescrição dos antipsicóticos atípicos,\ndeterminando altura e peso, calculando o Índice De Massa Corporal (IMC), medindo a\ncircunferência da cintura e a pressão arterial, e também dosando a glicemia de jejum e o perfil\nlipídico."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-134725","number":"134725","sourceNumber":"134725","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Constituem fatores associados ao maior risco de suicídio:","options":{"A":"História de perda recente, idade avançada, viver só, ter doença física crônica.","B":"Tentativa anterior, adolescente, solteiro, sem doença física crônica.","C":"Tentativa anterior, adolescente, com filhos, sem doença física crônica.","D":"História de perda recente, idade avançada, ser casado, ter doença física crônica."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-111916","number":"111916","sourceNumber":"111916","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em relação ao tratamento da dependência à nicotina, assinale a alternativa CORRETA:","options":{"A":"A abordagem cognitivo-comportamental deve ser realizada em todos os fumantes\nindependentemente do escore de Fagerstrom.","B":"A bupropiona não é contraindicada em pacientes com histórico de convulsões.","C":"Deve-se oferecer terapia de reposição de nicotina e bupropiona a todos os indivíduos que\ninformam fumar logo após o despertar.","D":"Após o estabelecimento de obstrução grave ao fluxo aéreo, ou após os 65 anos de vida, a\ninterrupção do tabagismo não oferece mais benefício."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-350897","number":"350897","sourceNumber":"350897","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente masculino, 32 anos, é levado ao setor de emergência. com agitação\npsicomotora importante, queixando-se de cefaleia e\nevoluindo com sudorese. Ao exame físico,\nencontra-se acordado, agitado, taquicárdico (FC= 130 bpm) hipertenso (PA = 190 X 100 mmHg), e\ntaquipneico (FR:24 mrm). Além disso, observa-se midríase ao exame físico. Glicemia e\neletrocardiograma foram normais. Há relato de uso de cocaína e opioides. Encontra-se com\nsaturação de oxigênio normal e não tem indicação para suporte ventilatório mecânico. Qual das\nmedicações abaixo estaria mais indicada para o manejo do quadro clínico acima descrito?","options":{"A":"Haloperidol.","B":"Flumazeni.","C":"Diazepam.","D":"Naloxone."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-350809","number":"350809","sourceNumber":"350809","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Tales, de 17 anos, procura atendimento médico referindo tosse diária há quatro meses,\nenquanto cumpria pena de privação provisória de liberdade em instituição socioeducativa. Refere\nuso diário de cigarro por tabaco e por cannabis. Quando questionado sobre o uso do cigarro,\nrelatou ?O cigarro para mim não é problema, mas solução. Eu fui preso por coisa que não fiz e\ndesde que isso aconteceu eu não consigo relaxar. Eu estou assustado o tempo todo, como se\nestivesse sempre com os nervos à flor da pele. Se eu escuto uma sirene, acho que é alguém vindo\nme pegar. De noite eu não prego os olhos. As únicas coisas que me acalmam é jogar futebol e\nfumar. Eu não sinto vontade de fumar nos dias que eu consigo jogar futebol, porque eu fico\nrelaxado, mas de uns tempos para cá eu tenho tido medo de sair de casa.? A partir do relato de\nTales, assinale a alternativa que contenha opção farmacológica considerada de primeira linha para\nseu problema de saúde.","options":{"A":"Sertralina.","B":"Quetiapina.","C":"Amitriptilina.","D":"Gabapentina."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-350808","number":"350808","sourceNumber":"350808","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Tales, de 17 anos, procura atendimento médico referindo hipervigilância, inquietação,\nfatigabilidade, insônia e dificuldade de\nmanter o foco. Após abordagem inicial com o médico de\nfamília, foi iniciado tratamento medicamentoso com um comprimido de 20mg de Fluoxetina. Três\ndias após o atendimento, Tales retorna referindo piora em sensação de angústia, além de náuseas.\nAssinale a alternativa com a conduta adequada diante das queixas de Tales.","options":{"A":"Orientar que pode haver piora transitória de sintomas durante introdução de fármaco. Diminuir\ndose e solicitar reavaliação precoce.","B":"Orientar que pode haver piora transitória de sintomas durante a introdução de fármaco. Associar\nantipsicótico para controle de sintomas.","C":"Orientar possível falha terapêutica em processo de introdução de fármaco. Substituir medicação\npor outro ansiolítico de mesma classe\nfarmacológica.","D":"Orientar possível falha terapêutica. Substituir medicação por outro ansiolítico de outra classe\nfarmacológica."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-350807","number":"350807","sourceNumber":"350807","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Tales, de 17 anos, procura atendimento médico referindo hipervigilância, inquietação,\nfatigabilidade, insônia e dificuldade de manter o foco. Foi iniciada Fluoxetina 20mg/dia, mas houve\nnecessidade de redução transitória de dose para 10mg/dia. Tales retorna para nova avaliação\nquinze dias após início de acompanhamento. Refere não sentir mais efeitos adversos, mas refere\nque persiste com sintomas ansiosos. Assinale a alternativa com a conduta adequada diante da\nqueixa de Tales.","options":{"A":"Considerando falha terapêutica em controle de sintomas, substituir medicação por outra de\nmesma classe.","B":"Orientar sobre a necessidade de observar uso de medicação por pelo menos quatro semanas\npara avaliar resposta clínica.","C":"Aumentar gradativamente dosagem de medicação, observando surgimento de efeitos adversos\ne controle adequado de sintomas.","D":"Considerando que paciente está adaptado à medicação, aumentar Fluoxetina para dose máxima\ne programar descalonamento gradual de dose\nconforme controle de sintomas."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-321301","number":"321301","sourceNumber":"321301","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente masculino, 45 anos, é trazido por familiares para serviço de Emergência\napresentando desorientação temporal e espacial.\nRefere não ter se alimentado hoje devido a\nnáusea, associada a cefaleia de intensidade moderada. Irmã informa que o paciente é alcoolista,\ningere aproximadamente um litro de aguardente por dia há alguns anos, mas que parou de beber\nhá dois dias. Também iniciou com sintomas persecutórios, nas últimas horas, quando ficou\nrepetindo que alguém queria invadir sua casa para lhe fazer mal. Esses sintomas são inéditos. Ao\nexame: Pressão arterial: 170x100 mmHg; FC: 110 bpm; tremor grosseiro em mãos e sudorese, sem\noutras alterações. Ansioso, relata que vê formigas em seus braços, inclusive tenta matá-las,\nembora não haja formiga ou qualquer outra alteração em sua pele. Qual a conduta inicial a ser\nadotada?","options":{"A":"Solicitar tomografia de crânio sem contraste.","B":"Iniciar uso de anti-hipertensivo e manter observação até controle pressórico.","C":"Prescrever haloperidol para uso domiciliar e orientar retorno breve para reavaliação.","D":"Iniciar uso de benzodiazepínico e manter em observação até melhor controle dos sintomas."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-321328","number":"321328","sourceNumber":"321328","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Os pais de um adolescente de 13 anos de idade estão preocupados com a\npossibilidade de seu filho ter a oportunidade\nde consumir cigarros e álcool precocemente. Assinale\na alternativa em relação a esse tema.","options":{"A":"Dificuldades para resolver tarefas, falta de afeto, depressão, desempenho escolar fraco são\nfatores que não alcançam significância para risco de uso de tabaco.","B":"As crianças cujos pais mantêm o ambiente de casa livre do tabaco são menos prováveis de se\ntornarem fumantes, independentemente se o pai ou a mãe é fumante.","C":"Não faz sentido se preocupar com os amigos do filho que fumam pois seu filho não tem maior\nprobabilidade de sofrer essa influência e iniciar o consumo de cigarros nos anos seguintes.","D":"Resultados de programas de alta qualidade com duração média de 12 meses de\nacompanhamento, mostraram que não houve aumento de\nnão fumantes nos grupos de intervenção\ncomparados aos de controles."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-321353","number":"321353","sourceNumber":"321353","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Durante atendimento médico em demanda programada para pessoas que desejam\ncessar o tabagismo, você atende Paulo, de 40\nanos. Em sua abordagem baseada na Entrevista\nMotivacional, você identifica que Paulo se encontra no estágio da Preparação. Assinale a\nalternativa com a intervenção adequada.","options":{"A":"Ajudar a perceber os gatilhos para prevenir recaídas.","B":"Aumentar a percepção sobre riscos de manter o comportamento atual.","C":"Tirar dúvidas e ajudar na escolha de melhor estratégia em busca da mudança.","D":"Desfazer a ambivalência evocando riscos de não mudar e elencando motivos para mudar."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-292810","number":"292810","sourceNumber":"292810","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem de 70 anos, viúvo, aposentado e alcoolista diário, vai à consulta médica para\nacompanhar Hipertensão Arterial Sistêmica e Diabetes anteriormente conhecidas e controladas.\nDurante a consulta, fica evidente humor deprimido constante, fala em volume baixo e pouco\nespontâneo. Relata perda do interesse na convivência com os netos e nos jogos de futebol que\ncostuma acompanhar, insônia intermediária, perda de peso involuntária por redução do apetite, e\nideias de que é um fardo para a família. Tem ideia de morte, achando que pode ser um alívio,\ninclusive com pensamentos sobre suicídio, mas sem planejamento no momento. Qual a opção\ncorreta em relação ao manejo do paciente no contexto descrito acima?","options":{"A":"O uso de antidepressivo tricíclico deve ser evitado pelo risco de morte em caso de ingestão em\ngrande quantidade.","B":"O médico deve evitar o uso de Inibidor de Recaptação de Serotonina, pela possibilidade do\naumento de risco de suicídio.","C":"Como perguntar sobre ideias de suicídio pode induzir ou aumentar o risco de tentativa, tal\nquestionamento deve ser evitado.","D":"O grau de preocupação é baixo e a intervenção médica deve ser pouco invasiva, pois o paciente\nestá fora da faixa etária de maior\nincidência de suicídio."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-292847","number":"292847","sourceNumber":"292847","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Os pais de uma criança de seis anos de idade vêm ao ambulatório com queixas de que\na criança está com posturas desafiadoras;\nrecusa em aceitar ordens ou solicitações de adultos,\ncom os quais discute com frequência; e tendendo a responsabilizar os outros pelos seus atos.\n\nEsses sintomas ocorrem em casa e em outros espaços sociais. Diante desse relato, qual a principal\nhipótese diagnóstica?","options":{"A":"Transtorno de conduta.","B":"Transtorno explosivo intermitente.","C":"Transtorno de oposição desafiante.","D":"Transtorno da personalidade antissocial."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-292854","number":"292854","sourceNumber":"292854","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Durante seu atendimento na demanda espontânea em uma UBS, você atende Dona\nMarta, de 52 anos. Dona Marta vem com\nqueixa de \"angústia\" e traz o seguinte relato: \"Doutor,\ndesde agosto de 2019, quando minha filha terminou o namoro com um rapaz, eu não consigo\nsuperar o fim do relacionamento dela, porque ela perdeu a virgindade com esse rapaz. Doutor, eu\ndurmo e acordo pensando nisso, eu não consigo tirar esse problema da minha cabeça. Eu já perdi\n7 kg, desde o fim desse relacionamento deles dois. Eu reconheço que isso é ridículo, que não faz\nsentido, que não me faz bem, mas eu não consigo nem mais ter relação com meu marido desde\nentão. Eu não consigo tirar esses pensamentos da cabeça. Eu cheguei ao ponto de escrever cartas\nsobre como a vida dele e da minha filha poderia ser. Eu só consigo melhorar essa angústia se eu\nescrever. Eu já escrevi mais de 30 cartas.\" Considerando o relato de Dona Marta, assinale a\nalternativa com hipótese diagnóstica mais provável.","options":{"A":"Fobia social.","B":"Transtorno esquizoafetivo.","C":"Transtorno obsessivo compulsivo.","D":"Transtorno de ansiedade generalizada."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-259714","number":"259714","sourceNumber":"259714","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente 56 anos, masculino, hipertenso e diabético, foi encaminhado a serviço de\npneumologia para \"parar de fumar\". No momento, não apresenta sintomas respiratórios mas tem\ncarga tabágica de 10 maços/ano e apresenta critérios de dependência severa. Há seis meses,\ntentou cessar espontaneamente mas apresentou irritabilidade e sintomas depressivos que\nocasionaram isolamento social. Durante a consulta, verifica-se que o paciente encontra-se\nmotivado e preparado para iniciar uma estratégia de cessação. Qual a estratégia terapêutica mais\nadequada dentre as opções abaixo a ser aplicada no presente contexto?","options":{"A":"Utilizar estratégia motivacional e iniciar imediatamente bupropiona ou nortriptilina.","B":"Prescrever adesivos de nicotina e iniciar bupropiona uma semana antes da cessação.","C":"Tentar persuadir e agir com autoridade tendo em vista as comorbidades do paciente.","D":"Encaminhar para abordagem cognitivo comportamental e iniciar vareniclina somente após\ncessação total."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-259718","number":"259718","sourceNumber":"259718","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Médico plantonista é chamado durante a madrugada para examinar homem de 52\nanos, com história de dependência do álcool,\nque não consegue conciliar o sono. Está no segundo\ndia de internação em enfermaria de clínica médica, para tratamento de patologia gástrica. Ao\nexame, o médico identifica que o paciente está vígil, inquieto, com tremores, sudorético,\ntaquipneico e taquicárdico, com pressão arterial = 140 x 100 mmHg. Nessa situação, qual\nmedicação é a primeira opção de escolha?","options":{"A":"Zolpidem.","B":"Diazepam.","C":"Amitriptilina.","D":"Clorpromazina."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-259727","number":"259727","sourceNumber":"259727","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Idosa de 75 anos portadora de hipertensão arterial sistêmica, diabetes, dislipidemia,\nosteoartrose, depressão e osteoporose vem ao Posto\nde Saúde para atendimento médico com\nqueixa de insônia. Refere que dorme de 22 até 4 horas da manhã e durante o dia tem um cochilo\napós o almoço por volta de 13h até as 15 horas. É independente para atividades básicas de vida\ndiária e está em uso de: losartana 100mg/d, hidroclorotiazida 25mg/d, AAS 100mg/d, omeprazol\n20mg/d, glibenclamida 5mg/d, amitriptilina 10mg/d e bromazepan 3mg/d. Nega queixas e apresenta\nexame físico sem alterações. Relata 3 episódios de queda no último ano. Qual o ajuste\nfarmacológico prioritário para a paciente?","options":{"A":"Suspender gradualmente o bromazepam.","B":"Suspender gradualmente a amitriptilina.","C":"Aumentar a dose de amitriptilina.","D":"Aumentar dose do bromazepam."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-234024","number":"234024","sourceNumber":"234024","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Senhor de 70 anos, sem história de doença neuropsiquiátrica, deu entrada no serviço\nde emergência, no turno da noite, apresentando\ninquietação, certo entorpecimento da consciência,\nalteração do juízo da realidade com pseudopercepções e desorientação alopsíquica. A família\nrelata que o quadro se iniciou no dia anterior depois de episódios repetidos de diarreia e que,\ndurante o dia, fica mais prostrado. Neste caso, qual é a intervenção psicofarmacológica sintomática\nde primeira escolha?","options":{"A":"Clozapina.","B":"Aripiprazol.","C":"Haloperidol.","D":"Clorpromazina."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-234067","number":"234067","sourceNumber":"234067","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente, sexo masculino, frentista, 45 anos, casado, procura UBS motivado pelas\nfaltas constantes ao trabalho. Diz que acorda\ntriste, sem vontade de sair da cama. Não tem ido\ntambém aos jogos de futebol do bairro, que antes frequentava semanalmente. Passa a maior parte\ndo dia dormindo. Relata perda de apetite e libido. Durante a consulta apresentou choro fácil. Refere\nque não faz uso de álcool e de outras drogas e não relata nenhum evento associado ao\naparecimento dos sintomas. Para realizar o diagnóstico é necessário considerar:","options":{"A":"Episódio depressivo e diferenciar do transtorno afetivo bipolar.","B":"Episódio depressivo relacionado ao trabalho com solventes.","C":"Transtorno de ansiedade generalizada.","D":"Episódio depressivo moderado."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-199751","number":"199751","sourceNumber":"199751","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher de 54 anos, médica, divorciada, apresentando atualmente episódio depressivo\ncom ideação suicida. É uma pessoa bastante\nperfeccionista e tem boa capacidade para fazer\napreciação da realidade. O pai fazia tratamento para depressão. Na avaliação do risco, quais, entre\nos dados clínicos e sociodemográficos da paciente, estão associados a uma taxa mais alta de\nsuicídio?","options":{"A":"Sexo e síndrome clínica.","B":"Idade e história familiar.","C":"Ocupação e personalidade.","D":"Estado civil e estilo cognitivo."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-199649","number":"199649","sourceNumber":"199649","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente, feminina, 48 anos, procura a unidade de atenção primária à saúde afirmando\nser tabagista há mais de 15 anos e que não\nconsegue parar de fumar. Fazia uso de 20 cigarros por\ndia e da última vez em que tentou parar, há cerca de 1 mês, apresentou forte crise de ansiedade,\nirritabilidade, inquietação e intensa vontade de fumar, tendo recaído ao padrão anterior de uso nas\nprimeiras 24 horas. Gostaria de parar de fumar definitivamente nos próximos 30 dias. Nas últimas\n48 horas tentou diminuir 2 cigarros por dia e decidiu procurar ajuda. Considerando os estágios de\nmudança de comportamento sugeridos no Modelo Transteórico de Prochaska e DiClemente (1992),\nqual seria o estágio em que melhor se enquadraria a paciente acima, nesse momento?","options":{"A":"Ação.","B":"Preparação.","C":"Contemplação.","D":"Pré-contemplação."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-199681","number":"199681","sourceNumber":"199681","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher, 40 anos, professora universitária, solteira, sem comorbidades ou antecedentes\npatológicos, compareceu sozinha para consulta médica em unidade básica de saúde com queixa\nde intenso sentimento de medo que tem prejudicado sua vida profissional. A paciente refere que\nsente medo de ser julgada pelos alunos quando fala em público nas aulas, e, por isso, já faltou ao\ntrabalho. O medo vem se intensificando ao longo do último ano, fazendo com que ela prefira ficar\nem casa, onde se sente bem. Nega outros sintomas. Qual o diagnóstico mais adequado para o\ncaso?","options":{"A":"Agorafobia.","B":"Fobia social.","C":"Transtorno de pânico.","D":"Transtorno de ansiedade generalizada."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-173001","number":"173001","sourceNumber":"173001","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Idoso, de 84 anos, há 3 dias com febre, dor e inchaço articular em mãos, ombros, pés e\njoelhos. Foi levado à emergência de um hospital, medicado com dipirona e deixado em observação.\nNo dia seguinte, estava sonolento e com comportamento sugestivo de alucinações. Realizada\ncontenção física no leito e horas depois evoluiu com agitação psicomotora. Qual a melhor opção\npara investigação diagnóstica e tratamento, desse paciente?","options":{"A":"Providenciar exames de bioquímica, rastreio infeccioso e considerar uso de antipsicótico.","B":"Solicitar exame de neuroimagem, parecer da psiquiatria e iniciar antipsicótico.","C":"Pedir exame de neuroimagem e iniciar inibidor de acetilcolinesterase.","D":"Realizar coleta de liquor e iniciar imunoglobulina."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-173011","number":"173011","sourceNumber":"173011","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem de 35 anos, há cerca de três meses, apresenta perda de peso, fadiga, choro\nfácil, diminuição do interesse em atividades\nantes prazerosas, angústia, sentimento de fracasso e\nculpa, indecisão, falta de concentração. Em uma Unidade de Pronto Atendimento (UPA), foi\nprescrito paroxetina ? 20 mg/dia, e agendada consulta em ambulatório de seguimento na atenção\nprimária, no prazo de duas semanas. Compareceu ao primeiro atendimento ambulatorial referindo\nestar usando a medicação, mas que não estava satisfeito com o resultado. A esposa, presente à\nconsulta, disse que notou que ele estava menos angustiado e as crises de choro diminuíram. Qual\na conduta indicada em relação ao manejo da medicação, a partir dessa consulta ambulatorial?","options":{"A":"Trocar por venlafaxina ? 75 mg/dia.","B":"Acrescentar alprazolam ? 0,5 mg/dia.","C":"Manter a paroxetina na mesma dose.","D":"Aumentar a dose da paroxetina para 40 mg/dia."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-173032","number":"173032","sourceNumber":"173032","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Criança de 10 anos, do sexo masculino, é trazida à consulta por estar apresentando,\nrecentemente, sintomas variados. Os pais\ndescrevem crises de palpitação, sufocação, tonturas e\ntremores. Relatam que o filho manifesta medo de morrer. Qual condição psicológica é compatível\ncom esse quadro clínico?","options":{"A":"Transtorno de hiperatividade.","B":"Síndrome de Asperger.","C":"Transtorno de humor.","D":"Transtorno de pânico."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-172949","number":"172949","sourceNumber":"172949","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma paciente de 85 anos comparece à consulta com seu médico de família\nacompanhada por sua filha que relata que a\nmãe está agitada nas últimas 3 semanas, após\nmudança para casa da filha mais nova. Relata que ela conversa sozinha e não consegue dormir,\nmesmo com uso de diazepam 10 mg. Fica tranquila durante o dia, mas torna-se agitada no período\nnoturno. Apresenta-se independente para atividades de vida diária básica e instrumental. Pontuou\n15 no mini-mental sendo analfabeta. Nega doenças prévias e não fazia uso regular de medicações.\nOs sintomas vêm se intensificando nos últimos dias. Qual a principal hipótese diagnóstica?","options":{"A":"Delirium.","B":"Depressão psicótica.","C":"Doença de Alzheimer.","D":"Demência frontotemporal."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-173004","number":"173004","sourceNumber":"173004","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em visita puerperal, a equipe de saúde identificou quadro ansioso da paciente em\ndecorrência do marido \"estar bebendo\ndemais\" e deixá-la sozinha cuidando do bebê e da casa. Foi\nagendada conferência familiar, onde o paciente masculino, 32 anos, vendedor de carros, refere que\n\"bebia\" duas ou três doses de cachaça cerca de quatro a cinco vezes por semana, não tendo\nevidência de tolerância. Disse que se irritava com as críticas da mulher, mas que, no fundo,\n\nsentia-se culpado diante dela por beber ?um pouco além da conta?. Relata que é um hábito\nquando chega do trabalho no fim da tarde para\nrelaxar, e consegue controlar sua vontade, nunca\nbebendo pela manhã. Ao ser questionado, negou sintomas como tremores e alucinações, no\nmomento e nos períodos em que não faz uso de bebidas alcoólicas. Não apresentava história de\nconvulsões ou transtornos mentais atual ou pregressa. Após entrevista motivacional, o paciente\nrevelou: \"Amo muito minha esposa e gostaria de diminuir a bebida, pois sei que estou fazendo ela\nsofrer. Mas se for pra parar de beber de vez, vou pedir o divórcio\". O que deve constar no plano\nterapêutico singular do paciente?","options":{"A":"Orientar metas de abstinência.","B":"Iniciar tiamina e benzodiazepínico.","C":"Reduzir o uso de álcool com baixas expectativas.","D":"Solicitar exames laboratoriais e prescrever dissulfiram."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-173042","number":"173042","sourceNumber":"173042","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente masculino, 24 anos, agricultor, comparece a UBS na zona rural com queixa de\ndesânimo, que o tem impedido de trabalhar. Mora sozinho. Refere insônia e diminuição do apetite.\nRelata que o quadro se iniciou há 15 dias, após ter assumido sua bissexualidade para a família. Na\nconsulta, apresenta autoestima e autoconfiança reduzidas e revela à médica que o atendeu:\n\"Prefiro que Deus me leve. Tenho vontade de dormir e não acordar... Não sei como ainda, mas\nquando sair daqui estou pensando em me matar. Não aguento mais tanta dor. Nunca me senti\nassim\". A médica ainda tem sete pacientes para atender depois dele. Qual a conduta imediata para\na situação?","options":{"A":"Solicitar a ambulância específica do SAMU para saúde mental e encaminhar para avaliação em\nemergência no hospital mais próximo.","B":"Respeitar o sigilo do paciente e deixá-lo sozinho em um dos ambientes da UBS, aguardando\nconsulta mais detalhada ao fim do atendimento.","C":"Evitar falar novamente sobre suicídio com o paciente, nesse momento, e agendar visita\ndomiciliar com psicólogo do NASF para o dia seguinte.","D":"Pedir a um dos membros da equipe que permaneça junto do paciente, enquanto o ACS mobiliza\nrede de apoio disponível para o paciente."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-150843","number":"150843","sourceNumber":"150843","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher, 24 anos, trazida por familiares para atendimento na Unidade Básica de Saúde,\nrelata que vem com insônia, desânimo,\npreocupada com as condições financeiras da família. Tem\nchorado com frequência, perdeu o apetite e não vê graça em nada. Questionada sobre seus planos\npara o futuro, diz que não acredita mais que possa ter uma vida como antes e que nos últimos dias\njá esteve, mais de uma vez, prestes a pôr fim à vida tomando comprimidos. No momento da\nconsulta, diz que não está pensando em se matar, mas não descarta que essa ideia possa voltar a\nlhe ocorrer. Tendo em conta a avaliação do risco de suicídio, qual o encaminhamento indicado?","options":{"A":"Nunca deixá-la sozinha, medidas de proteção, realização de contrato de não suicídio e\nencaminhar para internação.","B":"Escuta acolhedora, medidas de proteção, abordagem psicofarmacológica e, caso não haja\nmelhora, encaminhar para profissional especializado.","C":"Escuta terapêutica, medidas de proteção, realização de contrato de não suicídio e encaminhar\npara o serviço de psiquiatria para avaliação e\nconduta ou agendar uma consulta o mais breve\npossível.","D":"Escuta acolhedora para compreensão e amenização do sofrimento, facilitar a vinculação do\nsujeito ao suporte e ajuda possível ao seu redor ? social e institucional e encaminhar para\npsicoterapia."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-127013","number":"127013","sourceNumber":"127013","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher, 35 anos, em consulta ambulatorial em unidade básica de saúde, queixa-se de\ndores frequentes nas costas, ocasionais períodos em que fica com falta de ar e tem tido cefaleia.\nTerminou relatando que dorme mal, é muito irritada, preocupada e se impressiona \"com tudo\".\n\nPassa períodos \"tão agoniada\" que não consegue trabalhar. O exame físico não revelou\nanormalidades. Ao completar a anamnese o\nmédico ficou sabendo que a paciente sempre se\nconsiderou \"nervosa\" e já tomou, de modo irregular, \"remédio controlado\". Apesar das queixas, não\ntem o hábito de procurar atendimento médico com muita frequência, nem tem a demanda insistente\npela realização de exames complementares. Qual o diagnóstico mais provável?","options":{"A":"Transtorno depressivo.","B":"Transtorno de ajustamento.","C":"Transtorno de somatização.","D":"Transtorno de ansiedade generalizada."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-126971","number":"126971","sourceNumber":"126971","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"João Luís, 35 anos, busca seu médico de família e comunidade para saber o que deve\nfazer para parar de fumar. Ele responsabiliza o uso do cigarro pela coloração amarelada de seus\ndentes, o que o deixa bastante envergonhado, já que trabalha na recepção de uma pousada. Por\noutro lado, refere sentir prazer ao fumar. Dentro da classificação de Prochaska e DiClemente, em\nqual estágio comportamental encontra-se esse paciente?","options":{"A":"Ação.","B":"Preparação.","C":"Contemplação.","D":"Pré-contemplação."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-102108","number":"102108","sourceNumber":"102108","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente de 55 anos foi levada à emergência com agitação psicomotora,\nheteroagressividade, alucinações auditivas e\ndelírios persecutórios. Levando em consideração a\nsegurança na manutenção dos níveis da pressão arterial e a eficácia no controle das manifestações\nclínicas, qual medicamento é o mais bem indicado em administração intramuscular?","options":{"A":"Diazepam.","B":"Haloperidol.","C":"Prometazina.","D":"Clorpromazina."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-102165","number":"102165","sourceNumber":"102165","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente masculino, 70 anos, procura-o no consultório com queixas de esquecimentos\nfrequentes (como o número da sua conta\nbancária ou de sua identidade) e distanciamento familiar\npor apatia e déficit de concentração, nas últimas duas semanas. Ao examiná-lo você identifica um\nindivíduo orientado no tempo e no espaço, capaz de recordar seus eventos do dia á dia e fatos\nrelevantes de sua história. Ao ser apresentada uma lista com cinco palavras simples, este é capaz\nde repeti-las imediatamente, após um minuto de concentração e após 10 minutos durante os quais\nele realizou outras tarefas. Esse contexto deve deixá-lo atento para qual diagnóstico mais\nprovável?","options":{"A":"Transtorno depressivo menor.","B":"Demência degenerativa de Pick.","C":"Tumor do lobo temporal medial.","D":"Infarto da artéria cerebral anterior."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-102115","number":"102115","sourceNumber":"102115","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A equipe da Unidade Básica de Saúde está recebendo adolescentes usuários de\ndrogas, e a equipe não está conseguindo conduzir, de forma adequada, os casos atendidos.\nDurante uma sessão de estudo sobre o tema, foi esclarecido que, durante o uso de drogas, o\nsistema de recompensa cerebral é ativado principalmente por neurotransmissores. Qual o\nprincipal neurotransmissor envolvido nesse caso?","options":{"A":"Dopamina.","B":"Serotonina.","C":"Acetilcolina.","D":"Noradrenalina."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-65722","number":"65722","sourceNumber":"65722","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma senhora de 54 anos, portadora de ansiedade generalizada, comparece para\nconsulta por intensa dificuldade de memória,\nredução da capacidade laboral e lentidão. Ela usa\nalprazolam há seis meses na dose de 4 mg por dia. Qual das medicações é a mais adequada ao\nseu tratamento?","options":{"A":"Naloxona.","B":"Fluoxetino.","C":"Nifedipina.","D":"Clonazepam.","E":"Flumazenil."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-65702","number":"65702","sourceNumber":"65702","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher de 35 anos comparece pela sexta vez, no intervalo de dois meses, à consulta\ncom seu médico de família e comunidade com\nqueixa de dor torácica em pontadas que piorava\ncom estresse emocional e melhorava com massagem local com cânfora. Havia abandonado o\nemprego como diarista, pois as dores eram intensas. A paciente apresentava, como histórico,\nqueixas de dor muscular generalizada, artralgias, dor torácica em pontadas, disúria, diarreia,\nsensação de plenitude gástrica, irregularidade menstrual, fraqueza de membros inferiores e\namnésias. Apresentou receitas médicas com prescrição de paracetamol, omeprazol e soro de\nreidratação oral. Os sintomas e sinais iniciaram-se há oito anos com piora progressiva. O exame\nclínico, os exames laboratoriais, o ECG e a radiografia de tórax não apresentavam alterações\ndignas de nota. Levou à consulta uma tomografia computadorizada de crânio (realizada após\nconsulta com neurologista através do plano de saúde, há três meses) considerada normal. Apesar\nde exames sem alterações, o médico ficou confuso e irritado, pois a paciente e sua família estavam\nem real sofrimento psíquico com o quadro e cobraram um ?diagnóstico e tratamento?. Qual a\nhipótese diagnóstica mais provável no caso acima?","options":{"A":"Conversão.","B":"Hipocondria.","C":"Somatização.","D":"Dismorfofobia.","E":"Transtorno factício."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-51247","number":"51247","sourceNumber":"51247","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher de 63 anos, viúva, do lar, procurou seu médico de família com queixa de\n\n?tristeza? que já se prolonga há três meses. Na anamnese, o médico constatou humor deprimido,\nfatigabilidade, ideias de culpa, perturbações do sono, apetite diminuído e autoestima reduzida. A\npaciente negou qualquer evento traumático nos últimos meses. Ao exame: Peso = 86 kg; 1,62\nmetros de altura; PA = 130 x 80 mmHg. Exame neurológico sem alterações. Mini exame do estado\nmental = 24. Com base nos critérios para diagnóstico de episódio depressivo do CID-10, qual o\nprovável diagnóstico e tratamento farmacológico para essa paciente?","options":{"A":"Depressão (episódio grave); antidepressivos tricíclicos.","B":"Depressão (episódio leve); inibidores de recaptação de serotonina.","C":"Depressão (episódio grave); inibidores de recaptação de serotonina.","D":"Depressão (episódio moderado); inibidores de recaptação de serotonina."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-51251","number":"51251","sourceNumber":"51251","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um médico de família e comunidade (MFC) trabalha em área de risco na periferia de\numa grande cidade, onde a violência urbana, o\ntráfico e o consumo de drogas são evidentes. O\ncrack é a substância psicoativa ilícita mais utilizada. Uma adolescente e morador de rua da área faz\nuso regular de crack há 3 anos. Fumou a última pedra de crack há 12 horas e procurou o médico\nna Unidade Básica de Saúde. Qual o provável estado mental do adolescente?","options":{"A":"Depressão e anorexia.","B":"Humor eutímico, anedonia, grande fissura pela droga.","C":"Euforia, sensação de aumento da força, aumento da autoestima, diminuição da fadiga.","D":"Perda da capacidade de julgamento, sentimento de grandiosidade, alucinações e extrema\nagitação psicomotora."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-51254","number":"51254","sourceNumber":"51254","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma mulher de 46 anos, casada, costureira, faz uso de diazepam (20 mg/dia),\ndiariamente, há 15 anos. A medicação foi\nprescrita no início em unidades de emergência e desde\nentão vem sendo utilizada pela paciente. A paciente não apresenta sinais e sintomas condizentes\ncom transtornos de ansiedade, mas refere não conseguir dormir sem o uso da medicação. Ao\nconsultar sua Médica de Família e Comunidade (MFC), ambas decidem pela retirada da\nmedicação. Qual deve ser a proposta terapêutica?","options":{"A":"Retirada gradual da droga e uso de flumazenil visando prevenir sintomas de abstinência.","B":"Encaminhamento ao psiquiatra, visto que a dose utilizada é alta e requer manuseio por\nespecialista.","C":"Retirada gradual da droga visando evitar a precipitação de delírio, muitas vezes com sintomas\npsicóticos.","D":"Retirada abrupta da droga, pois estudos demonstram que a retirada gradual aumenta a\npossibilidade de recaídas."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-141598","number":"141598","sourceNumber":"141598","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A intoxicação por uso de cocaína é frequente em nosso meio. Qual das alternativas\nabaixo corresponde apresentação clínica e\ncomplicações, respectivamente?","options":{"A":"Síndrome hipoativa; midríase, hipertensão.","B":"Síndrome anticolinérgica; sudorese intensa.","C":"Síndrome colinérgica; insuficiência respiratória.","D":"Síndrome adrenérgica; arritmias, crise convulsiva e infarto agudo do miocárdio."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-37606","number":"37606","sourceNumber":"37606","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Dentre as causas reversíveis de demência é possível citar as relacionadas abaixo,\nexceto:","options":{"A":"medicamentosa.","B":"metabólica.","C":"endócrina.","D":"vascular."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-37635","number":"37635","sourceNumber":"37635","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Rafael e Josiane são casados e vivem com os filhos Gustavo e Livia na Barra do Ceará.\nA família é acompanhada pela equipe de saúde\nda família. Ao realizar estudo de família, Dra Tânia\nobservou que o casal apresentava dificuldade de comunicação e clima hostil, com certa dificuldade\nem tratar os sentimentos. A família vem passando por dificuldades financeiras importantes. Rafael\ntrabalha como autônomo e a violência urbana o tem impedido de sair para trabalhar nos últimos\ndias. Apesar da dificuldade de comunicação, a divisão de poder entre o casal é equânime. Josiane\ncuida da casa e das crianças e Rafael busca o sustento. Apesar das dificuldades, o casal propôs\nfabricar e vender desinfetantes para melhorar a renda. Josiane e Rafael demonstraram o\nentendimento de que cada um é uma pessoa separada, que pensa e tem sofrimentos, mas,\napresentaram dificuldade em demonstrar esses sentimentos um para o outro. São parâmetros da\ndinâmica familiar, exceto:","options":{"A":"família com filhos pequenos.","B":"expressão e manejo dos sentimentos.","C":"capacidade de lidar com perdas e mudanças.","D":"capacidade de autonomia e intimidade."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-30872","number":"30872","sourceNumber":"30872","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Adolescente com sintomas de falta de apetite, sonolência e desânimo vem recebendo\ntratamento medicamentoso e passou a apresentar\nrigidez muscular grave, hipertermia (temperatura\naxilar: 39,5°C), sudorese abundante, tremores e disfagia. Esses sintomas devem-se,\nprovavelmente, a que interação medicamentosa?","options":{"A":"Fluoxetina e fenelzina.","B":"Sertralina e imipramina.","C":"Risperidona e metilfenidato.","D":"Venlafaxina e sibutramina.","E":"Carbonato de lítio e anfetamina."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-30884","number":"30884","sourceNumber":"30884","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Qual dos itens abaixo representa um fator de risco para \"delirium\" no idoso durante\ninternamento hospitalar?","options":{"A":"Uso de dipirona.","B":"Sexo feminino.","C":"Hipertensão arterial sistêmica.","D":"Sonda vesical de demora.","E":"Obesidade."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-37048","number":"37048","sourceNumber":"37048","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A ingestão de duas a três doses de uísque resulta em uma concentração sérica de\nálcool entre 20 e 30 mg/dl. Em indivíduos sem\ntolerância, assinale a opção que descreve a relação\ncorreta entre concentração sérica e sintomas.","options":{"A":"20 mg/dl ? sem qualquer manifestação.","B":"80 mg/dl ? redução de funções cognitivas\ncomplexas e performance motora.","C":"400 mg/dl ? alterações óbvias da fala,\nmotricidade, do comportamento e do\njulgamento.","D":"600 mg/dl ? coma leve e depressão dos sinais\nvitais."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-27693","number":"27693","sourceNumber":"27693","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Jovem de 17 anos, sexo feminino, é trazida ao ambulatório de Clínica Médica pelos\npais. A queixa é de comportamento 'fora\ndos padrões' e solicitam investigação adequada. Referem\nque há cerca de dois anos a mesma apresenta hábitos alimentares aberrantes, chegando a comer\n'10 pacotes de batatas fritas e incontáveis biscoitos e bombons de chocolate' em um dia. Após este\n'dia de farra de comida' (referência dada pelos pais), passa de dois a três dias em intensa\natividade\nfísica na academia de musculação - com sessões de 6 a 8 horas diárias - sem alimentar-se ou\ningerir líquidos adequadamente. Esses ciclos alternantes vêm se repetindo 2 a 3 vezes por semana\npor pelo menos 6 meses. Durante entrevista, a paciente confirmou as informações dadas pelos pais\ne referiu que come exagerado por perder o controle, mas que sente-se extremamente infeliz após\ntais episódios. Relata que se acha um pouco acima do peso, mas nega indução de vômitos ou uso\nde laxantes em qualquer época. Nega alucinações visuais ou auditivas. A avaliação mostrou plena\norientação pessoal, temporal e espacial; o índice de massa corpórea era de 26 kg/m²; as mucosas\nestavam levemente ressecadas; demais aspectos do exame físico estavam normais. Foi realizada\navaliação bioquímica que não demonstrou alterações. Com base nestes dados, qual o diagnóstico\nmais provável?","options":{"A":"Esquizofrenia.","B":"Compulsão alimentar.","C":"Anorexia nervosa.","D":"Bulimia nervosa.","E":"Depressão."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-29471","number":"29471","sourceNumber":"29471","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Alice, 23 anos, estudante de medicina, apresentou quadro de sudorese, dispneia,\npalpitações durante o acompanhamento de consultas\nambulatórias em seu estágio na Unidade de\nSaúde da Família. Foi escutada e avaliada clinicamente por sua preceptora que não encontrou\nalterações no exame clínico. Alice não consome excessivamente cafeína, não faz uso de álcool e\nsubstâncias psicoativas. Posteriormente realizou exames bioquímicos necessários e ECG que não\nevidenciaram alterações. Alice relatou estar muito preocupada com provas. O transtorno do pânico\né um diagnóstico provável para Alice. Baseando-se no caso acima e em seus conhecimentos\nassinale a alternativa errada:","options":{"A":"Alice deve ser imediatamente encaminhada ao psiquiatra, pois transtornos de ansiedade não\ndevem ser conduzidos inicialmente pelo médico\nde família;","B":"Psicoterapia psico-comportamental mostra-se efetiva no caso de Alice;","C":"Os inibidores seletivos da recaptação de serotonina mostram-se efetivos e com eficácia mais ou\nmenos comprovada;","D":"O tratamento do transtorno do pânico deve ser longo, uma vez que recaídas e recidivas são\nmuito comuns e contribuem para cronicidade."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-29474","number":"29474","sourceNumber":"29474","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Leia atenciosamente o caso abaixo para responder a questão: Ana Lúcia, 36 anos,\ncasada, procurou seu médico de família com\nqueixa de humor deprimido, perda de interesse em\natividades anteriormente prazerosas, fatigabilidade, ideias de culpa, inutilidade. Quando\nquestionada sobre o futuro, referiu extremo pessimismo, pois não se julgava apta a continuar\nlecionando Literatura (seu ofício há 12 anos) e, por isso, nutria excessiva culpa. Relatou também\nalteração do sono e perda do apetite. Ana Lúcia refere episódio depressivo anterior aos 18 anos.\nSeu pai apresenta história de transtorno bipolar e sua mãe transtorno de ansiedade generalizada.\nDr. Fabrício, médico de família e comunidade, ao abordar integralmente o caso de Ana Lúcia, deve\nlevar em consideração, como pilares da abordagem à depressão, exceto:","options":{"A":"O diagnóstico de depressão é um importante fator de risco para o suicídio;","B":"A presença de risco de suicídio em um paciente deprimido é considerada uma indicação de\ninternação psiquiátrica quando estiver associado à psicose;","C":"A presença de risco de suicídio em um paciente deprimido é considerada uma indicação de\ninternação psiquiátrica quando estiver associado à ausência de suporte social;","D":"A presença de sintomas fundamentais para o diagnóstico da depressão exclui a possibilidade de\no episódio depressivo ser um sintoma de uma\ndoença médica associada ou o efeito colateral de\nmedicamentos."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-24316","number":"24316","sourceNumber":"24316","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Qual dos seguintes itens é característico da overdose por cocaína?","options":{"A":"Arreflexia","B":"Hipertermia","C":"Hipotensão","D":"Miose"},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-13394","number":"13394","sourceNumber":"13394","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Igor Daniel, 8 anos de idade, não vai à escola só, precisa ser acompanhado.\nComumente refere dores abdominais estomacais e\nsevera dor de cabeça. Sua mãe com frequência\nprecisa retirá--lo do colégio devido a estas queixas. À noite deseja dormir na cama com seus pais.\nQuando é levado para o seu dormitório, informa que não pode ficar sozinho, pois há monstros em\nseu guarda roupa. Qual das situações clínicas melhor explica o quadro clínico acima?","options":{"A":"Esquizofrenia.","B":"O relato é normal para a faixa etária.","C":"A criança é ansiosa e portadora de ansiedade de separação.","D":"Trata--se de desordem de socialização infantil.","E":"Psicose simbiótica."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-9075","number":"9075","sourceNumber":"9075","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sr. Pedro, 82 anos, procurou seu médico de família com escoriações em mmii e\nhematoma em face após episódio de queda no\nbanheiro de sua casa. Sr. Pedro vive com Dona\nLourdes, 80 anos, 1 filha viúva de 56 anos e 2 netas. Veio à consulta acompanhado pela filha, ela\nrelatou que Dona Lourdes também caíra 2 vezes no último mês. Em relação à queda em pacientes\nidosos, assinale a alternativa INCORRETA:","options":{"A":"As quedas representam sério problema para idosos e estão associadas a elevada morbidade.","B":"As quedas em idosos estão relacionadas ao aumento do número de institucionalizações\nprecoces.","C":"O médico de família deve restringir ao máximo as atividades de Sr. Pedro.","D":"Escadas, tapetes, calçados inadequados são causadores frequentes de quedas."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-9079","number":"9079","sourceNumber":"9079","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sr. Pedro, 82 anos, procurou seu médico de família com escoriações em mmii e\nhematoma em face após episódio de queda no\nbanheiro de sua casa. Sr. Pedro vive com Dona\nLourdes, 80 anos, 1 filha viúva de 56 anos e 2 netas. Veio à consulta acompanhado pela filha, ela\nrelatou que Dona Lourdes também caíra 2 vezes no último mês. O médico de família avaliou a\natividade funcional de Sr. Pedro através da investigação das atividades de vida diária básicas. São\nAVDs básicas, EXCETO:","options":{"A":"Vestir-se.","B":"Banhar-se.","C":"Ir ao banheiro.","D":"Usar o telefone."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-13431","number":"13431","sourceNumber":"13431","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em pacientes tratados com Lítio, os seguintes devem ser monitorados, EXCETO:","options":{"A":"TSH.","B":"Creatinina sérica.","C":"Lítio.","D":"Plaquetas.","E":"Frequência cardíaca."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-349736","number":"349736","sourceNumber":"349736","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre delirium tremens, assinale a alternativa correta.","options":{"A":"Contenção mecânica imediata e administração de haloperidol intramuscular fazem parte do\nmanejo. O uso de benzodiazepínicos é contraindicado devido ao risco de piora aguda do delirium\ntremens.","B":"O uso de fenitoína parenteral, a \"\"hidantalização\"\", deve ser feito de rotina, sendo eficaz no\ncontrole de crises convulsivas.","C":"Monitorar, corrigir possíveis distúrbios hidroeletrolíticos, realizar hidratação vigorosa,\niniciar\nbenzodiazepínico e profilaxia para encefalopatia de Wernicke-Korsakoff podem ser ações\nnecessárias para o manejo adequado.","D":"A administração de clorpromazina e outros neurolépticos sedativos de baixa potência para\ncontrole de agitação são a primeira escolha em relação ao uso de haloperidol.","E":"As manifestações geralmente ocorrem antes das primeiras vinte e quatro horas após a última\ningesta de bebida alcóolica."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-365650","number":"365650","sourceNumber":"365650","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um paciente de 38 anos de idade, tabagista há 18 anos, fumando 30 cigarros por dia\n(equivalentes a 1,5 maço), procurou atendimento para orientações acerca de cessação do\ntabagismo após falecimento do pai, também tabagista, por câncer de pulmão. No tratamento a ser\nindicado a esse paciente, pode-se utilizar","options":{"A":"diazepam.","B":"naloxone.","C":"bupropiona.","D":"amitriptilina."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-322176","number":"322176","sourceNumber":"322176","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Os pais de uma adolescente relatam ao seu pediatra, na ausência da paciente, que\nestão percebendo que ela tem mudado o\ncomportamento alimentar. Viram, por diversas vezes, que\nestava comendo escondida, muito rapidamente e em grandes quantidades. Referem que ela tem\nvergonha quando é vista nessa situação, que demonstra tristeza após alimentar-se e que, muito\nfrequentemente, come até se sentir desconfortável. Das seguintes condições, qual é a mais\nprovável, baseando-se apenas no relato dos pais?","options":{"A":"Anorexia nervosa.","B":"Bulimia.","C":"Transtorno alimentar restritivo evitativo.","D":"Compulsão alimentar.","E":"Ortorexia."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-322208","number":"322208","sourceNumber":"322208","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Dona Elisa, 50 anos, portadora de transtorno bipolar, retornou para consulta na UBS\ncom exames laboratoriais relacionados à\ntireoide alterados após iniciar o uso de medicamento.\nNesse caso, o médico da família deve então reavaliar o uso de","options":{"A":"carbonato de lítio.","B":"carbamazepina.","C":"divalproato de sódio.","D":"fumarato de quetiapina.","E":"haloperidol."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-305300","number":"305300","sourceNumber":"305300","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um homem de 62 anos está internado há 2 dias devido à fratura de pé D. Possui\nhistórico de consumo de bebida alcoólica em\ngrande quantidade, principalmente destilados.\nApresenta agitação importante, tremores, febre baixa e taquicardia, além de delírios audiovisuais.\nEm relação ao tratamento medicamentoso da abstinência alcoólica, assinale a melhor alternativa\nnesse caso.","options":{"A":"Diazepam 10mg endovenoso (EV).","B":"Midazolam 10mg intramuscular (IM).","C":"Haloperidol 5mg EV.","D":"Haloperidol 5mg IM.","E":"Clorpromazina 25mg IM."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-261247","number":"261247","sourceNumber":"261247","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma paciente de 54 anos de idade, usuária de mirtazapina 30 mg por dia, vem\napresentando importante aumento de peso. Durante\na evolução do seu peso, tem sentido dor\nabdominal em hipocôndrio direito, mal-estar, náuseas e vômitos. Realizou exames que\nidentificaram transaminases hepáticas quatro vezes acima do limite da normalidade, além de uma\nglicemia de jejum = 116 mg/dL. Levantou-se a hipótese de esteato-hepatite não alcoólica.\n\nConsiderando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir.\nMirtazapina é um medicamento seletivo da receptação da serotonina, que apresenta ganho de\npeso como efeito colateral.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-261313","number":"261313","sourceNumber":"261313","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Certo estudo acompanhou pacientes tabagistas que desejavam parar de fumar e que\nfizeram uso de medicamento como método auxiliar, e também pacientes tabagistas que desejavam\nparar de fumar e que não fizeram uso de medicamento, observando-se, posteriormente, os\nresultados de sucesso, ou não, na cessação do tabagismo nos dois grupos. Acerca desse caso e\ntendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. O uso de\nmedicamentos na cessação do tabagismo tem importância para minimizar os sintomas da\nabstinência. Entre os medicamentos oferecidos pelo Ministério da Saúde na rede pública, estão o\ncloridrato de bupropiona e a vareniclina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-261314","number":"261314","sourceNumber":"261314","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Certo estudo acompanhou pacientes tabagistas que desejavam parar de fumar e que\nfizeram uso de medicamento como método auxiliar, e também pacientes tabagistas que desejavam\nparar de fumar e que não fizeram uso de medicamento, observando-se, posteriormente, os\nresultados de sucesso, ou não, na cessação do tabagismo nos dois grupos. Acerca desse caso e\ntendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. Uma das dificuldades\nencontradas ao tentar cessar o tabagismo é a chamada \"fissura\", que consiste na grande vontade\nde fumar, com duração, geralmente, de até cinco minutos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-255782","number":"255782","sourceNumber":"255782","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"No que se refere aos conhecimentos relacionados a bioética, saúde mental,\nendocrinologia, dermatologia e cardiologia, julgue o\nitem a seguir. Epilepsia é uma contraindicação\nabsoluta para o uso de terapia de reposição de nicotina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-255783","number":"255783","sourceNumber":"255783","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"No que se refere aos conhecimentos relacionados a bioética, saúde mental,\nendocrinologia, dermatologia e cardiologia, julgue o\nitem a seguir. O dissulfiram e a naltrexona\nestão entre as opções farmacológicas para tratamento do alcoolismo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-214351","number":"214351","sourceNumber":"214351","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um paciente de 58 anos de idade, negro, chega à emergência levado pela esposa por\nestar sonolento, queixando-se de cefaleia de\nforte intensidade, fadiga e episódios de náuseas\nseguidos de vômito de forte intensidade. A esposa relata que os sintomas se iniciaram no dia e vêm\napresentando piora progressiva. Nega queixas de dor torácica e (ou) precordial, e também nega\nqueixas álgicas abdominais. O paciente refere quadro prévio de hipertensão arterial e está em uso\nde anti-hipertensivos. A esposa relata que ele se queixa de episódios frequentes de cefaleia no\núltimo ano e que tem estado \"muito estranho\" nos últimos três meses, apresentando ações\ninconsequentes até nas pequenas decisões diárias. Ao exame, apresenta-se em estado geral\nregular, acordado e conversando, porém com aspecto sonolento, ventilando espontaneamente em\nar ambiente. Apresenta ausculta cardíaca e pulmonar sem particularidades. Sinais vitais: FC = 58\nbpm; FR = 22 irpm; PA = 190 mmHg x 125 mmHg; SatO? = 97%; e temperatura axilar (Tax) = 38,6\n\n°C. Acerca desse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. Se as alterações comportamentais forem de caráter insidioso, de aumento progressivo e\nacompanhadas de sintomas físicos, devem- se excluir alterações de origem orgânica antes de se\npensar em um diagnóstico psiquiátrico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-196664","number":"196664","sourceNumber":"196664","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma paciente de 62 anos de idade, branca, com histórico de hipertensão arterial\nsistêmica, diabetes mellitus, sedentarismo,\nobesidade e depressão, e que faz uso de metformina,\ngliclazida, enalapril, hidroclorotiazida, sertralina e diazepam, vai a consulta de rotina. A\nrespeito\ndesse caso clínico e com base nos conhecimentos de saúde do idoso, julgue o ítem a seguir. A\ndepressão em pacientes idosos frequentemente se apresenta com quadros clínicos atípicos, com\nbase principalmente em queixas de sintomas psicossomáticos, como alterações de apetite,\nalterações de sono, fadiga e diminuição da concentração.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-179178","number":"179178","sourceNumber":"179178","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O transtorno psiquiátrico mais importante e frequente relacionado ao suicídio é o(a):","options":{"A":"Transtorno orgânico mental.","B":"Transtorno por uso de substância psicoativa.","C":"Transtorno do humor.","D":"Transtorno de personalidade.","E":"Esquizofrenia."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-179175","number":"179175","sourceNumber":"179175","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"De acordo com o Conselho Federal de Medicina , todos os anos, são registrados cerca\nde dez mil suicídios no Brasil e um milhão\nem todo mundo, havendo muitos mitos em relação a\nesse tema. Acerca do suicídio, assinale a alternativa correta.","options":{"A":"O suicídio é uma decisão individual, já que cada um tem pleno direito de exercitar seu livre\narbítrio.","B":"Quando uma pessoa pensa em se suicidar, terá risco de suicídio para o resto da vida.","C":"Falar sobre suicídio não aumenta o risco, pois pode aliviar a angústia e a tensão que esses\npensamentos trazem.","D":"As pessoas que ameaçam se matar não o farão, pois querem apenas chamar a atenção.","E":"Quando um indivíduo mostra sinais de melhora ou sobrevive a uma tentativa de suicídio, está\nfora de perigo."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-179180","number":"179180","sourceNumber":"179180","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Os dois principais fatores de risco do suicídio são","options":{"A":"idade e gênero.","B":"doença mental e tentativa prévia de suicídio.","C":"histórico familiar e genético de suicídio.","D":"doenças clínicas não psiquiátricas e eventos adversos na infância e na adolescência.","E":"doenças clínicas não psiquiátricas e história genética de suicídio."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-177595","number":"177595","sourceNumber":"177595","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"R.D.T., sexo masculino, de 32 anos de idade, comparece ao serviço de clínica médica\npor encaminhamento, após consulta recente em pronto\natendimento do mesmo hospital, na qual se\nqueixou de dispneia, de tosse não produtiva e de febre ocasional há 4 semanas. A saturação de\noxigênio é de 89%. Ele apresenta radiografia de tórax com infiltrado intersticial difuso e algumas\npneumotaceles, sem outras alterações. Ao consultar os exames laboratoriais realizados, verifica-se\num anti-HIV positivo, ainda sem exame confirmatório. O paciente refere sexo sem preservativo com\nalguma frequência, tendo apenas parceiros sexuais masculinos. Realizada a hipótese diagnóstica\nde pneumonia por Pneumocystis jiroveci, opta-se pelo tratamento em internação hospitalar. O\npaciente mostra-se muito resistente a aceitar a internação pois não deseja que sua família\ndescubra o HIV ou suspeite de sua homossexualidade. Com base nessa situação, julgue o item a\nseguir. A população LGBT apresenta, em diversos estudos, prevalência de transtornos psiquiátricos\nsuperior à população geral, sendo que se advoga que esse fator está relacionado com a frequente\ndiscriminação sofrida por esse grupo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-177599","number":"177599","sourceNumber":"177599","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"R.D.T., sexo masculino, de 32 anos de idade, comparece ao serviço de clínica médica\npor encaminhamento, após consulta recente em pronto\natendimento do mesmo hospital, na qual se\nqueixou de dispneia, de tosse não produtiva e de febre ocasional há 4 semanas. A saturação de\noxigênio é de 89%. Ele apresenta radiografia de tórax com infiltrado intersticial difuso e algumas\npneumatoceles, sem outras alterações. Ao consultar os exames laboratoriais realizados, verifica-se\num anti-HIV positivo, ainda sem exame confirmatório. O paciente refere sexo sem preservativo com\nalguma frequência, tendo apenas parceiros sexuais masculinos. Realizada a hipótese diagnóstica\nde pneumonia por Pneumocystis jiroveci, opta-se pelo tratamento em internação hospitalar. O\npaciente mostra-se muito resistente a aceitar a internação pois não deseja que sua família\ndescubra o HIV ou suspeite de sua homossexualidade. Com base nessa situação, julgue o item a\nseguir. O abuso de substâncias é fator importante a ser abordado durante consultas médicas da\npopulação LGBT, em razão da maior prevalência nessa população que na população geral.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-177643","number":"177643","sourceNumber":"177643","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"No contexto da Atenção Primária à Saúde, eventualmente, encontram-se prontuários\nque relatam todo o curso de vida de certo\npaciente, desde o período gestacional até a idade adulta,\nincluindo-se o período reprodutivo. Suponha que o M.S.F., atualmente com 28 anos de idade, foi\nacompanhada, no posto de saúde, durante toda a sua vida, desde a própria gestação da qual foi\nfruto. Ao longo de sua vida, várias estratégias de prevenção e programas de rastreamento foram\nefetuados e, eventualmente, continuarão sendo utilizados ao longo de seu envelhecimento. A\npaciente é sexualmente ativa, solteira, negra, com dois filhos (2 e 4 anos de idade), secretária,\nnão\ntabagista, não etilista, fisicamente ativa, com IMC = 22,5 e PA = 125 mmHg x 70 mmHg na última\nconsulta. A respeito dessas estratégias e desses programas e considerando as recomendações\ndos Cadernos de Atenção Básica do Ministério da Saúde, julgue o item a seguir. Deve-se rastrear o\ntabagismo, no mínimo, anualmente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-177696","number":"177696","sourceNumber":"177696","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O escopo da abordagem comunitária do médico de família foge do completo isolamento\ndo consultório médico, envolvendo, também, ações\nde modificação do ambiente da comunidade,\nvisando à promoção da qualidade de vida e à prevenção de doenças da população. Considerando\nesse contexto, Rafael, residente do 2º ano de medicina de família e comunidade, procurou auxílio\nda prefeitura para implantar um programa de incentivo à atividade física, na área geográfica de sua\natuação, o qual incluía a revitalização da praça próxima ao posto, a implantação de academia ao ar\nlivre e a pista de caminhada. Três vezes por semana, Rafael investia a 1ª hora de sua manhã\norganizando um grupo de caminhada e orientando a população na prática de exercícios físicos.\n\nConsiderando a situação hipotética apresentada e os conhecimentos médicos correlatos, julgue o\nitem a seguir. Além da prevenção de doenças, o exercício físico é parte integrante do tratamento de\ndiversas patologias psiquiátricas, como depressão e ansiedade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-140743","number":"140743","sourceNumber":"140743","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Julgue o próximo item, relativo à distimia. Pacientes com distimia apresentam, além do\nhumor depressivo, dois ou mais dos seguintes sintomas: perda (ou excesso) de apetite, insônia (ou\nhipersônia), redução de energia (ou fadiga), baixa autoestima, dificuldade de concentração e de\ntomada de decisões, sentimento de desesperança e desamparo, pessimismo em relação ao futuro,\nretraimento social e diminuição do interesse por atividades prazerosas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-140645","number":"140645","sourceNumber":"140645","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Julgue o próximo item, relativo à distimia. A distimia é caracterizada como um\ntranstorno depressivo crônico, com menor\nintensidade de sintomas comparada às depressões\nmaiores; e surge de forma insidiosa, na maioria dos casos antes dos vinte e cinco anos de idade,\ntendo duração de pelo menos dois anos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-105567","number":"105567","sourceNumber":"105567","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A população acima de 65 anos de idade vem aumentando em nossa pirâmide\nsociodemográfica e obriga os clínicos a\nadequarem-se para atendê-la, observando os critérios de\nbom atendimento. Além do exame neurológico completo, é necessário que se avalie também\nalguns aspectos psicológicos, para que se faça o encaminhamento devido, quando detectado\nalgum sinal de demência ou depressão, que são achados frequentes nessa faixa etária. Alguns\nquestionários padronizados estão disponíveis para uso e devem ser aplicados sempre nesses\nindivíduos. Um deles é a Escala de Depressão Geriátrica - forma curta, com quinze itens, que vem\nsendo usada há cerca de três décadas. Um dos itens dessa escala é:","options":{"A":"Você acha que é maravilhoso estar vivo agora?","B":"Você assiste à TV todos os dias?","C":"Você pratica jogos de tabuleiro com frequência?","D":"Você se alimenta sozinho?","E":"Você sabe que dia é hoje?"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-105559","number":"105559","sourceNumber":"105559","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O abuso de drogas em nosso meio é muito comum. Ocorre em qualquer classe social,\nentre homens e mulheres, usando drogas lícitas, como álcool e tabaco, ou ilícitas, como cocaína e\nLSD. Problema de saúde pública deve ser conduzido segundo os protocolos clínicos. A\ndiferenciação entre os vários estados por elas causados deve ser bem conhecida. Um deles é a\ndiferenciação entre o abuso e a dependência. Em relação ao álcool, assinale a alternativa que\napresenta uma das características de abuso e não de dependência:","options":{"A":"Sintomas de abstinência e maior tolerância.","B":"Inabilidade para cumprir tarefas do trabalho ou da escola.","C":"Ingestão de altas quantidades por tempo maior que o intencionado.","D":"Maior parte do tempo diário despendido para se recuperar dos efeitos provocados, na maioria\ndos dias do mês.","E":"Redução crescente das atividades sociais e recreativas."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-108223","number":"108223","sourceNumber":"108223","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"No que se refere ao tratamento indicado para a redução da dependência do consumo\nde álcool e aos efeitos biológicos causados\npelo etanol no organismo, julgue o item subsecutivo. O\nacamprosato é um fármaco de efeito aversivo, utilizado no tratamento da dependência do álcool,\ncuja função é diminuir, por meio da liberação das endorfinas e consequente bloqueio da liberação\nde dopamina, o prazer que a bebida proporciona ao dependente.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-108226","number":"108226","sourceNumber":"108226","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"No que se refere ao tratamento indicado para a redução da dependência do consumo\nde álcool e aos efeitos biológicos causados\npelo etanol no organismo, julgue o item subsecutivo. O\netanol interfere em macromoléculas celulares, em ácidos nucleicos e na cascata de sinalização\nintracelular e extracelular, altera as mitocôndrias e produz dano no retículo endoplasmático, no\nDNA e nos ribossomos.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-82106","number":"82106","sourceNumber":"82106","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Acerca dos sinais e sintomas do uso de drogas, julgue o item a seguir: pupilas\ndilatadas, taquicardia, hipertensão e hipertermia indicam a possibilidade do uso abusivo de\ncocaína.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-8590","number":"8590","sourceNumber":"8590","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem de 72 anos de idade acompanhado de sua esposa procura assistência médica\ncom queixa de ?perda de memória?. Refere que\nguarda as chaves do carro e não se recorda\ndepois do local, tem dificuldade de aprender novas tarefas, como usar o celular que ganhou do filho\ne que, às vezes, durante conversa não consegue lembrar-se do nome de pessoas sobre a quais\ngostaria de tecer um comentário. A esposa não tem observado dificuldades no dia a dia do paciente\ne refere que ele continua desempenhando suas tarefas como antes. Quanto ao caso clínico é\ncorreto afirmar que: (MEEM = Miniexame do Estado Mental)","options":{"A":"trata-se de um caso de demência em sua fase precoce.","B":"o MEEM é fundamental para o diagnóstico de demência nessa situação.","C":"a ausência de perda funcional torna improvável o diagnóstico de demência.","D":"é necessária a realização de um exame de imagem para definição diagnóstica.","E":"definitivamente não se trata de um caso de demência."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-307101","number":"307101","sourceNumber":"307101","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um paciente de 43 anos de idade compareceu ao atendimento do pronto-socorro às\n3h30 da manhã, relatando dificuldade para\ndormir e que vem apresentando perda da vontade de\nfazer as coisas, pensamento lentificado, com latência maior de resposta e sensação de ?brancos?,\nbem como perda da vontade sexual. Relata que o irmão gêmeo morreu na pandemia de Covid-19,\nna segunda ?onda?, e que, desde então, vem pensando que não vale a pena viver. Foi indicado\ndiazepan no dia para auxiliar no sono e alprazolan XR para casa. Após duas semanas, o\nplantonista atendeu um caso de autoextermínio com êxito, em outro hospital no qual trabalha,\nidentificando o paciente atendido anteriormente. A respeito desse caso clínico, assinale a\nalternativa correta.","options":{"A":"No primeiro atendimento, faltou focar na qualidade de vida e solicitar que o paciente saísse\nmais,\ndesfrutando da companhia de amigos e tomando alguns drinques.","B":"Nesse caso, ficou muito evidente a falta de apoio familiar que, com a morte do irmão, piorou o\nquadro, o qual poderia ter sido amenizado com apoio espiritual.","C":"No primeiro atendimento, o paciente deveria ter sido encaminhado para a psicoterapia cognitiva\ne comportamental.","D":"No lugar do benzodiazepínico alprazolan, deveria ter deixado o diazepan de horário para\nmantê-lo tranquilo nessa fase.","E":"Uma boa opção, nesse caso, seria encaminhar o paciente para a psiquiatria e iniciar um\nantidepressivo. Se possível, chamar alguém próximo e criar um vínculo empático com o paciente."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-274589","number":"274589","sourceNumber":"274589","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Ao adoecer, todo indivíduo passa por um processo de regressão. O indivíduo regressa\na uma situação de restrições e dependência,\nocasionando reações que acabam por abranger\nmecanismos de defesas psíquicas que nascem em ocasiões específicas como um tipo de ajuda\npara o indivíduo superar e ultrapassar situações psicologicamente complexas devido ao momento\nem que se encontra. Um exemplo é o paciente que, diante de um diagnóstico com risco fatal, diz\nestar bem, uma vez que já realizou todos os procedimentos possíveis para a cura, bem como já\nrealizou todos os seus sonhos e terminou de fazer tudo o que desejou fazer. Diante do exposto, o\nmecanismo de defesa mais adequado ao exemplo ora mencionado é:","options":{"A":"Negação.","B":"Recalcamento.","C":"Racionalização.","D":"Progressão."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-274591","number":"274591","sourceNumber":"274591","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A anamnese é a entrevista realizada por um profissional da saúde com seus pacientes\ncujo objetivo é orientar o raciocínio médico para\no diagnóstico de uma doença. O raciocínio\ndiagnóstico estabelecido a partir da obtenção de dados, que consiste em testar teorias por meio de\nhipóteses falseáveis, é denominado:","options":{"A":"Raciocínio inferencial-indutivo.","B":"Raciocínio hipotético-dedutivo.","C":"Raciocínio hipotético-indutivo.","D":"Raciocínio analógico-dedutivo."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-274599","number":"274599","sourceNumber":"274599","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Os antipsicóticos ou neurolépticos se caracterizam por sua ação psicotrópica, com\nefeitos sedativos e inibição das funções psicomotoras. Da mesma forma, os neurolépticos:","options":{"A":"Apresentam apenas atividade ansiolítica.","B":"Podem ser usados em associação com analgésicos e antidepressivos, exceto no tratamento da\ndor crônica em geral.","C":"Podem ser usados em associação com analgésicos e antidepressivos no tratamento da dor\ndisestésica decorrente de neuropatias.","D":"Alteram a percepção da dor, porém não controlam os transtornos psíquicos."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-274603","number":"274603","sourceNumber":"274603","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O tabagismo é uma toxicomania caracterizada pela dependência física e psicológica do\nconsumo de nicotina, substância presente\nno tabaco. Por seu turno, o número de fumantes vem\naumentando mundo afora e, em decorrência do uso de tal substância, problemas de saúde,\nmormente pulmonares, tendem a ser frequentes, ocasionando inúmeras consequências. No Brasil,\no contexto não é muito diferente. Acerca do consumo de cigarros no país, é CORRETO afirmar:","options":{"A":"A maioria dos indivíduos inicia o uso do cigarro a partir dos seus 20 anos.","B":"A preponderância em seu uso é mais elevada em moradores da zona rural.","C":"O poder aquisitivo não influencia no consumo de cigarros.","D":"O grau de escolaridade não se encontra como um dos fatores de seu consumo."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-263399","number":"263399","sourceNumber":"263399","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um médico de uma equipe de Saúde da Família atende muitas pessoas tabagistas e\nopta por implantar um grupo operativo de enfrentamento ao tabagismo como intervenção coletiva\nde educação em saúde. Segundo o Consenso sobre Abordagem e Tratamento do Fumante do\nInstituto Nacional do Câncer, está correto o médico","options":{"A":"prever inicialmente seis sessões semanais e recomendar, ao grupo, uma redução progressiva do\nnúmero de cigarros fumados por dia.","B":"planejar palestras nas sessões com imagens demonstrando as consequências maléficas do\ntabagismo para a saúde.","C":"realizar o teste de Fagerstrom durante a primeira sessão do grupo para avaliação da gravidade\nda dependência nicotínica.","D":"indicar farmacoterapia sem contraindicações clínicas para fumantes que já tentaram parar de\nfumar somente com terapia cognitivo-comportamental."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-212092","number":"212092","sourceNumber":"212092","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Acerca do transtorno depressivo maior, ou transtorno do humor, julgue o item a seguir.\nEntre os critérios de diagnóstico desse\ntranstorno que devem estar presentes quase todos os dias,\npor no mínimo duas semanas consecutivas, incluem-se o interesse ou prazer reduzidos em todas\nou quase todas as atividades, na maior parte do dia; a agitação psicomotora; a hipersonia; e o\nhumor depressivo na maior parte do dia.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-212087","number":"212087","sourceNumber":"212087","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Acerca do transtorno depressivo maior, ou transtorno do humor, julgue o item a seguir.\nA imipramina e a nortriptilina são\nantidepressivos Inibidores Seletivos da Recaptação da Serotonina\n(ISRS) usados como tratamento inicial para a maioria dos pacientes com formas mais graves de\ndepressão.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-212128","number":"212128","sourceNumber":"212128","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Com relação a doenças respiratórias, julgue o item a seguir. Um instrumento\nquantitativo para avaliação da pessoa\ntabagista é o questionário, de tolerância de Fagerström, que\navalia o grau de dependência psíquica à nicotina; observando-se que, quanto menor o escore\nobtido, maior é o grau dessa dependência.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-203113","number":"203113","sourceNumber":"203113","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Política Nacional de Saúde Mental, Álcool e Outras Drogas: A Política Nacional de\nSaúde Mental compreende as estratégias e\ndiretrizes adotadas pelo País com o objetivo de\norganizar a assistência às pessoas com necessidades de tratamento e cuidados específicos em\nsaúde mental. Abrange a atenção a pessoas com necessidades relacionadas a transtornos mentais\ncomo depressão, ansiedade, esquizofrenia, transtorno afetivo bipolar, transtorno\n\nobsessivo-compulsivo, incluindo aquelas com quadro de uso nocivo e dependência de substâncias\npsicoativas (álcool, cocaína, crack e outras drogas). Com base no texto, e considerando a Rede de\nAtenção Psicossocial (RAPS), vinculada à Política Nacional de Saúde Mental, assinale a alternativa\ncorreta.","options":{"A":"Objetiva a institucionalização dos que moram hospitais psiquiátricos.","B":"Objetiva a redução dos serviços residenciais terapêuticos.","C":"Os serviços residenciais terapêuticos não alcançam pacientes em situações de vulnerabilidade,\ncomo os moradores de rua.","D":"Os pacientes que apresentarem transtornos mentais serão tratados com exclusividade na\nAtenção Básica.","E":"Objetiva o recebimento de pacientes em quadros clínicos agudizados para internações breves."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":["question_bank/media/medcurso/medcurso-psiquiatria-psi-unico/203113.png"],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-177270","number":"177270","sourceNumber":"177270","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente de 19 anos de idade usuária de drogas, é admitida em unidade básica de\nsaúde às 22 h , com relato de tosse e\nfebre baixa. Encontra-se em precário estado de cuidado\npessoal. Relata uso frequente de cocaína e heroína desde os 18 anos de idade, com a última dose\ntendo ocorrido apenas 4 horas antes do atendimento médico. Nega comorbidades. No começo da\nmanhã do dia seguinte, a equipe médica é chamada com urgência ao quarto onde a paciente está\ninternada. A equipe de enfermagem informa que, desde as 4 horas da manhã, a paciente começou\na ficar inquieta, com piora da rinorreia e sudorese intensa, além de arrepios frequentes. Há cerca\nde 30 minutos, ela começou a apresentar náuseas, mialgia e hipotensão severa. Com base no\nreferido caso clínico e considerando que, no uso crônico de narcóticos, a retirada dos\nentorpecentes pode ocasionar sintomas da conhecida síndrome de abstinência, assinale a\nalternativa correta.","options":{"A":"A hipotensão não é esperada na abstinência por opioides, de maneira que é necessário excluir\nas causas sistêmicas.","B":"A presença de mialgia e de arrepios reforça a ideia de processo infeccioso associado.","C":"Por se tratar de dependência em relação a opioides, o risco de morte na síndrome de\nabstinência é maior que na dependência por barbitúricos, o que justifica a internação.","D":"Pelo curto período desde a última dose de narcótico, o quadro não pode ser considerado\nsíndrome de abstinência.","E":"Na síndrome de abstinência o uso de naloxona reverte os sintomas. O uso de metadona\nprovocará a ampliação da dependência em relação\nao narcótico."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-177271","number":"177271","sourceNumber":"177271","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem de 57 anos de idade, portador de hipertensão arterial sistêmica, tabagista\ndesde os 17 anos de idade, após um\ntratamento prévio contra depressão, relata ter realizado\ntentativas anteriores de interrupção do tabagismo, com recaídas em menos de 15 dias em todas as\noportunidades. Relata que o fator mais importante para as recaídas era o estresse no trabalho. Nos\núltimos 2 anos, ele tem conseguido diminuir a carga de tabaco e, atualmente, fuma cerca de 10\ncigarros por dia. O paciente, então, procurou auxílio médico para a suspensão do tabagismo.\n\nConsiderando-se a situação hipotética apresentada e os conhecimentos médicos relacionados à\nconduta apropriada para o referido o caso clínico, é correto afirmar que","options":{"A":"deve ser feito o uso de bupropiona, associado à nicotina oral e ao acompanhamento médico,\nsomente se for descartada crise convulsiva prévia.","B":"a quantidade de cigarros consumidos por dia não modifica a dependência do tabagismo.","C":"deve haver o acompanhamento para a continuidade da retirada da carga tabágica.","D":"o uso de adesivos tem demostrado efeito inócuo para a cessação do tabagismo.","E":"deve ser feito uso de vareniciclina, associado à nicotina oral e ao acompanhamento periódico."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-168440","number":"168440","sourceNumber":"168440","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um homem com 65 anos de idade encontra-se internado no hospital, no pós-operatório\nimediato de uma herniorrafia inguinal à\ndireita. Seus exames pré-operatórios apresentaram-se sem\nalterações. Às 2 horas da madrugada, a técnica de enfermagem recorre ao médico plantonista, pois\no paciente é encontrado nu, recusa-se a colocar novamente as roupas, fala coisas sem sentido e\nnão reconhece familiar que o acompanha. Sua cirurgia foi realizada na manhã anterior, sem\nintercorrências, tendo ele recebido meperidina após o procedimento cirúrgico e metoclopramida\ndevido a náuseas. Não se alimentou o dia todo e, ao exame físico, não se apresentaram\nalterações. O exame do seu estado mental mostra desorientação; ele não atende pelo nome e não\nsabe onde está, além de estar hipotenaz e um pouco sonolento. Diante desse quadro, o médico\nplantonista deve","options":{"A":"prescrever um benzodiazepínico endovenoso para a sedação do paciente e avaliar\ncomplicações pós-operatórias.","B":"avaliar a necessidade das medicações em uso, colocar o paciente em um quarto com boa\niluminação e prescrerver-lhe um antipsicótico, se constatada agitação psicomotora.","C":"conter fisicamente o paciente e iniciar sedação com midazolam endovenoso, enquanto aguarda\navaliação psiquiátrica.","D":"manter conduta expectante, dado que esses quadros regridem espontaneamente em poucas\nhoras, e prescrever um benzodiazepínico, se\nconstatada agitação psicomotora."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-168450","number":"168450","sourceNumber":"168450","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma mulher com 38 anos de idade procurou atendimento em Unidade Básica de Saúde\n(UBS) por apresentar, há 4 meses, ganho de\npeso, fadiga, sonolência excessiva e irritabilidade. A\npaciente relata sentir-se muito triste, desanimada e com baixa autoestima. Ao exame físico\napresentou frequência cardíaca = 58 bpm, pele seca e áspera e edema palpebral bilateral. Os\ndemais aspectos do exame físico estavam inalterados. Os resultados dos exames solicitados\nindicaram dosagem sérica do hormônio estimulante da tireoide (TSH) = 34 mUI/L (valor de\nreferência:0,45 a 4,5 mUI/L), tendo sido repetidos e confirmado o resultado, tiroxina sérica (T4\nlivre)\n\n= 0,3 ng/dL (valor de referência: 0,7 a 1,8 ng/dL). Diante desse quadro, foi iniciado tratamento com\nlevotiroxina 100 mcg/dia. Após 6 semanas, foi solicitada a repetição dos exames com os seguintes\nresultados: TSH = 2,5 mUI/L e T4 livre = 1,2 ng/dL. Nessa ocasião a paciente referiu melhora quase\ncompleta dos sintomas apresentados. Cinco meses depois, essa paciente volta à UBS para\nconsulta expondo a suposição de que a tireoide piorou de novo. Afirma estar tomando corretamente\nsua medicação. Novos exames realizados nessa ocasião indicam TSH = 2,3 mUI/L e T4 livre = 1,2\nng/dL. Questionada, a paciente informa apresentar muita tristeza, desânimo, falta de concentração\ne fadiga. Ao exame físico, constata-se que não houve ganho de peso e que não há alteração na\ntireoide da paciente. Nessa situação, a conduta adequada é","options":{"A":"informar à paciente que o seu quadro clínico é compatível com tireotoxicose e que a dosagem\ndo seu medicamento deverá ser reduzida;\nagendar retorno em 6 meses para reavaliação de TSH.","B":"informar à paciente a necessidade de aumentar a dose de levotiroxina até a resolução completa\ndos sintomas, independentemente dos valores de\nTSH e T4 livre; agendar retorno em 6 meses para\nreavaliação de TSH.","C":"fazer a avaliação para transtorno depressivo como diagnóstico deiferencial e, caso confirmado,\ndiscutir o início de tratamento para essa\nnova comorbidade; manter acompanhamento dos níveis\nséricos de TSH.","D":"informar à paciente que, mediante os indícios de que a terapia com levotiroxina não está sendo\nefetiva, faz-se necessário estender a investigação, procedendo-se à realização de biópsia da\n\ntireoide com agulha fina."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-158060","number":"158060","sourceNumber":"158060","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente de 88 anos de idade, previamente autônoma para as atividades de vida diária,\ncom história de HAS e de DM2 bem controlada com enalapril e metformina, apresenta-se ao\n\npronto-socorro às 22h30, levada pelos respectivos familiares, pois está confusa e desorientada\ndesde o dia anterior, não reconhecendo\nfamiliares, esquecendo o próprio nome, errando datas e\nrespondendo, de forma desconexa, às perguntas que lhe são feitas. Os familiares notaram que,\ndesde a manhã anterior, a paciente estava mais restrita ao próprio quarto e com comportamento\nestranho. Como ela sempre foi uma senhora muito mal-humorada e interagia pouco, resolveram\nnão incomodá-la, mas quando a família reuniu-se para almoçar, ainda no dia anterior, ficou claro\nque havia algo errado. Ao longo do dia seguinte, a paciente pareceu melhorar algumas vezes por\npoucos minutos, para depois voltar a ficar confusa. Os familiares não sabem informar mais dados.\nAo exame físico: paciente está desidratada; com PA = 150 mmHg x 90 mmHg; FC = 105 bpm;\ntemperatura = 38,5°C; FR = 18 irpm; saturação de oxigênio = 98%; hemoglicoteste de 120 mg/dl. A\nausculta pulmonar é normal, e a ausculta cardíaca indica sopro aórtico sistólico 2+/+6, edema 1+/\n4+ simétrico em membros inferiores e abdome difusamente doloroso, mas sem peritonismo. O\nexame neurológico é prejudicado pela baixa colaboração da paciente, mas não são detectados\ndeficit focais. A respeito do caso clínico apresentado, assinale a alternativa CORRETA.","options":{"A":"Trata-se de um acidente vascular encefálico, sendo o tratamento imediato apenas de suporte,\nvisto que não há possibilidade de trombólise\nem razão do tempo de evolução.","B":"Trata-se de demência senil, tendo em vista o histórico de alteração de comportamento crônico;\nentretanto, deve se realizar a triagem para causas reversíveis de demência.","C":"O quadro é compatível com delirium, sendo necessário realizar triagem infecciosa.","D":"Não se recomenda a dosagem de eletrólitos.","E":"Essa condição acomete principalmente idosos com boa funcionalidade, como a paciente do\nquadro."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-168506","number":"168506","sourceNumber":"168506","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Durante plantão em enfermaria de um hospital, o médico plantonista é chamado pela\nequipe de enfermagem porque um homem, com 38 anos de idade, que aguarda para realização de\numa herniorrafia eletiva, apresenta uma crise. Chegando ao quarto, o médico se depara com o\npaciente referindo dor torácica, taquicardia, dispneia, tontura e sudorese de início súbito.\n\nImediatamente o médico avalia o paciente que refere medo de estar tendo um ataque cardíaco e de\n\"estar ficando louco\". Não possui antecedentes de doença dignos de nota. Ao exame físico,\napresenta frequência cardíaca = 110 bpm e frequência respiratória = 32 irpm, sem evidenciar outras\nalterações. Avaliações cardiológica, metabólica e pulmonar de emergência também apresentam\nresultados normais. O paciente não tem histórico de doenças cardíacas nem apresenta fatores de\nrisco cardiovascular. O médico chega á hipótese diagnóstica de crise de pânico. Considerando\nesse quadro clínico e correspondente hipótese diagnóstica, o médico plantonista deve","options":{"A":"Prescrever imediatamente prometazina 25 mg via intramuscular, repetir a aplicação com\ndosagem, se necessário, e cancelar a\ncirurgia por necessidade de encaminhamento do paciente\npara a psiquiatria de emergência.","B":"Tranquilizar o paciente, orientá-lo par que respire devagar e profundamente e considerar o uso\nde benzodiapínicos em caso de crise muito prolongada\nou grave.","C":"Iniciar tratamento com inibidor seletivo da recaptação de serotonina e agendar visita do\npsicólogo do hospital para uma avaliação do\npaciente em 2 dias, período em que este deve ficar\ninternado.","D":"Prescrever imediatamente haloperidol 5 mg via intramuscular, conter fisicamente o paciente e\nmanter a data da cirurgia, pois a medicação anestésica pode reverter o quadro e aliviar os\nsintomas."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-168513","number":"168513","sourceNumber":"168513","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um homem com 75 anos de idade, acompanhado da filha, é atendido em consulta no\nambulatório de Geriatria. A filha revela estar preocupada com os problemas de memória do pai que,\nsegundo ela, tem estado desatento nas últimas 2 semanas, incapaz de lembrar seus\ncompromissos, além de ter se perdido ao dirigir, ter sido incapaz de utlizar o telefone celular e de\nnão ter certeza do próprio endereço. A filha informa que o paciente faz uso de vários\nmedicamentos, não sabendo informar o nome deles. O paciente não apresenta sintomas\ndepressivos cormóbidos e não tem história pregressa de uso de tabaco ou álcool. Ao exame físico,\no paciente mostra-se normal. Considerando a situação descrita, a medida incial apropriada para a\nelucidação diagnóstica é","options":{"A":"Excluir a possibilidade de delirium por uso de medicações, pedindo à filha que traga a lista\ncompleta de medicações em uso pelo paciente.","B":"Iniciar o diagnóstico diferencial de demências mediante a solicitação de ressonância magnética\ndo cérebro.","C":"Avaliar a possibilidade de tumor cerebral e solicitar tomografia computadorizada do cérebro.","D":"Investigar a possibilidade de neurocisticercose e solicitar tomografia computadorizada do\ncérebro."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-159547","number":"159547","sourceNumber":"159547","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A respeito do uso de cocaína, julgue o item que se segue. As manifestações clínicas\nassociadas à intoxicação por cocaína incluem taquicardia, hipertensão, infarto do miocárdio,\nsudorese, midríase, delírio, hipertermia, rabdomiólise, convulsões, hemorragia intracerebral,\narritmias cardíacas e edema pulmonar.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-154484","number":"154484","sourceNumber":"154484","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sabe-se que o consumo de cigarros é um importante fator de risco para o\ndesenvolvimento de câncer de pulmão. Quando\ncomparados com os não fumantes, os tabagistas\napresentam mais riscos de terem câncer de pulmão. Dentre as doenças abaixo, assinale a que não\nse relaciona com o tabagismo.","options":{"A":"Hipertensão arterial.","B":"Trombose vascular.","C":"Úlcera do aparelho digestivo.","D":"Impotência sexual no homem.","E":"Lúpus."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-168447","number":"168447","sourceNumber":"168447","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma adolescente com 14 anos de idade, com história de perda de peso associada a\nirritabilidade há 6 meses, é atendida em Unidade Básica de Saúde da Família. A paciente refere\nque deixou de praticar esportes porque se sente cansada, que não consegue se concentrar nos\nestudos e que dorme mais que o habitual. Diz não ter energia para fazer nada, além de estar sem\napetite. Informa que, quando acordada, seu entretenimento é observar as redes sociais em seu\ncelular. Em face desse quadro, a conduta médica adequada é","options":{"A":"encaminhar a paciente a endocrinologia.","B":"solicitar eletroencefalograma para diagnóstico.","C":"considerar comportamento comum à faixa etária.","D":"iniciar tratamento com fluoxetina e/ou psicoterapia."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-168492","number":"168492","sourceNumber":"168492","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um homem com 25 anos de idade, vítima de agressão em via pública, é levado pela\nviatura da Polícia Militar até a Unidade de Pronto Atendimento (UPA). Apresenta-se com agitação\npsicomotora, fala arrastada, incoordenação motora com ataxia, lúcido, orientado no tempo e\nespaço e hálito etílico. Apresenta ferimento corto-contuso na região frontal, de aproximadamente 2\ncm, sem sangramento ativo. Mostra-se bastante agressivo, ameaçador e não permite ser\nsubmetido à avaliação dos sinais vitais, ao exame físico é à sutura do ferimento. Demonstra\nintensão de fugir da UPA e ameaça agredir os membros da equipe de saúde. Nessa situação, a\nconduta médica deve incluir as seguintes ações:","options":{"A":"Indicar contenção física e mecânica do paciente a ser realizada pela equipe de saúde; aplicar\nhaloperidol 5 mg via intramuscular, realizar sutura do ferimento; manter o paciente em observação\nna UPA e solicitar ao Serviço Social o contato com seus familiares.","B":"Indicar contenção física e mecânica do paciente a ser realizada pela equipe de saúde; aplicar\nprometazina 25 mg via intramuscular, realizar sutura do ferimento e transferir o paciente para\nhospital geral de referência.","C":"Indicar contenção física e mecânica do paciente a ser realizada pelos policiais; aplicar diazepam\n10 mg via endovenosa, realizar sutura do\nferimento e transferir o paciente para unidade de\nreferência psiquiátrica.","D":"Indicar contenção física e mecânica do paciente a ser realizada pelos policiais; administrar\nglicose a 50% ( 60 a 100 ml, diluída a 50%)\nvia endovenosa em bolus e diazepam 10 mg via\nendovenosa; realizar sutura do ferimento; manter o paciente em observação na UPA e solicitar ao\nServiço Social o contato com seus familiares."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-168485","number":"168485","sourceNumber":"168485","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um homem com 33 anos de idade, com diagnóstico de esquizofrenia há 8 anos, em\ntratamento regular no Centro de Atenção Psicossocial, faz uso de quetiapina 600 mg/dia e\nencontra-se estável em relação aos sintomas psiquiátricos. Ele comparece à Unidade de Saúde da\nFamília para reavaliação periódica; refere ganho de peso de 1,5 kg em 3 semanas, polifagia e\npolidipsia sem outros sintomas. Em face desse caso, qual deve ser a conduta adotada?","options":{"A":"Referenciar o caso à atenção especializada para investigação adicional e manejo adequado do\nquadro clínico atual.","B":"Encaminhar o paciente para internação, considerada recurso terapêutico e instrumento do\nProjeto Terapêutico Singular.","C":"Aumentar a dose de quetiapina para 800 mg/dia, considerando-se interações medicamentosas,\npara otimização do tratamento.","D":"Avaliar glicemia em virtude do risco de complicações metabólicas decorrentes do controle do\nquadro glicêmico em função do tratamento medicamentoso para esquizofrenia."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-168501","number":"168501","sourceNumber":"168501","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma adolescente com 16 anos de idade é trazida à Unidade Básica de Saúde (UBS)\npela mãe, apresentando quadro de tristeza e\namenorreia há 4 meses. A mãe relata que o\ncomportamento da adolescente tem mudado desde que ela passou a frequentar o grupo de dança\nda comunidade onde mora, há um ano. Informa que, desde então, a filha vem perdendo peso e tem\nse alimentado apenas com frutas e verduras, recusando-se a participar dos eventos familiares e se\nisolando de amigos da escola, embora continue a frequentar com assiduidade o grupo de dança.\n\nAo exame físico, a adolescente mostra-se triste e pouco interativa, está hipocorada, hidratada,\neupneica. Apresenta índice de massa corporal = 15\nkg/m²; pressão arterial = 90 x 50 mmHg;\nfrequência cardíaca = 55 bpm. Observa-se discreto aumento do volume das parótidas\nbilateralmente. Exames laboratoriais realizados na UBS mostram anemia\nnormocrômica/normocítica, elevação de aminotransferases, hiponatremia, normocalemia e nível de\ncreatinina normal. Diante do quadro clínico apresentado, o diagnóstico e a conduta mais apropriada\na ser tomada pelo médico de família são","options":{"A":"quadro de depressão na adolescência, de grau grave; encaminhar a paciente para internação\npsiquiátrica e orientar a família acerca\ndo risco de suicídio e comprometimento do desenvolvimento\npsicomotor.","B":"quadro provável de depressão na adolescência, de grau leve a moderado; prescrever inibidor da\nrecaptura da serotonina na UBS e orientar a família a respeito dos aspectos normais da\nadolescência.","C":"quadro provável de transtorno alimentar moderado; solicitar a realização de recordatório\nalimentar, com acompanhamento na UBS, e\norientar a família a respeito da alimentação saudável\nna adolescência.","D":"quadro de transtorno alimentar grave; encaminhar para a unidade hospitalar de referência e\norientar a família acerca da importância da busca de ajuda especializada e seguimento do\ntratamento na UBS após internação."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-159542","number":"159542","sourceNumber":"159542","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em um dia normal de trabalho, médicos de família e comunidade atendem a muitos\ncasos diferentes. Certa manhã, determinado\nmédico atendeu a quinze pacientes, entre os quais se\nencontravam os seguintes: (1) uma criança de cinco anos de idade com suspeita de abuso sexual,\ntrazida pela mãe; (2) um idoso de sessenta e seis anos de idade, tabagista, com diabetes melito\n(DM) e hipertensão arterial sistêmica (HAS); (3) uma mulher de vinte e três anos de idade,\nestudante universitária, que não tomava banho havia uma semana; (4) um bebê de uma semana de\nvida (5) e sua mãe, puérpera, para consulta normal; (6) um adolescente de dezessete anos de\nidade, com rolha de cera; (7) uma idosa de setenta e um anos de idade, com diabetes melito (DM)\ne obesa com úlcera no membro inferior esquerdo, (8) e sua filha, e cuidadora, de quarenta e nove\nanos de idade, que não dormia regularmente havia um mês. Considerando esses casos clínicos,\njulgue o item a seguir. Ao paciente 2, o médico poderá indicar a nortriptilina, a segunda linha de\ntratamento medicamentoso do tabagismo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-133979","number":"133979","sourceNumber":"133979","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente masculino de 32 anos de idade, em acompanhamento irregular em diversos\nserviços de psiquiatria em razão de transtorno ansioso generalizado e dependência de\nbenzodiazepínicos, agitado e trêmulo, invade sala de atendimento. Considerando essa situação\nhipotética e sabendo que, logo em seguida, o paciente manifestou um dos sinais maiores da\nsíndrome de abstinência por benzodiazepínicos, de acordo com o Projeto Diretrizes - Abuso e\nDependência dos Benzodiazepínicos, assinale a alternativa correta em relação ao sinal\napresentado.","options":{"A":"Náuseas.","B":"Vômitos.","C":"Pesadelos.","D":"Irritabilidade.","E":"Convulsões."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-129013","number":"129013","sourceNumber":"129013","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Avô, de 58 anos de idade, de uma criança de três anos de idade, morreu devido a\nenfarte agudo do miocárdio. Os pais da\ncriança, preocupados, solicitaram orientações, na unidade\nbásica de saúde, durante consulta de puericultura, pois souberam que a prevenção dessa patologia\ndeve ser iniciada ainda na infância. Com base no caso hipotético, assinale a alternativa que\napresenta a conduta correta.","options":{"A":"Reduzir a ingestão alimentar de gorduras pela criança, prescrevendo leite desnatado.","B":"Detalhar os antecedentes patológicos e hábitos, como diabetes, hipertensão, obesidade e\ntabagismo, do avô.","C":"Dosar o colesterol da criança anualmente.","D":"Dosar o colesterol da criança e iniciar medicação caso esteja acima do limite.","E":"Acalmar os pais, informando que a criança somente precisará de avaliação após os quarenta\nanos de idade."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-97767","number":"97767","sourceNumber":"97767","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma mulher com 55 anos de idade e longa história de episódios depressivos é trazida à\nUnidade Básica de Saúde por um Agente Comunitário de Saúde por apresentar-se delirante há\nvárias semanas. Já na sala de espera, o quadro agrava-se progressivamente para franca agitação\npsicomotora, com a paciente tentando agredir outro usuários e a equipe de trabalho, por quem diz\nestar sendo perseguida. Nessa situação, além de realizar a contenção física da paciente, está\nindicado administrar","options":{"A":"sertralina por via oral.","B":"diazepam por via oral.","C":"haloperidol por via intramuscular.","D":"prometazina por via intramuscular."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-97796","number":"97796","sourceNumber":"97796","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma mulher com 44 anos de idade procura a Unidade Básica de Saúde com queixas\nde diminuição do apetite, insônia terminal e\nfraqueza. Relata que as queixas tiveram início há dois\nmeses e são diárias, embora em alguns momentos consiga se sentir bem. Informa pouca\nconcentração no trabalho e não apresenta mais interesse em cuidar de sua primeira e única filha de\nnove meses. Relata ainda fazer uso de duas taças de vinho nos finais de semana. Paralelamente\nnão tem se relacionado bem com o marido desde que a filha nasceu, falta muito ao trabalho e tem\ndeixado a filha sob os cuidados da mãe. Assinale a alternativa com a hipótese diagnóstica correta e\na conduta indicada para essa paciente.","options":{"A":"Transtorno depressivo orgânico (depressão pós-parto); prescrição de antidepressivo tricíclico.","B":"Transtorno de ajustamento (reação depressiva breve); encaminhamento para fazer psicoterapia.","C":"Episódio depressivo (depressão maior); prescrição de inibidor de receptação de serotonina.","D":"Transtorno de humor (depressivo) induzido pelo álcool; recomendação para se abster do uso de\nálcool."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-75489","number":"75489","sourceNumber":"75489","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher com 30 anos de idade é atendida por um médico numa Unidade de Saúde da\nFamília na comunidade em que reside. Há três meses vem se sentindo muito cansada, com\ndesânimo e desinteresse para fazer todas as suas tarefas diárias, inclusive sem vontade de comer\n(emagreceu 3 kg nesse período) ou de sair de casa. Não está dormindo direito e sente \"que não\nserve para mais nada\" (sic). Além do acolhimento de forma contextualizada, por meio de um\nrelacionamento médico-paciente humanizado, quais devem ser, respectivamente, o diagnóstico e a\nconduta?","options":{"A":"A paciente não preenche critérios para episódio depressivo e deve-se investigar anorexia\nnervosa.","B":"A paciente preenche critérios para diagnóstico de episódio depressivo e deve ser encaminhada\npara um psiquiatra.","C":"A hipótese diagnóstica é de anemia e deve-se solicitar dosagem de hemoglobina e iniciar\nreposição medicamentosa.","D":"A paciente preenche critérios para diagnóstico de episódio depressivo e deve-se iniciar\ntratamento.","E":"Deve-se realizar investigação das funções tireoidianas, pois a história clínica é característica\nde\ndistúrbios deste órgão."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-137525","number":"137525","sourceNumber":"137525","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher de 48 anos de idade, obesa, procura ambulatório de Clínica Médica,\nacompanhada da irmã, com queixas de sentir-se cansada, sem ânimo e interesse para suas\natividades corriqueiras e sociais, apresentando constante vontade de dormir , sem conseguir\nconcentrar-se nas suas atividades. Seu peso aumentou de 75 para 82 kg em um mês. A irmã\nrelata que a paciente \"está fazendo as coisas de maneira lenta\", passa os dias em um quarto\nescuro e verbalizou vontade de morrer. Exame físico: IMC = 31 kg/m (valor de referência < 25\nKg/m ), sem outras alterações. A paciente tem histórico de arritmia cardíaca. Avaliação\nrecente de função tiroideana revelou resultados normais para TSH, T3 e T4. No caso\ndescrito acima, qual a conduta terapêutica mais adequada?","options":{"A":"Indicação de psicoterapia de apoio e de antidepressivo tricíclico.","B":"Indicação de psicoterapia cognitivo-comportamental e inibidor da mono-amino-oxidase.","C":"Prescrição de antidepressivo inibidor seletivo da recaptação de dopamina.","D":"Indicação de psicoterapia e antidepressivo inibidor seletivo da recaptação de serotonina.","E":"Prescrição de associação de antidepressivo inibidor de serotonina e antipsicótico."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-137571","number":"137571","sourceNumber":"137571","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um homem de 75 anos de idade é trazido pela filha com história de\ncomportamento anormal há sete dias. Havia\nchegado da fazenda, onde administra suas\npropriedades; dormiu e acordou desorientado. Passou a perambular pela casa sem\nreconhecer pessoas, dirigindo-se à porta da rua para sair . Apresentou evacuações e diurese\nsem ir ao banheiro e dificuldade para despir-se, necessitando ser higienizado pela filha.\nMorando no andar superior da casa, passou a apresentar algum grau de dificuldade ao descer as\nescadas, tendo de ser ajudado. Come com lentidão, necessitando que o alimento lhe seja dado. É\nhipertenso e toma medicações há 13 anos. Teve retenção urinária há 10 dias, por hipertrofia\nprostática, necessitando de sondagem de alívio. Não refere febre. Ao exame físico: paciente\nvígil, porém desatento, sem alterações aparentes de humor , responde com lentidão às\nperguntas, o hesita ao deambular e sentar . Temperatura = 37,5 C, pulso radial = 110 bpm,\npressão arterial = 140 x 80 mmHg. Exame neurológico: hesitação aos movimentos e\ntremores finos, ausentes em repouso e desencadeados pelo movimento. Sem rigidez. Marcha\nhesitante. Reflexos osteotendíneos sem alterações. Demais aspectos do exame físico\ninalterados. O diagnóstico mais compatível com o quadro é","options":{"A":"demência vascular.","B":"doença de Alzheimer.","C":"doença de Parkinson.","D":"estado confusional agudo.","E":"demência por déficit de Vit B12."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-368179","number":"368179","sourceNumber":"368179","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Dos sintomas a seguir, aquele que deve estar obrigatoriamente presente no diagnóstico\nde episódio depressivo maior é","options":{"A":"perda ou ganho de peso.","B":"insônia ou hipersonia diária.","C":"fadiga ou perda de energia.","D":"humor deprimido ou perda do interesse ou prazer."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-368185","number":"368185","sourceNumber":"368185","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Considere uma jovem de 24 anos de idade, admitida no pronto-socorro após ter\ningerido propositalmente grande quantidade de\nmedicamentos. Após a estabilização clínica e\nmelhora do nível de consciência, a paciente conta que fez uso dos medicamentos impulsivamente\napós uma discussão com sua mãe. Refere que se acha gorda e repulsiva, que ?odeia? suas\nformas corporais, e que há três anos vem tentando perder peso, mas que, depois de um dia\nrestringindo de forma rigorosa a alimentação, acaba perdendo o controle e come ?tudo o que vê\npela frente?. Além disso, relata que apresenta esses episódios quase diariamente e que, em\nseguida, provoca vômitos e se corta com lâmina de barbear em região de punhos, coxas e abdome.\nTambém tem feito uso de laxantes e diuréticos, com o objetivo de ?desinchar? e compensar os\nepisódios compulsivos. Apresenta peso atual de 72 kg (altura: 1,65 m). Queixa-se de uma\nsensação de vazio, de longa data, e diz que os vômitos e as autoagressões também ajudam a\naliviar a sua ?dor psicológica?, através do desconforto físico. A paciente, no momento, nega\nideação suicida e relata que já buscou atendimento psicológico, mas que frequentou sem\nregularidade e abandonou há um ano. O transtorno alimentar apresentado nesse caso e o provável\ntranstorno de personalidade comórbido são, respectivamente","options":{"A":"bulimia nervosa e transtorno de personalidade borderline.","B":"anorexia nervosa e transtorno de personalidade evitativa.","C":"comer compulsivo e transtorno de personalidade histriônica.","D":"bulimia nervosa e transtorno de personalidade anancástica."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-336301","number":"336301","sourceNumber":"336301","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Senhora, 73 anos, professora aposentada, faz trabalhos comunitários (reforço escolar\npara crianças carentes) e viúva. Há 1 ano sua\nfilha vem notando que tem se esquecido com mais\nfacilidade dos seus compromissos. Nas reuniões familiares, tornou-se um pouco repetitiva,\ncontando as mesmas histórias e tendo maiores dificuldades para encontrar a palavra que quer\ndizer. Nos últimos meses, tem se confundido ao pagar contas na mercearia e padaria, voltando\npara casa frequentemente com o troco errado. Certo dia, ficou muito desorientada, confundindo os\nparentes, não sabia onde estava e dizia que havia bichos na parede e perto da cama. Passou a\nnoite toda sem dormir e dizia que havia pessoas dentro da casa, mas não sabia quem eram,\nquando foi levada ao Hospital para avaliação. Qual hipótese diagnóstica melhor explica o quadro\natual da paciente?","options":{"A":"Esquizofrenia","B":"Transtorno Delirante","C":"Depressão Maior","D":"Delirium"},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-304848","number":"304848","sourceNumber":"304848","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sofia, mulher, 39 anos, cabelereira, casada, G2AOP2, chega a Unidade Básica de\nSaúde para consulta de rotina. Relata\nperceber, há cerca de 3 meses, dores pelo corpo com\nsensação de fadiga e falta de energia para realizar as tarefas habituais. Percebeu aumento de\nirritabilidade, insônia de manutenção e aumento de apetite com o ganho ponderal de 6 kg, algo que\na incomoda muito porque tem medo de engordar. Observa que esse quadro piorou nos últimos 20\ndias e não tem conseguido realizar as atividades que antes gostava, como caminhar ou cozinhar,\ndiz não ver mais graça. Não relaciona sua situação a nenhum fator ambiental. Informa episódios\nsemelhantes aos 30 anos mas, na época, não buscou ajuda. A hipótese diagnóstica mais provável\ne a conduta que deve ser sugerida são:","options":{"A":"Transtorno do sintoma somático, com predomínio de dor; benzodiazepínicos e atividade física.","B":"Transtorno depressivo maior; inibidor preferencial da recaptação de serotonina e psicoterapia.","C":"Transtorno alimentar, provável compulsão alimentar periódica; inibidor preferencial da\nrecaptação de serotonina.","D":"Transtorno depressivo persistente (distimia); antidepressivo tricíclico, benzodiazepínico para\ninsônia e psicoterapia."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-291922","number":"291922","sourceNumber":"291922","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um jovem de 20 anos, concluindo o ensino médio, foi pouco à escola no último mês.\nNos últimos meses, vem se envolvendo com\nquestões filosóficas e parapsicológicas, temas que\nnunca lhe haviam interessado. Tem passado muito tempo isolado no quarto, convivendo pouco\ncom os amigos, inclusive com a sua família, e vem tomando pouco banho e quase não troca de\nroupa. Por insistência da mãe, contra a sua vontade, comparece à consulta médica com um\ncomportamento inadequado com riso imotivado e respostas sem sentido. Nesse caso, o diagnóstico\nMAIS PROVÁVEL, é de:","options":{"A":"Neurose.","B":"Esquizofrenia hebefrênica.","C":"Encefalite viral.","D":"Delírio de referência."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-306728","number":"306728","sourceNumber":"306728","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"J.L.A. 30 anos, vem para consulta no ambulatório de psiquiatria com diagnóstico de\nesquizofrenia, porém sem tratamento instituído até o momento. Chega à consulta relatando estar\nouvindo vozes e apresentando alucinações visuais. Têm história pregressa de reação\nextrapiramidal ao uso de bromoprida. Qual das medicações abaixo listadas tem menor risco de\ncausar a reação que o paciente apresentou ao utilizar bromoprida?","options":{"A":"Haloperidol","B":"Tiotixeno","C":"Loxapina","D":"Quetiapina"},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-287338","number":"287338","sourceNumber":"287338","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Alcoolista crônico dá entrada na Unidade de Pronto Atendimento com quadro de\nSíndrome de Abstinência Alcoólica. Observe as\nalternativas e assinale a terapêutica que NÃO deve\nser utilizada no tratamento da Síndrome de Abstinência Alcoólica.","options":{"A":"Tiamina.","B":"Benzodiazepínico.","C":"Difenil Hidantoína.","D":"Haloperidol."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-266377","number":"266377","sourceNumber":"266377","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A convulsão é uma complicação da Síndrome de Abstinência Alcoólica sendo mais\nfrequentes crises do tipo tônico-clônica generalizada. Sobre o tratamento dessa complicação\nassinale a alternativa correta:","options":{"A":"Carbamazepina em associação com fenitoína tem ação rápida e eficaz no controle das crises.","B":"Diazepam é a medicação de escolha.","C":"Fenitoína por via endovenosa, a chamada \"\"hidantalização\"\", deve ser associada ao\nbenzodiazepínico para controle das crises mantendo-se após fenitoína por via oral.","D":"Clorpromazina em doses elevadas tem se mostrado eficaz em casos refratários."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-227244","number":"227244","sourceNumber":"227244","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre o transtorno afetivo bipolar tipo 1 assinale a alternativa CORRETA.","options":{"A":"A maioria dos casos inicia-se com um episódio maníaco.","B":"É necessário pelo menos um episódio de transtorno maníaco e um depressivo para o\ndiagnóstico.","C":"Apesar de ser um transtorno do humor, no decorrer da doença ocorrem prejuízos cognitivos.","D":"A farmacoterapia apresenta boa resposta na estabilização inicial do humor, porém a psicoterapia\né que mantém o paciente estável por períodos\nprolongados."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-227245","number":"227245","sourceNumber":"227245","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"São fatores predisponentes ao desenvolvimento de delirium.","options":{"A":"Procedimentos cirúrgicos, doença renal crônica.","B":"Mudança de ambiente, privação de sono.","C":"Sexo feminino, desidratação.","D":"Idade avançada, depressão."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-227082","number":"227082","sourceNumber":"227082","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher de 43 anos é levada ao pronto atendimento pelos familiares por causa de\nagitação psicomotora e confusão mental. É\netilista, porém está sem ingerir bebidas alcoólicas há 3\ndias. Desconhece outras doenças e não faz uso de medicamentos. Ao exame físico, PA: 180 X\n100mmHg, FC 133bpm, FR 29ipm, SpO? 98%, Tax 39,1ºC. Está com sudorese profusa, tremor de\nextremidades, desorientada no tempo e no espaço, apontando insetos voadores inexistentes, com\nagitação psicomotora extrema e necessidade de contenção mecânica. Sem outras alterações ao\nexame físico. Considerando o caso descrito, assinale a alternativa que apresenta\nCORRETAMENTE a hipótese diagnóstica dessa paciente.","options":{"A":"Alucinação alcoólica.","B":"Delirium tremens.","C":"Síndrome de abstinência alcoólica leve.","D":"Síndrome de Wernicke."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-227253","number":"227253","sourceNumber":"227253","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem de 32 anos deu entrada no pronto atendimento com quadro de dispneia,\ntremores, sudorese, taquicardia, palpitações e\ndelírios persecutórios. Refere uso crônico de cocaína\ne álcool, estando abstêmio há 4 dias após libação. Ao exame físico apresenta desorientação no\ntempo e espaço, agitação psicomotora, temperatura axilar de 37ºC, diaforese, pressão arterial de\n160/100 mmHg, frequência cardíaca de 125 bpm, ritmo cardíaco regular, frequência respiratória de\n20 irpm, ausculta respiratória sem achados significativos. Eletrocardiograma evidenciou taquicardia\nsinusal. O tratamento inicial deste paciente consiste em:","options":{"A":"Benzodiazepínico.","B":"Betabloquedor.","C":"Nitroprussiato.","D":"Neuroléptico."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-246729","number":"246729","sourceNumber":"246729","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"No tratamento do transtorno de ansiedade generalizada é menos indicado o uso de:","options":{"A":"fluoxetina.","B":"sertralina.","C":"lorazepam.","D":"alprazolam.","E":"valproato de sódio."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-255664","number":"255664","sourceNumber":"255664","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Numa avaliação inicial de um quadro de delirium, qual entre os exames\ncomplementares abaixo, deve ser solicitado? MARQUE A CORRETA:","options":{"A":"Nível de vitaminas: B12, folato e tiamina.","B":"Hormônios Tireoidianos: Tireoestimulante (TSH) e Tetraiodotironina (T4) livre.","C":"Sorologia: VDRL e anticorpos anti HIV.","D":"Painel de eletrólitos: Cálcio, magnésio e fósforo."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-199499","number":"199499","sourceNumber":"199499","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um homem de 62 anos foi encontrado pelo filho com confusão mental ao acordar pela\nmanhã. É hipertenso e etilista (faz uso de destilados diariamente há mais de 30 anos). Ao exame\ndo estado mental, estava desorientado no tempo e no espaço, hipotenaz, normovigil, com perda da\nmemória recente, com juízo e crítica comprometidos, sem alteração da sensopercepção, do\npensamento e da linguagem, humor preservado e eutímico. O exame neurológico revelou nistagmo\nhorizontal, demais pares cranianos normais, motricidade e sensibilidade sem alterações, marcha\natáxica, com base alargada e desequilíbrio. Restante do exame clínico sem alterações\nsignificativas. Sobre o caso descrito, assinale a alternativa CORRETA:","options":{"A":"O paciente mais provavelmente teve um acidente vascular encefálico enquanto dormia.","B":"As alterações neurológicas são irreversíveis, a\ndespeito do tratamento.","C":"O tratamento consiste na administração de tiamina pela via intravenosa.","D":"O paciente mais provavelmente apresenta a síndrome de abstinência alcoólica e deve receber\ndiazepam parenteral."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-202738","number":"202738","sourceNumber":"202738","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A partir de uma visão mais abrangente da saúde mental, não apenas a capacidade\npara amar e trabalhar, como propunha Freud,\nmas uma ampla gama de possibilidades de convívio\nem vários contextos (interpessoal, familiar, social, profissional), bem como um progressivo\ndesenvolvimento da capacidade de entrar em contato com as próprias emoções e de tolerar as\ninevitáveis frustações e dificuldades que a ?vida como ela é?, na expressão de Nelson Rodrigues,\nnos apresenta de forma contínua, conclui-se que, as intervenções psicoterápicas de orientação\npsicanalítica se baseiam nos seguintes princípios fundamentais: Marque ?V? para verdadeiro ou\n\n?F? para falso. ( ) Existência de manifestações mentais inconscientes. ( ) Causalidade ou\ndeterminismo psíquico (fenômenos mentais ou\ncomportamentais atuais guardam relação causal,\nainda que nem sempre evidentes, com fenômenos, ou acontecimentos anteriores a vida da\npessoa). ( ) Transferência: os pacientes repetem, de forma inconsciente na sua relação atual com o\nmédico ou com equipe, desejos, expectativas, temores ou experiências emocionais passadas. ( )\nParcialidade ou a não Neutralidade: como posição do médico em relação ao paciente, que\nconfigura uma certa distância possível e não permite a coexistência da objetividade com a empatia.","options":{"A":"V ? V ? F ? F","B":"F ? F ? V ? F","C":"F ? V ? V ? F","D":"V ? V ? V ? F","E":"V ? V ? V ? V"},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-215145","number":"215145","sourceNumber":"215145","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sabendo que depressão é uma condição prevalente entre as pessoas em cuidado\npaliativo, avalie as assertivas a seguir: I ?\nEm pessoas com demência, o humor não precisa ser\navaliado. II ? A escolha do antidepressivo deverá ser guiada pelas comorbidades de base do\npaciente, não havendo uma classe prioritária. III ? A dose dos antidepressivos deve ser progredida\nhabitualmente, quando necessário, a fim de proporcionar um melhor conforto para a pessoa. IV ? A\ndepressão deve ser rastreada em todas as pessoas que recebem cuidados paliativos. Quais\nalternativas estão CORRETAS?","options":{"A":"Apenas a I e a II.","B":"Apenas a II e a III.","C":"Apenas a III e a IV.","D":"Apenas a II, III e IV.","E":"I, II, III e IV estão corretas."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-212922","number":"212922","sourceNumber":"212922","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O fator precipitante (desencadeador direto) mais comum para o desenvolvimento do\ndelirium é:","options":{"A":"Doença cérebro-vascular.","B":"Alterações da glicemia.","C":"Estresse emocional.","D":"Uremia.","E":"Infecções."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-220299","number":"220299","sourceNumber":"220299","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre o tratamento farmacológico dos transtornos depressivos, assinale a alternativa\nCORRETA:","options":{"A":"A mirtazapina e a trazodona são boas alternativas nos casos que cursam com insônia.","B":"As doses dos inibidores seletivos da recaptação da serotonina devem ser aumentadas a cada\nsemana até a melhora clínica.","C":"O citalopram e o escitalopram são boas opções em idosos e cardiopatas, em função da\nsegurança cardiovascular desses medicamentos mesmo em doses altas.","D":"Os tricíclicos são boas opções para o tratamento do delirium em pacientes portadores de\ndemência."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-212934","number":"212934","sourceNumber":"212934","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Acerca dos quadroa ansiosos agudos, pode-se afirmar que:","options":{"A":"Geralmente surgem acompanhados de delírios.","B":"A maior parte dos pacientes apresentam-se agressivos durante o exame.","C":"O tratamento de escolha no PS é diazepam 100 mg VO.","D":"O paciente deve ser mantido em observação até a melhora do quadro.","E":"Para o diagnóstico ser firmado, deve haver um fator desencadeante claro para o quadro."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-199629","number":"199629","sourceNumber":"199629","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em relação a alimentação persistente de substâncias não nutritivas ou de substâncias\nnão pertencentes ao cardápio em geral (pica),\nassinale V para assertiva Verdadeira e F para\nassertiva Falsa. ( ) Esse distúrbio alimentar ocorre mais frequentemente em pacientes com\nesquizofrenia do que em pacientes apresentando transtorno do espectro autista. ( ) Para\ndiagnóstico desse distúrbio alimentar sugere-se que a criança tenha idade mínima de 2 anos. ( )\nEssas crianças são de risco para obstrução intestinal e intoxicação por chumbo. ( ) Abuso infantil\ndeve ser incluído entre os diagnósticos diferenciais em quadros como esse. ( ) Esse distúrbio\nalimentar ocorre sistematicamente em pacientes com anemia perniciosa. Assinale a sequência\nCORRETA:","options":{"A":"F, V, V, V, F.","B":"V, V, V, F, V.","C":"F, F, V, V, F.","D":"V, F, F, F, V."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-212963","number":"212963","sourceNumber":"212963","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma adolescente de 14 anos é levada ao pronto atendimento com queixa de perda de\npeso (13 quilos em 6 meses) e amenorreia.\nEla nega vômitos, diarreia, dor abdominal ou outras\nqueixas. Insiste que se sente muito bem. O exame físico mostra caquexia e frequência de pulso =\n48 batimentos por minuto. Os exames solicitados mostram glicose sérica = 62 mg/dl, potássio\nsérico = 3,2 mEq/l e hematócrito = 30%. Qual alternativa abaixo indica o diagnóstico mais provável\npara essa adolescente?","options":{"A":"Neoplasia maligna.","B":"Doença de Addison.","C":"Hipertireoidismo.","D":"Anorexia nervosa.","E":"Diabetes melito."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-196797","number":"196797","sourceNumber":"196797","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Quais são considerados os transtornos mentais mais graves na infância? Marque a\nCORRETA:","options":{"A":"Esquizofrenia e distúrbio do sono","B":"Hiperatividade e distúrbio bipolar","C":"Autismo e depressão","D":"Distonia neurovegetativa (DNV) e suicídio"},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-199570","number":"199570","sourceNumber":"199570","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente tabagista está em consulta com seu médico de família e comunidade para\nabordar este problema. Relembrou as vezes que\njá tentou parar de fumar, ressaltando suas\ndificuldades em manter a abstinência. Está motivado para tentar interromper novamente o uso de\ntabaco e acredita que terá sucesso desta vez, já tendo planejado algumas coisas que pode fazer\nnas próximas semanas. Em qual estágio de mudança de comportamento do Modelo Transteórico\nde Prochaska e DiClemente o paciente se encontra?","options":{"A":"Pré-contemplação.","B":"Contemplação.","C":"Preparação.","D":"Ação."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-196793","number":"196793","sourceNumber":"196793","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher de 59 anos com quadro de labilidade emocional, anedonia, inapetência, perda\nde peso, insônia, apatia, eventualmente com\nagitação psicomotora. Exame neurológico sem déficit\nmotor ou sensitivo. Assinale dentre as opções abaixo aquela que NÃO está indicada para o\ntratamento desta paciente.","options":{"A":"Escitalopram.","B":"Venlafaxina.","C":"Alprazolam.","D":"Trazodona."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-188015","number":"188015","sourceNumber":"188015","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher, 30 anos, evangélica, casada, natural e procedente de São Mateus, chega ao\npronto atendimento de psiquiatria apresentando taquicardia, opressão no peito, sudorese fria e\nsensação de morte iminente. Vem acompanhada do marido, que refere ter procurado a\n\n?psiquiatria? porque nos últimos meses tem apresentado esses ?surtos?. Ele já está cansado de\nlevá-la ao Pronto-socorro, fazer diversos exames que ?não dão nada?. Após ser tranquilizada e\nreceber clonazepam 2,0 mg, a paciente consegue nos falar e confirmar tais informações trazendo\nEletrocardiograma (ECG) e Holter sem alterações, bem como exames séricos sem anormalidades\n(hemograma, função hepática e tireoidiana). Paciente também nega, uso de medicação, etilismo ou\ndrogas ilícitas. Conta que vem apresentando medo constante de ?acontecer novamente?.\n\nRealizado novo ECG (apresentando leve alteração da repolarização, ritmo cardíaco sinusal com FC\nde 105 bpm, segmento ST com elevação de\n0,8mm); PA = 140 X 100 mm HG, FR= 78 irpm. A\nhipótese diagnóstica e conduta para esse caso são:","options":{"A":"Síndrome coronária aguda (angina instável) ? colher enzimas cardíacas seriadas e\nencaminhamento ao serviço de cardiologia.","B":"Taquicardia atrial paroxística ? uso de antiarrítmico e encaminhamento para o serviço de\ncardiologia.","C":"Transtorno de Ansiedade Generalizada ? encaminhamento ambulatorial com benzodiazepínico\nde curta duração.","D":"Transtorno do Pânico ? encaminhamento ambulatorial com ISRS (inibidor seletivo da\nreceptação da serotonina) e benzodiazepínico de curta duração por curto período.","E":"Transtorno dissociativo (ou conversivo) ? encaminhamento para psicoterapia e benzodiazepínico\nde longa duração."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-172770","number":"172770","sourceNumber":"172770","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"João é tabagista e discute com seu médico de família o medo que tem de ganhar peso\ndurante a tentativa de parar de fumar que estão conjuntamente planejando. João está\nassintomático, não tem comorbidades, exames laboratoriais normais e tem pontuação de 3 no teste\nde Fagerströn. É sua primeira tentativa de interromper o tabagismo. Qual deve ser a abordagem do\nmédico em relação a este receio de ganho de peso expresso pelo paciente?","options":{"A":"Reforçar os benefícios de parar de fumar e informar que o ganho de peso após a cessação do\ntabagismo é um mito não comprovado por ensaios clínicos.","B":"Recomendar atividade física e orientar dieta rigorosa acompanhada por nutricionista durante o\nprocesso de cessação do tabagismo.","C":"Preparar o paciente para a real possibilidade de ganho de peso, informando que este é\ntemporário, e orientar uma dieta equilibrada não rigorosa.","D":"Iniciar vareniclina e orientar dieta rigorosa acompanhada por nutricionista durante o processo de\ncessação do tabagismo."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-148596","number":"148596","sourceNumber":"148596","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente, sexo feminino, 50 anos, empregada doméstica, divorciada há 1 ano, procura\nseu médico de família e comunidade\nqueixando-se de ansiedade e preocupação excessiva de difícil\ncontrole com eventos futuros e questões que suas filhas consideram \"bobagens\". Diz concordar\ncom a avaliação feita pelas filhas. Sente-se muito tensa, tendo dificuldade para relaxar,\nrelatatando\ndores de cabeça e em região dorsal com frequência. Queixa-se de alteração do sono, irritabilidade,\ncansaço e dificuldades de concentração. Relata que o quadro teve início há pelo menos 7 meses e\nque são raros os dias que se sente completamente bem. Nega tristeza, desinteresse significativo\npelas coisas que costuma fazer e ideias suicidas. Considerando as opções abaixo e tendo em vista\na principal hipótese diagnóstica, qual seria a opção medicamentosa de primeira escolha para esta\npaciente?","options":{"A":"Clonazepam.","B":"Nortriptilina.","C":"Buspirona.","D":"Quetiapina.","E":"Escitalopram."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-127220","number":"127220","sourceNumber":"127220","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"São critérios diagnósticos para síndrome de abstinência ao álcool, definidos pela\nOrganização Mundial de Saúde (OMS), exceto.","options":{"A":"Taquicardia.","B":"Tremores.","C":"Agitação psicomotora.","D":"Alucinações.","E":"Ataxia."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-127245","number":"127245","sourceNumber":"127245","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Durante consulta médica em uma Unidade de Saúde da Família com queixa principal\nde lesão de pele inespecífica, você aborda o\npaciente sobre hábito de fumar. Pelo relato do\npaciente, você identifica grau de dependência muito elevado. Ao ser questionado sobre sua\nmotivação para interromper este hábito, o paciente relata que atualmente não pensa em parar de\nfumar e nega tentativas anteriores. Em qual estágio de motivação encontra-se o paciente e qual a\nconduta mais adequada para o caso?","options":{"A":"O paciente está na fase pré-contemplação; fornecer informações sobre tabagismo de maneira\nincisiva, priorizando as graves consequências deste\nhábito para a saúde, de forma a produzir medo\nda morte no paciente e desejo de mudar o comportamento.","B":"O paciente está na fase de contemplação; identificar os receios e medos do paciente, avaliar as\nestratégias para parar de fumar, trabalhar os tipos de interrupção do tabagismo (gradual ou\nabrupta), abordar a ambivalência do paciente e agendar o dia D para parar de fumar.","C":"O paciente está na fase pré-contemplação; fornecer informações adequadas sobre tabagismo,\nevitando-se neste momento o confronto e a abordagem incisiva do paciente, tendo como objetivo\npossibilitar que o paciente comece a pensar a respeito.","D":"O paciente está na fase de contemplação; aproveitar o momento para inserir o paciente em um\ngrupo de cessação do tabagismo, onde enfermeiros avaliarão a melhor estratégia para o paciente\nparar de fumar.","E":"O paciente está na fase de preparação; avaliar, junto com o paciente, as diferentes estratégias\nde mudança de comportamento, estabelecendo uma\ndata para parar de fumar já na primeira\nconsulta."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-77540","number":"77540","sourceNumber":"77540","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Dispnéia e dor torácica são sintomas comumente observados em qual dos seguintes\ntranstornos psiquiátricos?","options":{"A":"Esquizotípico.","B":"Dissociativo.","C":"Do pânico.","D":"Obsessivo-compulsivo.","E":"Dismórfico corporal."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-77372","number":"77372","sourceNumber":"77372","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente 66 anos, com história de estenose aórtica moderada em ecocardiograma\nrealizado no ano de 2011, deu entrada no\npronto-socorro do HECI em setembro de 2013 em\nedema agudo de pulmão grave, foi entubada após sedação com midazolam fentanil e transferida\nao CTI. No CTI, foi medicada com diuréticos e anti-hipertensivos, foi mantida sob sedação apenas\ncom propofol, repetido ecocardiograma mostrando agora estenose aórtica grave. Após melhora\nsignificativa da radiografia de tórax, cerca de 36 horas da admissão, foi suspensa sedação com\ndespertar imediato, porém devido à agitação psicomotora, foi extubada sem a realização do teste\nde respiração espontânea. Logo após, e devido extrema agitação psicomotora, hipertensão (210 x\n100) e taquicardia sinusal (150 bpm), apresentou recidiva do edema pulmonar, sendo reentubada.\nNovamente medicada e sedada com propofol, sendo acrescido risperidona para controle da\nagitação psicomotora apresentada. Nesse mesmo dia da reintubação, e devido mudança do\naspecto secreção pulmonar, foi colhida cultura de aspirado traqueal. Um dia após, iniciou febre.\n\nDois dias após, resultado da cultura do aspirado com S. aureus multissensível sendo iniciado\nOxacilina. Nesse mesmo dia a febre permaneceu\nconstante, elevada, em torno de 39,5/40 graus,\nacompanhada de tremores generalizados, refratária ao tratamento antitérmico e compressas de\ngelo. Manteve esse mesmo padrão de febre persistente após 48 horas de antibiótico,\nacompanhado ainda de labilidade pressórica significativa, leucocitose de 35000 com PCR de 60 e\nalteração leve de TGO e TGP. Hipótese diagnóstica e causa de refratariedade da febre?:","options":{"A":"Sinusite grave e otite média relacionadas ao uso da sonda nasoentérica. Necessidade de\nretirada da sonda e medidas locais para drenagem.","B":"Endocardite infecciosa com abscesso paravalvar. Necessidade de cirurgia cardíaca e retirada do\nfoco de infecção.","C":"Endocardite fúngica evoluindo com aneurisma micótico cerebral e consequente febre de origem\ncentral.","D":"Síndrome Neuroléptica Maligna relacionada ao uso de risperidona.","E":"Resistência in vivo à Oxacilina e provável infecção associada por Gram-negativo. Trocar\n\noxacilina por vancomicina e associar meropenem."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-77366","number":"77366","sourceNumber":"77366","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente 66 anos, com história de estenose aórtica moderada em ecocardiograma\nrealizado no ano de 2011, deu entrada no\npronto-socorro do HECI em setembro de 2013 em\nedema agudo de pulmão grave, foi intubada após sedação com midazolan fentanil e transferida ao\nCTI. No CTI foi medicada com diuréticos e antihipertensivos, foi mantida sob sedação apenas com\npropofol, repetido ecocardiograma mostrando agora estenose aórtica grave. Após melhora\nsignificativa da radiografia de tórax, cerca de 36 horas da admissão, foi suspensa sedação com\ndespertar imediato, porém devido à agitação psicomotora, foi extubada sem a realização do teste\nde respiração espontânea. Logo após, e devido extrema agitação psicomotora, hipertensão\n(210x100) e taquicardia sinusal (150bpm), apresentou recidiva do edema pulmonar sendo\nreintubada. Novamente medicada e sedada com propofol, sendo acrescido risperidona para\ncontrole da agitação psicomotora apresentada. Neste mesmo dia da reintubação e devido mudança\ndo aspecto secreção pulmonar, foi colhida cultura de aspirado traqueal. Um dia após iniciou febre.\nDois dias após, resultado da cultura do aspirado com S. aureus multisensível sendo iniciado\nOxacilina. Neste mesmo dia a febre permaneceu constante, elevada, em torno de 39,5-40 graus,\nacompanhada de tremores generalizados, refratária ao tratamento antitérmico e compressas de\ngelo. Manteve este mesmo padrão de febre persistente após 48 horas de antibiótico, acompanhado\nainda de labilidade pressórica significativa, leucocitose de 35000 com PCR de 60 e alteração leve\nde TGO e TGP. Hipótese diagnóstica e causa refratariedade da febre?: Em relação ao caso\ndescrito, marque a alternativa mais pertinente entre as abaixo:","options":{"A":"Dosagem de CK total e uso de dantrolene.","B":"Colher novas hemoculturas e fazer novo teste de sensibilidade a oxacilina.","C":"Realização de ecocardiograma transesofágico e contato com a equipe de cirurgia cardíaca.","D":"Realização de tomografia de seios da face e de mastoide.","E":"Realização de tomografia de crânio e início de Anfotericina B."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-59464","number":"59464","sourceNumber":"59464","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente 39 anos, obesa, tabagista (20 cigarros/dia há 4 anos), sem outras\ncomorbidades prévias, dá entrada em um\npronto-socorro em Niterói-RJ, com quadro de dispneia e\ndesconforto precordial que descreve como \"angústia\", iniciados há cerca de 20 minutos da\nadmissão ao hospital, após problema familiar grave (prisão de seu irmão). Apresentava ainda\nhistória de hipermenorreia. É atendida por seu colega de plantão, que assim descreve o exame\nfísico em prontuário: \"Paciente agitada, com dificuldade de manter-se deitada no leito, sendo\ncontida por terceiros, acianótica, anictérica, sem edemas, corada, hidratada. RCR 2t FC 140 bpm,\nPA 200 x 100 mmHg. Taquipneica, com FR 40, sem tiragem intercostal e sem batimento de aleta\nnasal. Sons pulmonares normais. Abdome livre e peristáltico\". Seu colega de plantão solicita\nimediatamente na chegada ao hospital os exames abaixo: Hemograma: Hb 7,8 VCM 60 Leucócitos\n7000 Plaquetas 200000; Gasometria arterial: pH 7,52 PCO2 20 PO2 110 Gradiente alveoloarterial\nde O2 10, restante normal; CK total de 500 (Normal < 200); CKMB 15 (N < 25); restante da\nbioquímica sem alterações; RX de tórax sem alterações; ECG (VER IMAGEM). Diante do exposto\nvocê o ajuda a elaborar o seguinte diagnóstico inicial:","options":{"A":"Provável Crise Hipertensiva do tipo emergência hipertensiva; Hipertensão arterial + Infarto\nAgudo do Miocárdio (IAM) com supra ST em\nparede inferior. Internação em CTI, controle de HAS\ncom Nitroprussiato e medidas para IAM.","B":"Provável Crise Hipertensiva do tipo emergência hipertensiva: Hipertensão arterial + Angina\nInstável (AI). Internação em Unidade de Dor\ntorácica, controle de HAS com Nitroglicerina, dosagem\nimediata de troponina e medidas para AI.","C":"Provável Crise Hipertensiva do tipo emergência hipertensiva: Hipertensão arterial + Infarto\nagudo do Miocárdio (IAM) sem supra de ST.\nInternação em CTI, controle de HAS com Nitroglicerina\ne medidas para IAM sem supra.","D":"Provável Crise Hipertensiva do tipo urgência hipertensiva: Hipertensão arterial + Desconforto\nprecordial a esclarecer. Internação em Unidade\nde dor torácica, controle de HAS com Captopril via\nsublingual, dosagem imediata de troponina.","E":"Provável pseudocrise hipertensiva: Hipertensão arterial em paciente com crise de ansiedade tipo\nSíndrome do Pânico. Medicações para controle de ansiedade, reavaliar paciente e pressão arterial\nperiodicamente."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":["question_bank/media/medcurso/medcurso-psiquiatria-psi-unico/59464.png"],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-32451","number":"32451","sourceNumber":"32451","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Dentre as causas possíveis de estado confusional agudo em idosos, qual das opções\nabaixo é a menos provável?","options":{"A":"Hipercalemia grave.","B":"Hipomagnesemia.","C":"Hipovolemia.","D":"Quinolonas.","E":"Anticolinérgicos."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-32466","number":"32466","sourceNumber":"32466","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente masculino, 36 anos, com insônia, desinibição social, logorreico, agitação\npsicomotora e ideias de grandeza há 5 dias, de caráter progressivo. Qual o diagnóstico mais\nprovável?","options":{"A":"Depressão agitada.","B":"Surto esquizofrênico agudo.","C":"Episódio maníaco.","D":"Delirium.","E":"Demência."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-27349","number":"27349","sourceNumber":"27349","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Os Mecanismos de Defesa do Ego, descritos por Anna Freud, que protegem o Ego de\nsupostos ? segundo Superego ? danos, são:","options":{"A":"Inconscientes","B":"Parte consciente e parte inconsciente","C":"São conscientes quando o ambiente permite","D":"Pode passar de consciente para inconsciente conforme o nível estresse","E":"Nenhuma das respostas corresponde à realidade"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-9419","number":"9419","sourceNumber":"9419","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A depressão na infância e na adolescência pode representar graves riscos, incluindo o\nsuicídio. Indique a opção NÃO associada a um sinal de depressão:","options":{"A":"Ausência do sentimento de culpa.","B":"Perda ou ganho de peso.","C":"Pensamentos de morte recorrentes.","D":"Insônia ou hipersonia.","E":"Perda de interesse ou prazer nas atividades habituais."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-363973","number":"363973","sourceNumber":"363973","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em quadros depressivos graves, é possível que haja a presença de sintomas psicóticos\nassociados. O tipo de delírio mais provável nesses casos é","options":{"A":"onírico.","B":"catatímico.","C":"alucinatório.","D":"interpretativo."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-363972","number":"363972","sourceNumber":"363972","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"L.M.V., mulher, 25 anos, solteira, é levada à consulta psiquiátrica por familiares por\nconta do seu comportamento. A mãe relata que\nela é \"cheia de manias\": suas roupas devem ser\norganizadas sempre por cores, seus livros devem seguir determinada ordem \"da sua cabeça\", ela\ndemora no banho porque tem métodos específicos para se limpar. Sente-se incomodada quando\nos móveis estão fora do lugar e quando sua rotina muda por qualquer motivo. Segundo os\nfamiliares, \"sempre foi assim, embora tenha piorado nos últimos anos\". Sem histórico de\ncompulsões, nem de distanciamento ou isolamento social. Quando indagada a respeito, a paciente\nrelata gostar de ser assim e que erradas estão as outras pessoas por serem tão desorganizadas.\nTais características são sinais indicativos de","options":{"A":"Transtorno Obsessivo Compulsivo.","B":"Transtorno Delirante Persistente.","C":"Transtorno do Espectro Autista.","D":"Transtorno de Personalidade Obsessivo-compulsiva."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-337452","number":"337452","sourceNumber":"337452","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"As combinações de adesivo + goma ou pastilha Nicotina podem ser feitas de acordo\ncom o esquema de uso do adesivo, sendo:","options":{"A":"a goma, mas não a pastilha utilizada para o resgate da fissura ou em casos de consumo de até\n5 cigarros/dia.","B":"a goma ou pastilha utilizada para o resgate da fissura, mas não em casos de consumo de até 5\ncigarros/dia.","C":"a goma ou pastilha utilizada para o resgate da fissura ou em casos de consumo de até 50\ncigarros/dia.","D":"a goma ou pastilha utilizada para o resgate da fissura ou em casos de consumo de até 5\ncigarros/dia."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-337455","number":"337455","sourceNumber":"337455","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Os tabagistas que fumam mais de 20 cigarros/dia, e que apresentam dificuldade para\nreduzir o número de cigarros:","options":{"A":"Mas que estão motivados a parar de fumar, não são candidatos ao uso associado de adesivos.","B":"Mas que estão motivados a parar de fumar, são candidatos ao uso associado de adesivos.","C":"Mas que não estão motivados a parar de fumar, são candidatos ao uso associado de adesivos.","D":"Mas que estão motivados a parar de fumar, são proibidos do uso associado de adesivos."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-337457","number":"337457","sourceNumber":"337457","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"As reduções das doses associadas de adesivos de nicotina devem ser paulatinas.","options":{"A":"Recomenda-se a retirada de 7 mg a cada semana, avaliadas pela intensidade dos sintomas de\nsíndrome de abstinência.","B":"Recomenda-se a retirada de 7 mg a cada dia, avaliadas pela intensidade dos sintomas de\nsíndrome de abstinência.","C":"Recomenda-se a retirada de 7 mg a cada semana, nunca avaliadas pela intensidade dos\nsintomas de síndrome de abstinência.","D":"Recomenda-se a retirada de 17 mg a cada semana, avaliadas pela intensidade dos sintomas de\nsíndrome de abstinência."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-337460","number":"337460","sourceNumber":"337460","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Pacientes idosos podem ser mais sensíveis ao tratamento com cloridrato de\nbupropiona. Sendo correto que:","options":{"A":"O médico deve avaliar a necessidade e nesse caso, prescrever dose tripla diária matinal (após o\ndesjejum) de 150 mg.","B":"O médico deve avaliar a necessidade e nesse caso, prescrever dose única diária matinal (após o\ndesjejum) de 550 mg.","C":"O médico deve avaliar a necessidade e nesse caso, nunca prescrever dose única diária matinal\n(após o desjejum) de 150 mg.","D":"O médico deve avaliar a necessidade e nesse caso, prescrever dose única diária matinal (após o\ndesjejum) de 150 mg."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-337462","number":"337462","sourceNumber":"337462","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O uso de Adesivos de Nicotina Transdérmico pode ocorrer irritação na pele durante o\nuso (decorrente da cola).","options":{"A":"Esta reação pode ser minimizada com o uso de creme de corticoide no local onde o adesivo será\naplicado, na noite anterior e no dia seguinte à aplicação.","B":"Esta reação pode ser piorada com o uso de creme de corticoide no local onde o adesivo será\naplicado, na noite anterior e no dia seguinte à aplicação.","C":"Esta reação pode ser minimizada com o uso de creme de corticoide no local onde o adesivo\nserá aplicado, na noite anterior e nunca no dia\nseguinte à aplicação.","D":"Esta reação não pode ser minimizada com o uso de creme de corticoide no local onde o adesivo\nserá aplicado, na noite anterior e no dia\nseguinte à aplicação. Pela perda de disponibilidade."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-337465","number":"337465","sourceNumber":"337465","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Terapia de Reposição de Nicotina (TRN) é bem tolerada nos pacientes cardiopatas\ncrônicos estáveis, não aumentando a gravidade\ndestas. Sobre isso, podemos afirmar que:","options":{"A":"Nos eventos agudos, como no infarto agudo do miocárdio (IAM), deve- se evitar a TRN nas\nprimeiras duas semanas do evento, pelo risco aumentado de arritmias causado pelo estímulo\nadrenérgico da nicotina.","B":"Nos eventos agudos, como no infarto agudo do miocárdio (IAM), deve- se evitar a TRN nas\nprimeiras duas semanas do evento, pelo risco reduzido de arritmias causado pelo estímulo\nadrenérgico da nicotina.","C":"Nos eventos agudos, como no infarto agudo do miocárdio (IAM), não é necessário evitar a TRN\nnas primeiras duas semanas do evento, pelo\nrisco aumentado de arritmias causado pelo estímulo\nadrenérgico da nicotina.","D":"Nos eventos agudos, como no infarto agudo do miocárdio (IAM), deve- se evitar a TRN nos\nprimeiros dois dias do evento, pelo risco aumentado de arritmias causado pelo estímulo\nadrenérgico da nicotina."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-337467","number":"337467","sourceNumber":"337467","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Na prática clínica, há pacientes com eventos cardiovasculares agudos, que podem se\nbeneficiar do uso antecipado da TRN na forma de adesivos de nicotina.","options":{"A":"Para tanto, esses indivíduos devem ser avaliados pelo médico assistente quanto a presença de\nquadro clínico cardiovascular estável, principalmente quando existir risco real de tabagismo entre\nesses pacientes. Essa decisão deverá desconsiderar os riscos e benefícios do uso da TRN antes\ndos 15 dias após evento agudo.","B":"Para tanto, esses indivíduos devem ser avaliados pelo médico assistente quanto a presença de\nquadro clínico cardiovascular estável, principalmente quando existir risco real de tabagismo entre\nesses pacientes. Essa decisão deverá considerar os riscos e benefícios do uso da TRN antes dos\n15 dias após evento agudo.","C":"Para tanto, esses indivíduos devem ser avaliados pelo médico assistente quanto a presença de\nquadro clínico cardiovascular estável, principalmente quando existir risco real de tabagismo entre\nesses pacientes. Essa decisão deverá considerar os riscos e benefícios do uso da TRN antes dos 5\ndias após evento agudo.","D":"Para tanto, esses indivíduos não devem ser avaliados pelo médico assistente quanto a presença\nde quadro clínico cardiovascular estável,\nprincipalmente quando existir risco real de tabagismo\nentre esses pacientes. Essa decisão deverá considerar os riscos e benefícios do uso da TRN antes\ndos 15 dias após evento agudo."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-342678","number":"342678","sourceNumber":"342678","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mesmo sendo considerado um importante problema de saúde pública, o alcoolismo\ncostuma em seus estágios finais ser\nidentificado apenas quando já ocorreram grandes perdas e as\nchances de reabilitação do indivíduo são menores. O consumo de álcool é, em geral, socialmente\naceito, o que provoca grande dificuldade na classificação do estado em que se encontram os\nusuários. A alternativa que define o padrão e as implicações do consumo de álcool é:","options":{"A":"a vulnerabilidade individual à dependência do álcool se desenvolve em função de fatores\ngenéticos","B":"a definição de um bebedor-problema está associada às repercussões sociais, profissionais e\nfamiliares do uso do álcool","C":"a quantidade de doses de álcool que identifica uma mulher como bebedora excessiva é maior\nque a definida para os homens","D":"o uso nocivo é definido pelos fenômenos fisiológicos, comportamentais e cognitivos associados\na prioridade no uso de bebidas alcoólicas pelos\nindivíduos."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-334853","number":"334853","sourceNumber":"334853","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Idosa de 90 anos de idade é trazida pela filha ao pronto socorro com queixa de\nsonolência diurna, diminuição de apetite e de\naceitação hídrica há 6 dias. Há 4 dias não tem\ndormido à noite e há 2 dias não reconhece a casa e fala coisas desconexas. Filha refere que tem\nmomentos que a mãe parece quase normal. Redução de volume urinário, com alteração de cor e\nodor, e não evacua há 6 dias. Nega febre, tosse ou falta de ar. Em uso de Losartan e Metformina\nde longa data e uso de Clonazepan há 2 dias, para a insônia. Ao exame físico a paciente\napresenta-se sonolenta, não consegue manter a atenção. De acordo com o caso relatado, qual é o\ndiagnóstico provável e a conduta, respectivamente?","options":{"A":"Demência de Alzheimer - iniciar anticolinesterásico.","B":"Demência de Alzheimer com distúrbio de comportamento - iniciar antipsicótico.","C":"Delirium - identificar e tratar causas precipitantes.","D":"Delirium - introduzir antipsicótico, essencial para a resolução do quadro."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-294267","number":"294267","sourceNumber":"294267","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente esportista, de 35 anos, com queixa de fadiga, piora da performance esportiva\ne diminuição da libido, com ciclos menstruais\nregulares. Nega contraceptivo. Faz uso de cloridrato\nde sertralina, 50 mg/d, há seis meses. Orientada pelo seu \"personal trainer\", a procurar\nendocrinologista para avaliar níveis séricos de testosterona e possível terapia de reposição. Nesse\ncaso, qual é a melhor conduta para essa paciente segundo as diretrizes da Endocrine Society?","options":{"A":"Solicitar testosterona total e SHBG, na fase folicular, de preferência do terceiro ao quinto dia\ndo\nciclo menstrual.","B":"Solicitar testosterona livre e progesterona na fase lútea do ciclo menstrual.","C":"Repor testosterona, via transdérmica, para melhora da libido e fadiga, na presença de níveis\nbaixos de testosterona livre.","D":"Não há indicação para solicitar níveis séricos de testosterona para essa paciente."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-300819","number":"300819","sourceNumber":"300819","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Adolescente, 16 anos, previamente hígido, com alterações nos últimos meses de\ncomportamento, apresentando-se instável e com variações acentuadas de apetite, sono, energia e\ndeclínio no rendimento escolar. Diagnóstico provável de:","options":{"A":"Abuso de drogas.","B":"Retardo mental.","C":"Síndrome paranoide.","D":"Problemas de desenvolvimento."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-294281","number":"294281","sourceNumber":"294281","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre a prevalência de comportamento suicida e suicídio consumado, sabe-se que:","options":{"A":"a proporção de suicídio entre diversos estados brasileiros e os diversos países é bastante\nhomogênea, sugerindo-se a primazia de determinantes biológicos.","B":"apesar da grande prevalência de ideação suicida em adolescentes do sexo feminino, o suicídio\nem si não figura como importante causa de\nmorte nessa população.","C":"as maiores taxas de suicídio estão nos países altamente desenvolvidos e se correlacionam com\nperda de valores morais, ateísmo e aculturação de imigrantes.","D":"ao contrário do Brasil, a taxa mundial de suicídio vem caindo desde o início do século,\nprovavelmente fruto da implementação de estratégias de prevenção e tratamento."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-317175","number":"317175","sourceNumber":"317175","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O tabagismo é sabidamente reconhecido como um fator de risco para diversas\ndoenças, incluindo câncer. O consumo de tabaco,\nindependente da forma utilizada, é considerado\ntóxico e nocivo, não havendo nenhum limiar de segurança para o uso dessa substância. Além da\nnicotina, o cigarro contém outras substâncias. Além da nicotina, o cigarro contém outras\nsubstâncias prejudiciais à saúde como o alcatrão, o benzeno e metais pesados. Sobre o tabagismo\nassinale a questão correta:","options":{"A":"O consumo de cigarro eletrônico (pod, juul, vape) não está associado a doenças pulmonares, e,\npor isso, pode ser usado no tratamento de cessação ao tabagismo.","B":"O narguilé é menos prejudicial que o cigarro branco, já que pelo uso do sistema de refrigeração\ncom água, todas as partículas tóxicas são\nfiltradas, e, portanto, não são inaladas.","C":"O cigarro de palha, fumo de rolo, cigarro de corda, também contém folha de tabaco, e, por ter\nconcentração maior dessa substância, é considerado mais forte do que o cigarro branco.","D":"O tabagismo causa dependência física e psíquica, mas não dependência química, pois a\nnicotina não tem poder aditivo."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-294282","number":"294282","sourceNumber":"294282","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre a abordagem e o tratamento de uma pessoa em comportamento suicida, sabe-se\nque:","options":{"A":"a ineficácia de tratamentos farmacológicos em conseguir prevenir o suicídio torna a psicoterapia\no padrão-ouro para a maioria dos pacientes com\nplanejamento suicida, especialmente a terapia\ncognitivo-comportamental.","B":"em pacientes com transtornos psiquiátricos que apresentem ideação suicida grave,\nmedicamentos com alto risco de toxicidade, tais\ncomo antidepressivos tricíclicos, clozapina e lítio,\ndevem ser suspensos.","C":"a prescrição de antidepressivos estará sempre indicada devido à especificidade desse sintoma\nno diagnóstico da depressão, ainda que o efeito\ntenda a demorar várias semanas para ocorrer.","D":"além da esculta empática e psicoterapia, a indicação de eletroconvulsoterapia ou de escetamina\npodem ser realizadas no paciente com\ntranstorno depressivo maior, devido ao rápido efeito\nantisuicida."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-295370","number":"295370","sourceNumber":"295370","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Benício, de 24 anos, afirma estar tendo intenso sofrimento por não conseguir ter\ncontrole sobre algumas imagens que lhe vêm à\nconsciência a \"quase todo momento\". Diz que vê,\nem seu pensamento, repetidas vezes, a imagem de sua esposa morta e ensaguentada no chão.\nTal visualização o faz entrar em estado de \"quase desespero\" e vê a necessidade de imaginar uma\ncena agradável dos dois na praia para \"anular\" esse pensamento. Muitas vezes, acha que, se não\nfizer isso, sua esposa irá morrer antes de chegar em casa. Frequentemente, tem impulsos de\nagredir alguém com faca ou socos. Esses impulsos são vivenciados como sem contexto,\ninadequados, contra sua vontade ou seus princípios. No entanto, acontecem repetidas vezes, e ele\nacha que acontecerá uma catástrofe se não tentar isolar esse impulso repetindo a palavra 'paz' sete\nvezes. Tais sintomas se iniciaram de forma leve há cerca de sete anos e pioraram há um ano. No\nmomento, o paciente apresenta-se altamente disfuncional e em intenso sofrimento. Os sintomas\napresentados são característicos de:","options":{"A":"obsessões e compulsões.","B":"delírios e alucinações.","C":"fobias e despersonalização.","D":"confabulações e dissociação."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-317956","number":"317956","sourceNumber":"317956","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Segundo a OMS, a depressão é a quarta maior causa de ônus no mundo. Saber\nidentificar quadros psiquiátricos é uma\nnecessidade na prática médica devido aos danos causados\npor problemas psiquiátricos não diagnosticados. Sobre depressão, sabe-se que é","options":{"A":"uma doença bem estabelecida, com mecanismos etiopatogênicos identificados, tem como\nessência a diminuição nos níveis de serotonina e noradrenalina no sistema nervoso central.","B":"uma reação emocional esperada e normal frente a contextos de vida adversos, tais como:\npobreza, fome, luto e violência urbana.","C":"uma síndrome psicopatológica que pode ocorrer por inúmeras causas, tratada de maneiras\ndiferentes a depender do contexto, sintomas e evolução.","D":"um sintoma presente em várias condições clínicas diferentes (como transtorno bipolar,\nesquizofrenia, doença de Parkinson, lúpus,\nhipotireodismo) e que deve ser tratada prontamente\ncom uso de antidepressivos."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-295371","number":"295371","sourceNumber":"295371","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Marcos é um jovem de 22 anos que foi levado ao pronto-socorro por ter parado de se\nmovimentar. Há duas semanas, começou a ficar mais de 20 horas deitado e imóvel na cama,\nalgumas vezes se levanta e vai ao banheiro, e outras vezes urina na cama. Quando alguém faz\numa pergunta ou comentário, ele repetia a última palavra ou sílaba inúmeras vezes. Nos últimos\ndois dias, vem se recusando a se alimentar, não fala nenhuma palavra por dias seguidos e mantém\nposturas estranhas por horas, além de rigidez muscular. Faz uso de lítio e lamotrigina há dois anos,\napós ocorrência de um quadro maníaco e diagnóstico de transtorno bipolar. Qual é a síndrome\napresentada no momento e a conduta adequada?","options":{"A":"Síndrome depressiva - suspender lítio e iniciar fluoxetina.","B":"Síndrome dissociativa - indicar ansiolítico e psicoterapia.","C":"Síndrome psicótica - introduzir olanzapina.","D":"Síndrome catatônica - aplicar benzodiazepínico lorazepam."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-317957","number":"317957","sourceNumber":"317957","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O combate ao tabagismo passa pelo tratamento das pessoas com síndrome de\ndependência do tabaco. No Brasil, o Ministério da Saúde criou programas de tratamento que\ndisponibilizaram, via SUS, o acesso à bupropiona e adesivos de nicotina. No entanto, há perigos\nem se prescrever bupropiona para pacientes com histórico psiquiátrico. Não devem receber essa\nprescrição, pacientes que se apresentem com","options":{"A":"sintomas de mania ou bulimia nervosa.","B":"sintomas obsessivos compulsivos ou transtorno de compulsão alimentar.","C":"sintomas obsessivos compulsivos ou bulimia nervosa.","D":"transtorno de déficit de atenção e hiperatividade ou sintomas de mania."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-308256","number":"308256","sourceNumber":"308256","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Na entrevista motivacional com um dependente químico, tão importante quanto\nentender como a dependência se manifesta\nnesse indivíduo, é compreender sua motivação para a\nmudança, já que essa compreensão pode auxiliar no planejamento terapêutico de cuidados a este\npaciente. Se nesta avaliação for evidenciado que o sujeito percebe um problema em relação ao seu\nuso de substâncias, mas está ambivalente para promover mudança, com um discurso como:\n\"Talvez fosse melhor para a minha saúde se eu usasse menos, embora eu não ache que use\ndemais\", entende-se que se encontra no estágio de prontidão para a mudança conhecido como:","options":{"A":"Pré contemplação.","B":"Recaída.","C":"Ação.","D":"Contemplação."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-311951","number":"311951","sourceNumber":"311951","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Dr. Gercílio está em visita domiciliar na casa de Dona Almerinda, 92 anos, a pedido da\nfamília. Na visita anterior, há um mês, a paciente estava acamada devido a uma sequela de AVC,\nporém lúcida e orientada, em uso de Sinvastatina, Clopidogrel e Propanolol. Na visita atual, a\nfamília relata que há uma semana a paciente iniciou uso de Clonazepan gotas, receitado por um\namigo da família, para insônia. Há dois dias dona Almerinda começou a ficar muito agitada, e\nrepete a todo o momento que tem um jacaré em seu quarto. Dr. Gercílio não encontra nada digno\nde nota no Exame Físico. Dona Almerinda responde a todas as perguntas, mas apresenta confusão\nmental e agitação psicomotora. O diagnóstico mais provável e conduta nesse caso são:","options":{"A":"demência fronto-temporal; indicada a associação de um anti-psicótico ao benzodiazepínico.","B":"delirium; indicada a suspensão do Clonazepan.","C":"depressão paranoide; indicado um estabilizador do humor.","D":"demência senil; indicado aumento da dose do benzodiazepínico."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-315828","number":"315828","sourceNumber":"315828","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A etapa de avaliação é o momento em que será possível conhecer a história tabagística\n(idade de iniciação, tentativas para\ndeixar de fumar), histórico patológico (doenças\n\ntabaco-relacionadas ou não), avaliação do grau de dependência da nicotina (Teste de Fagerström),\nestágios de motivação para cessação do\ntabagismo. Sendo correto que:","options":{"A":"Essa avaliação inicial não permitirá ao profissional definir se além da abordagem cognitivo\ncomportamental o paciente necessitará de medicação e qual tipo.","B":"Essa avaliação inicial permitirá ao profissional definir se além da abordagem cognitivo\ncomportamental o paciente necessitará de medicação e qual tipo.","C":"Essa avaliação inicial permitirá ao profissional definir se além da abordagem cognitivo\ncomportamental o paciente necessitará de medicação e não qual tipo.","D":"Essa avaliação inicial nunca auxilia o profissional definir se além da abordagem cognitivo\ncomportamental o paciente necessitará de medicação e qual tipo."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-315832","number":"315832","sourceNumber":"315832","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O tratamento para cessação do tabagismo no SUS consiste no aconselhamento\nterapêutico estruturado/abordagem intensiva, acompanhado e pelo\ntratamento farmacológico.\nSendo correto o item:","options":{"A":"Composto dos seguintes medicamentos: terapia de reposição de nicotina (adesivo, goma e\npastilha) isolada ou em combinação; e cloridrato de bupropiona.","B":"Composto dos seguintes medicamentos: terapia de reposição de nicotina (adesivo, goma e\npastilha) isolada ou em combinação; e nunca cloridrato de bupropiona.","C":"Composto dos seguintes medicamentos: terapia de reposição de nicotina (adesivo, goma e não\na pastilha) isolada ou em combinação; e\ncloridrato de bupropiona.","D":"Composto dos seguintes medicamentos: terapia de reposição de nicotina (adesivo, goma e\npastilha) isolada , vetada em combinação; e cloridrato de bupropiona."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-311958","number":"311958","sourceNumber":"311958","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"São características do Transtorno de Ansiedade Generalizada a presença de\nansiedade e preocupação excessivas, acerca\nde diversos eventos ou atividades. Para se preencher\nos critérios diagnósticos para está doença em adultos, a ansiedade e a preocupação excessivas\ndevem ocorrer na maioria dos dias, por pelo menos seis meses, e estar associadas a pelo menos\ntrês outros sintomas. Assinale a alternativa que apresenta os sintomas que devem estar associados\nà ansiedade e preocupação excessivas para se preencher os critérios diagnósticos para Transtorno\nde Ansiedade Generalizada no adulto.","options":{"A":"Dificuldade em concentrar-se, fatigabilidade e perda ou ganho significativo de peso.","B":"Tensão muscular, medo acentuado acerca de um objeto ou situação e humor deprimido.","C":"Inquietação, fatigabilidade e irritabilidade.","D":"Perturbação do sono, agorafobia e dor ou desconforto torácico."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-315839","number":"315839","sourceNumber":"315839","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A partir das respostas às perguntas direcionadas recomenda-se aconselhar o fumante\na parar de fumar, adaptando as mensagens ao\nperfil do fumante levando em consideração idade,\nexistência de doenças associadas ao tabagismo, etc. Sendo correto que:","options":{"A":"A conduta não deve estar de acordo com o interesse do fumante em deixar de fumar, ou não, no\nmomento da consulta.","B":"A conduta nunca deve estar de acordo com o interesse do fumante em deixar de fumar, no\nmomento da consulta.","C":"A conduta deve estar de acordo com o interesse do fumante em deixar de fumar, ou não, no\nmomento da consulta.","D":"A conduta deve estar de acordo com o interesse do fumante em deixar de fumar, ou não, fora da\nconsulta."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-317217","number":"317217","sourceNumber":"317217","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente feminina, 42 anos, em acompanhamento na UBS por transtorno depressivo\nmaior, em uso de Sertralina, Amitriptilina e\nClonazepam, comparece na consulta com humor\ndeprimido, choro fácil, anedonia, anorexia e relatando pensamentos referentes a perda da vontade\nde viver, que o mundo seria um lugar melhor sem ela e que considerou tomar todos os\nmedicamentos juntos para poder parar de sentir dor. Qual é a conduta MAIS ADEQUADA para o\ncaso acima:","options":{"A":"Solicitar TSH e T4L, suspeitando de um possível quadro de hipotireoidismo associado.","B":"Encaminhar ao serviço de psicologia e orientar em relação a beleza da vida.","C":"Encaminhar à emergência hospitalar, devido ao quadro de ideação suicida com planejamento.","D":"Ajustar as doses das medicações em uso e encaminhar ao serviço de psiquiatria do CAPS."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-300887","number":"300887","sourceNumber":"300887","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O tabagismo passivo, de acordo com a Organização Mundial de Saúde (OMS), é\nresponsável por 1,2 milhões de mortes no mundo por ano e tem como uma das principais vítimas\nas crianças. Especialmente no período de pandemia, em que o isolamento social é uma das\nmedidas preventivas mais eficazes contra a Covid-19, uma relevante consequência na saúde\ninfantil foi a maior exposição ao tabagismo passivo pela convivência com familiares fumantes.\n\nConsiderando o tabagismo passivo em crianças, que foi potencializado durante a pandemia, e os\ndiversos danos à saúde desse grupo de pessoas, uma consequência do tabagismo passivo infantil\né:","options":{"A":"As crianças fumantes passivas têm maior probabilidade de contrair doenças respiratórias agudas\ndo que indivíduos da mesma idade sem essa\nexposição, além de que aparentemente são mais\nimunodeprimidas, pois têm maior propensão a terem associadas duas ou mais patologias.","B":"As consequências a longo prazo do convívio de crianças com tabagistas são a irritação da\nmucosa oral e nasal, olhos e pulmão da\ncriança, náuseas, cefaleia, tosse, coriza, entre outros. Além\ndisso, crianças portadoras de asma podem apresentar crises asmáticas no mesmo momento.","C":"Os efeitos instantâneos do tabagismo passivo são a maior incidência de rinite, otite, laringite,\ntonsilite, bronquite, pneumonia e aumento na\nfrequência de crises asmáticas. Dessa forma, além\ndessas doenças, ainda podem ocorrer manifestações tardias na vida desse indivíduo, havendo uma\nmaior predisposição a diversos tipos de câncer, em especial no pulmão, cardiopatias e redução da\nfunção respiratória.","D":"É uma consequência relevante da exposição de crianças à fumaça do tabaco no ambiente a\nmenor necessidade de atendimento médico para\nesse grupo. De acordo com o Departamento\nCientífico de Pneumologia da Sociedade Brasileira de Pediatria, em comparação com crianças não\nexpostas, as que sofrem com o tabagismo passivo são a menor parte dentre o número total de\npacientes pediátricos com quatro idas ou mais ao pronto- socorro por ano e com necessidade de\nantibioticoterapia duas vezes ou mais ao ano."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-300889","number":"300889","sourceNumber":"300889","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A internação psiquiátrica tem como principal objetivo atuar no manejo clínico de\npacientes disfuncionais, em quadros agudos, graves\ne que, devido ao adoecimento mental,\napresentam risco para si e para outros, ou seja, é uma modalidade de atenção destinada a\npacientes que necessitam de cuidados intensivos, cabendo à instituição hospitalar acolher, tratar,\ncuidar, respeitar e estabilizar o paciente para que ele possa ser reinserido na sociedade após\nresolução do episódio agudo. Considerando o enunciado, no contexto das modalidades de\ninternação psiquiátrica, é CORRETO afirmar:","options":{"A":"A internação compulsória é a que se dá com o consentimento expresso e por escrito de paciente\nem condições psíquicas de manifestação válida\nde vontade.","B":"A internação compulsória é a que se dá contrariamente à vontade do paciente, sem o seu\nconsentimento expresso ou com consentimento inválido. Para que ocorra, faz-se necessária a\nconcordância de representante legal, exceto nas situações de emergência médica (risco iminente\nde suicídio, agitação psicomotora grave etc.).","C":"A internação compulsória é determinada por magistrado e independe da vontade expressa da\nfamília ou do paciente.","D":"Na internação compulsória, quem determina a natureza e o tipo de tratamento a ser ministrado\nao paciente é o magistrado, que poderá prescrever\nalta hospitalar quando entender que aquele se\nencontra em condições para tal."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-273130","number":"273130","sourceNumber":"273130","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Estudos realizados demonstram associação significativa entre tabagismo e depressão,\ndistúrbio bipolar, consumo de álcool, cocaína,\ndentre outras drogas. O fumante pode vir a ter, no\ndecorrer da vida, diversos tipos de doenças, podendo, em muitos casos, vir a óbito. Acerca do\ntabagismo, é INCORRETO afirmar:","options":{"A":"Estudos evidenciaram que fumantes têm risco aumentado de adquirir tuberculose pulmonar.","B":"Metade dos fumantes morre de doenças relacionadas ao tabaco.","C":"Fumar é a segunda maior causa isolada de óbitos em todo o mundo, só perdendo para os\nacidentes automobilísticos.","D":"As principais causas de óbitos associadas ao tabagismo são as doenças cardiovasculares e a\ndoença pulmonar obstrutiva crônica."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-273139","number":"273139","sourceNumber":"273139","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Acerca do tabagismo e de suas peculiaridades, é CORRETO afirmar:","options":{"A":"A Convenção-Quadro para o Controle do Tabaco recomenda que o Brasil, país signatário, adote\napenas duas providências: informações educativas sobre os malefícios à saúde e proibição de\nfumar em ambientes públicos.","B":"Pode ser utilizada a reposição de nicotina e remédios como Bupropiona e Vareniclina.","C":"Como tratamentos farmacológicos, se encontram os programas de autoajuda e a advertência\nbreve.","D":"O tratamento do tabagista é feito de forma individual, sendo que não há recaídas em seu\nprimeiro ano."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-273140","number":"273140","sourceNumber":"273140","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A dependência é o impulso que leva a pessoa a usar uma droga de forma contínua ou\nperiódica para obter prazer. Nesse sentido, o Código Internacional de Doenças (CID) define a\ndependência do tabaco como ?um conjunto de fenômenos comportamentais, cognitivos e\nfisiológicos que se desenvolve após uso repetido e que tem como características: forte desejo de\nfumar; dificuldade em controlar seu uso; persistência no uso, a despeito de consequências nocivas;\ntolerância à nicotina aumentada e estado de abstinência?. Dessa maneira, com relação à\ndependência do tabaco:","options":{"A":"A nicotina é um reforçador positivo mediado pelo sistema dopaminérgico mesolímbico.","B":"A sua inalação e absorção em picos nas tragadas reduzem o número de receptores cerebrais\n(upregulation).","C":"A nicotina é um flavonoide presente nos vegetais Nicotiana tabacum e Nicotiana rustica,\nencontrada na folha do tabaco.","D":"Após alguns minutos, a nicotina inalada atinge o cérebro, onde age como agonista dos\nreceptores de acetilcolina presentes na superfície dos neurônios."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-257732","number":"257732","sourceNumber":"257732","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um homem com antecedente de consumo de álcool, queixa-se de piora progressiva de\nseu estado geral nas últimas duas semanas,\nalém de dificuldade para enxergar e quedas\nfrequentes. Perdeu o emprego devido à pandemia e vem consumindo quantidades crescentes de\nálcool. Está confuso, com alteração do olhar conjugado, nistagmo multidirecional e dificuldade em\nreter informações recentes. Seu exame de ressonância do crânio mostra hiperintensidades\nbitalâmicas. Qual é o tratamento de urgência para reverter seus sintomas e melhorar o\nprognóstico?","options":{"A":"Glicose endovenosa contínua.","B":"Tiamina 500 mg endovenosa, três vezes ao dia.","C":"Lactulose 30 g, via oral, três vezes ao dia.","D":"Fenitoína 300 mg endovenosa, uma vez ao dia."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-257737","number":"257737","sourceNumber":"257737","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Clara é uma mulher de 20 anos que, apesar de sempre ter tido um bom histórico\nescolar, decidiu não entrar na faculdade por\ncausa de sua ansiedade. Foi levada ao psiquiatra pela\nsua mãe e, durante a consulta, estava relutante em falar de si mesma. Dizia estar constantemente\ntensa e só em casa sentia-se à vontade. Tinha muita dificuldade de conversar com pessoas fora do\nseu círculo familiar, geralmente por começar a suar profusamente e ter taquicardia. Ficava\nparticularmente ansiosa na companhia de pessoas da mesma idade ou de pessoas que ela\nconsiderava \"muito importantes\". Tinha poucos amigos com quem se sentia à vontade. Tremia ao\nter que assinar ou preencher formulários quando estava sendo observada. Tinha muita vontade de\nnamorar e sair com os amigos. As pessoas do seu círculo de convivência a achavam muito doce e\neducada. No entanto, evitava sair com eles para restaurantes, pois começava a passar mal (tendo\ntontura, palpitações, fôlego curso) quando tentava comer com pessoas estranhas por perto que lhe\npudessem observá-la. Era vista pelas outras pessoas como \"caseira\", não por gostar de ficar em\ncasa o tempo todo, mas pelo constante medo de passar vexame na frente de outras pessoas. Clara\nnegou abuso de drogas e negou eventos traumáticos que antecedessem o surgimento dos\nsintomas. Nesse caso, qual é o provável diagnóstico?","options":{"A":"Transtorno de personalidade antissocial.","B":"Transtorno de personalidade paranoide.","C":"Transtorno de ansiedade generalizada.","D":"Transtorno de ansiedade do tipo fobia social."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-258187","number":"258187","sourceNumber":"258187","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Magda, de 35 anos, previamente hígida e sem prévio diagnóstico psiquiátrico, estava\naparentemente bem até dois dias atrás. Ontem foi trazida ao pronto-socorro por ter tentado engolir\nágua sanitária. Magda recebeu notícia sobre o assassinato do noivo em uma briga de trânsito.\n\nInicialmente, a família notou que ela reagira com uma tranquilidade incomum, não falava e\ndedicava-se a atividades repetitivas, como\ndobrar e desdobrar roupas. Algumas horas depois, deu\num grito, pegou uma garrafa de água sanitária e tentou bebê-la, sendo impedida pelo irmão. Ela\ncaiu no chão tremendo, chorando e gritando e, depois, ficou parada \"como se estivesse morta\". A\nfamília não notou movimentos tônico-clônicos ou liberação esfincteriana. Após ser levada ao\nhospital, foi se tornando mais responsiva, mas diz não se lembrar de nada que ocorreu após\nreceber a notícia da morte de seu noivo. Foi mantida em observação e teve vários episódios de\nagitação repentina, choro e gritos, durante os quais tentou arranhar o rosto e sair do quarto. Ao\nexame, mostrava-se chorosa, triste e relatando desrealização e amnésia para o episódio em que\ntentou beber água sanitária. Os exames laboratoriais de screening e o exame físico não\nconstataram alterações. Nesse caso, qual é o diagnóstico e o tratamento mais adequado para o\nquadro apresentado por Magda?","options":{"A":"Transtorno psicótico agudo; prescrição de risperidona por pelo menos quatro semanas.","B":"Episódio depressivo grave, com tentativa de suicídio; iniciar escitalopram 10 mg.","C":"Transtorno de estresse pós-traumático; iniciar fluoxetina e psicoterapia.","D":"Transtorno dissociativo; ofertar suporte emocional e psicoterapia."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-257738","number":"257738","sourceNumber":"257738","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Clara é uma mulher de 20 anos que, apesar de sempre ter tido um bom histórico\nescolar, decidiu não entrar na faculdade por\ncausa de sua ansiedade. Foi levada ao psiquiatra pela\nsua mãe e, durante a consulta, estava relutante em falar de si mesma. Dizia estar constantemente\ntensa e só em casa sentia-se à vontade. Tinha muita dificuldade de conversar com pessoas fora do\nseu círculo familiar, geralmente por começar a suar profusamente e ter taquicardia. Ficava\nparticularmente ansiosa na companhia de pessoas da mesma idade ou de pessoas que ela\nconsiderava \"muito importantes\". Tinha poucos amigos com quem se sentia à vontade. Tremia ao\nter que assinar ou preencher formulários quando estava sendo observada. Tinha muita vontade de\nnamorar e sair com os amigos. As pessoas do seu círculo de convivência a achavam muito doce e\neducada. No entanto, evitava sair com eles para restaurantes, pois começava a passar mal (tendo\ntontura, palpitações, fôlego curso) quando tentava comer com pessoas estranhas por perto que lhe\npudessem observá-la. Era vista pelas outras pessoas como \"caseira\", não por gostar de ficar em\ncasa o tempo todo, mas pelo constante medo de passar vexame na frente de outras pessoas. Clara\nnegou abuso de drogas e negou eventos traumáticos que antecedessem o surgimento dos\nsintomas. A abordagem terapêutica ideal para essa paciente é:","options":{"A":"prescrição de risperidona 2 mg e uso de técnicas de dessensibilização sistemática.","B":"prescrição de paroxetina 20 mg e técnicas de reprocessamento cognitivo.","C":"prescrição de clomipramina 75 mg e técnicas de exposição.","D":"psicoterapia em monoterapia pela ausência de benefício com medicamentos."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-258188","number":"258188","sourceNumber":"258188","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Você atende um paciente de 27 anos, do sexo masculino, com episódio depressivo\ngrave e risco de suicídio. Ele tem história\nprévia de episódios depressivos com sintomas atípicos\n(hipersonia, aumento de apetite, labilidade do humor e ausência de anedonia) e delírios de ruína.\nJá fez muito abuso de álcool, maconha e cocaína, e relatou episódios de franca irritabilidade,\ncomportamento agressivo, logorreia e aumento da impulsividade sexual e pensamentos acelerados\ncom duração de vários dias, mesmo sem estar intoxicado por drogas. Na família, há vários casos\nde suicídio e internações psiquiátricas por surtos de agressividade e agitação psicomotora. Em\nrelação à conduta medicamentosa, a prescrição adequada é:","options":{"A":"Nortríptilina, um antidepressivo tricíclico.","B":"Escitalopram, antidepressivo inibidor seletivo de recaptação de serotonina.","C":"Quetiapina, um antipsicótico de segunda geração.","D":"Lorazepam, um benzodiazepínico."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-274804","number":"274804","sourceNumber":"274804","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre o Transtorno Depressivo Maior (TDM), marque a alternativa correta.","options":{"A":"Os critérios diagnósticos do DSM-V são úteis para classificação, mas não devem ser usados\npara diagnóstico.","B":"Em pacientes com maior risco de recaída pode ser feito tratamento medicamentoso de\nmanutenção por até 2 anos.","C":"Quando decidido por tratamento medicamentoso, o mesmo deve ser usado apenas até obter\nremissão dos sintomas para evitar o desenvolvimento de dependência medicamentosa.","D":"Após iniciado tratamento medicamentoso, deve-se reavaliar o paciente em 2 semanas. Se não\nhouver melhora procede-se ao aumento da dose ou troca de antidepressivo."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-274810","number":"274810","sourceNumber":"274810","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Você está acompanhando na sua UBS (Unidade Básica de Saúde) o caso do Marcos,\nde 21 anos, pedreiro, analfabeto, solteiro,\nque mora com a avó de 80 anos e tem uma história de\ninternações em clínicas de reabilitação. Ele refere que está \"limpo\" há um ano, mas a avó procura a\nUnidade de Saúde relatando que ele foi despedido de uma obra em que estava sendo muito\nelogiado, depois de ter uma piora do desempenho no último mês. Tem tido, ainda, acessos de\nraiva, chegando a ameaçar a avó com uma faca, além de ter abandonado o campeonato de futebol\ndo bairro, onde atuava como principal zagueiro do time. Diante desse caso, podemos afirmar que:","options":{"A":"Marcos apresenta indícios de uso abusivo de substâncias psicoativas, e deve ser encaminhado\nao serviço privado e filantrópico, já que o SUS\nnão provê esse tipo de atendimento.","B":"é seu dever, como médico, confrontar Marcos de forma não preconceituosa, para estabelecer\num vínculo adequado baseado na verdade.","C":"o acompanhamento de Marcos deve ser obrigatoriamente com especialista em saúde mental, e\nele deve ser encaminhado ao serviço especializado.","D":"se Marcos concordar em comparecer a uma consulta, seu exame físico deve incluir um exame\nneurológico, já que o impacto das substâncias psicoativas no SNC é significativo, mesmo em\nindivíduos jovens."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-281321","number":"281321","sourceNumber":"281321","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A exposição ocasional ao cigarro aumentou seu risco relativo para 1,58, enquanto a\nexposição regular aumentou o risco relativo para 1,91. Sendo adequado o item:","options":{"A":"O tabagismo não constitui-se em fator de risco (FR) para a demência e seu abandono pode\nreduzir a carga de demência.","B":"O tabagismo constitui-se em fator de risco (FR) para a demência e seu abandono não pode\nreduzir a carga de demência.","C":"O tabagismo constitui-se em fator de risco (FR) para a demência e seu abandono pode reduzir a\ncarga de demência.","D":"O tabagismo constitui-se em fator de risco (FR) para a demência e seu abandono pode\naumentar a carga de demência."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-281323","number":"281323","sourceNumber":"281323","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A exposição passiva ao fumo também pode aumentar o risco de demência. Em relação\naos fumantes idosos, pode-se afirmar que:","options":{"A":"Estudos mostram que os fumantes idosos apresentam maior intenção em abandonar o cigarro\nse comparados aos jovens; mas tem, em\ncontrapartida, maior probabilidade de sucesso quando\ntentam parar de fumar.","B":"Estudos mostram que os fumantes idosos apresentam menor intenção em abandonar o cigarro\nse comparados aos jovens; menor probabilidade de\nsucesso quando tentam parar de fumar.","C":"Estudos mostram que os fumantes idosos apresentam menor intenção em abandonar o cigarro\nse comparados aos jovens; mas tem, em\ncontrapartida, maior probabilidade de sucesso quando\ntentam parar de fumar.","D":"Estudos mostram que os fumantes idosos apresentam maior intenção em abandonar o cigarro\nse não comparados aos jovens; com maior\nprobabilidade de sucesso quando tentam parar de\nfumar."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-274530","number":"274530","sourceNumber":"274530","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A queixa de insônia é frequente entre os pacientes atendidos pelo médico de família.\nem relação a insônia e a higiene do sono,\nmarque a alternativa INCORRETA:","options":{"A":"Faz parte das regras de revisão do ambiente de sono: eliminar ruídos no quarto; regular a\ntemperatura do quarto, bem como tornar o ambiente de dormir confortável; eliminar o relógio do\nquarto.","B":"Dentre as regras sobre os horários de dormir, destacam-se: controlar ou eliminar os cochilos\ndiurnos; reduzir o tempo na cama para um sono\nmais profundo e mais contínuo; manter horário fixo\npara ir para a cama.","C":"Dentre as atividades ao entardecer que conduzem ao sono, estão: prática de atividades\naeróbicas, pelo menos três vezes na semana,\ncomeçando 4 a 6 horas antes do horário de se\ndeitar; engajar-se em atividades relaxantes antes de dormir; banho quente 1 ou 2 horas antes de se\ndeitar.","D":"Dentre os medicamentos utilizados no tratamento da insônia, o uso de antidepressivos inibidores\nda recaptação de serotonina estão entre as opções\nde escolha, ainda que o paciente não\napresente transtorno de humor associado."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-274830","number":"274830","sourceNumber":"274830","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Na consulta de uma adolescente de 15 anos, qual das alternativas abaixo presente na\nhistória clínica está mais relacionado ao risco de ideação suicida?","options":{"A":"Perfeccionismo na escola.","B":"Abuso de álcool.","C":"Déficit de atenção.","D":"Classe social alta."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-241690","number":"241690","sourceNumber":"241690","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher de 74 anos, previamente hígida, é submetida a uma artroplastia de quadril. No\nsegundo pós-operatório passa a apresentar\nalteração do ciclo sono-vigília e da atenção. Não é\nesperada, nesse caso, a presença de:","options":{"A":"agitação psicomotora.","B":"alucinação visual.","C":"elevação pressórica com taquicardia.","D":"eletroencefalograma alterado.","E":"tomografia de crânio alterada."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-241694","number":"241694","sourceNumber":"241694","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Na população idosa, as medicações são apontadas como causa de delirium em até\n30% dos casos. O uso de três ou mais\nmedicações foi claramente correlacionado ao maior risco do\ndesenvolvimento de delirium, sendo a principal classe envolvida aquela de propriedades:","options":{"A":"anticolinérgicas.","B":"anti-inflamatórias.","C":"antimicrobianas.","D":"hipoglicemiantes orais.","E":"simpaticomiméticas."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-234337","number":"234337","sourceNumber":"234337","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente de 27 anos, etilista pesado há cinco anos, foi levado por transeuntes ao pronto\natendimento com perda de consciência e relato de convulsões. O plantonista avalia que a via aérea\nestá pérvia, o paciente respira de forma ruidosa, com pulsos cheios e enchimento capilar menor\nque dois segundos, saturando 92% de oxigênio ao ar ambiente. A escala de coma de Glasgow é 9.\nNesse caso, a conduta mais indicada é:","options":{"A":"Fenitoína 50 mg/ml, quatro ampolas em SF 0,9%, 250 ml venoso, em uma hora.","B":"Diazepam 10 mg, uma ampola venosa em bolus.","C":"Tomografia computadorizada de crânio, sem contraste.","D":"Tiamina 100 mg em 10 minutos, seguida de glicose 50%, 40 ml, venosos."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-232242","number":"232242","sourceNumber":"232242","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Quais são as desvantagens do uso de benzodiazepínicos em detrimento dos inibidores\nseletivos de recaptura de serotonina no tratamento desses transtornos de ansiedade: transtorno de\npânica, fobia social e transtorno de ansiedade generalizada?","options":{"A":"Eficácia inferior e maior tempo para efeito.","B":"Maior tempo para efeito e prejuízo cognitivo.","C":"Prejuízo cognitivo e risco de dependência.","D":"Risco de dependência e efeito exclusivo no alívio de crises agudas."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-234342","number":"234342","sourceNumber":"234342","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente de 23 anos, do sexo feminino, sofre desde muito cedo de ataques de pânico\nprecipitados pela necessidade de fazer exames de sangue, ver agulhas, tomar injeções e quando\nvê sangue. Ela chega a ficar dias sem dormir na expectativa de ter que vir a se deparar com esse\ntipo de situação e chega a desmaiar em algumas ocasiões, nas quais é exposta a isso. Relata que\nos mesmos sintomas também acontecem na presença de alguns animais, tais como lagartas.\n\nNesse caso, qual é, respectivamente, o diagnóstico e tratamento ideal para tal condição?","options":{"A":"Fobia específica e terapia comportamental.","B":"Transtorno de ansiedade generalizada e inibidores seletivos de recaptação de serotonina.","C":"Transtorno de pânico e inibidores seletivos de recaptação de serotonina e benzodiazepínicos na\nexposição.","D":"Agorafobia e terapia comportamental e benzodiazepínico na exposição."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-232243","number":"232243","sourceNumber":"232243","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O tratamento farmacológico da esquizofrenia, com os modernos antipsicóticos de 2ª\ngeração,","options":{"A":"tende a resultar em adequado controle dos sintomas positivos, a ter efeitos limitados nos\nsintomas negativos e a aumentar o risco de\nmortalidade cardiovascular pelos efeitos secundários\nmetabólicos.","B":"é contraindicado a menores de 15 anos de idade, dado o potencial de essas drogas causarem\nganho de peso, hiperglicemia,\nhipercolesterolemia e piora cognitiva.","C":"deve ser prescrito preferencialmente após tentativa malsucedida com psicoterapia\n\ncognitivo-comportamental e uso de medicamentos inibidores seletivos de recaptação de serotonina.","D":"traz menos efeitos colaterais metabólicos e mais eficácia contra os sintomas negativos e\ncognitivos desta doença, revolucionando seu tratamento."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-234343","number":"234343","sourceNumber":"234343","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente de 46 anos, do sexo masculino, é trazido por familiares para atendimento por\nestar \"retraído e isolado\". Há um mês não sai do quarto e nem toma banho. O paciente\n\napresenta-se apático, retraído socialmente e está há anos sem trabalhar. Não se engaja em\natividades prazerosas e nem em projetos de longo\nprazo. Fala poucas frases esparsas e\ndesconectadas e neologismos frequentes. Diz não entender o motivo de ter sido levado ao médico,\nainda que passe dias sem tomar banho e escovar os dentes. Não se sente triste. Os sintomas vêm\nse agravando há cerca de 20 anos e se iniciaram após um quadro psicótico que necessitou de\ninternação por dois meses. Nesse caso, qual seria o tratamento ideal para esse paciente?","options":{"A":"Inibidor seletivo de recaptação de serotonina e terapia cognitivo-comportamental.","B":"Antipsicótico de segunda geração e abordagem psicossocial com terapia ocupacional.","C":"Inibidor de acetilcolinesterase e reabilitação cognitiva.","D":"Sal de lítio ou divalproato de sódio associado à psicoeducação."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-231979","number":"231979","sourceNumber":"231979","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A depressão, na Atenção Primária à Saúde:","options":{"A":"é um agravo de tratamento fácil, desde que o paciente consiga atendimento médico o mais cedo\npossível para evitar as sequelas","B":"pode ser detectada em rastreamento pelo questionário PHQ-2 (Patient Health Questionnaire),\nque tem especificidade de 96% e sensibilidade de\n54%","C":"é exageradamente diagnosticada e, assim, há um excessivo uso de antidepressivos. Por isso a\nexcessiva quantidade de pessoas apresentando incapacidade pelos efeitos adversos, aguardando\nafastamento definitivo pelo INSS","D":"é prevalente em pessoas com dificuldades em lidar com seus problemas pessoais e tomar\natitudes para resolvê-los. São levadas a ter\nessa doença por ausência de uma família presente,\namigos, religião e emprego satisfatório","E":"raramente é identificada pelo médico de família ou generalista nas Unidades de Saúde Pública,\njá que tal agravo é mais prevalente em\npopulações de maior escolaridade e renda. Estas buscam\natendimento diretamente com psiquiatras de planos de saúde privados"},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-247449","number":"247449","sourceNumber":"247449","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Joana é uma jovem grávida de 26 anos que procurou a UBS para sua segunda\nconsulta de pré-natal com a sua médica de\nfamília e comunidade, Dra. Anastásia. Está atualmente\ncom 12 semanas de idade gestacional e apresenta-se sem qualquer queixa. Trouxe os exames\nlaboratoriais solicitados na primeira consulta, incluindo exame preventivo colpocitológico colhido,\npela primeira vez, antes da gestação, cujo resultado nunca havia sido analisado por nenhum\nprofissional. Ao entrar no consultório, Dra. Anastásia notou cheiro de cigarro vindo de Joana e\ndecidiu abordar a questão do tabagismo durante a consulta. Joana fuma cerca de um maço por dia\ndesde os 23 anos de idade. Quando perguntada sobre o que a levava a fumar diariamente e sobre\nseus sentimentos em relação ao uso do cigarro. Joana refere que o cigarro reduz o seu estresse.\n\nEstá desempregada e o cigarro \"\"tem sido seu maior companheiro durante o dia\"\", haja vista que\nseu esposo trabalha o dia todo e não tem lhe\ndado tanta atenção. Assim, Dra. Anastásia, levando\nem consideração os sentimentos de Joana, propôs ajudá-la a cessar com o tabagismo, inclusive\nexplicando que o mesmo poderia ser muito prejudicial para a gravidez. Apesar disso, Joana,\nrelatando não ter interesse em parar de fumar e mostrou-se pouco receptiva a proposta de\nAnastásia. Tendo em vista que a abordagem ao tabagismo tem grau A de recomendação de\nrastreamento pelo Ministério da Saúde em todos os adultos, incluindo gestantes, conclui-se que o\nestágio de mudança de comportamento do Modelo Transteórico (MTT) que Joana se encontra para\ncessação do tabagismo pode ser enquadrado em:","options":{"A":"Ação.","B":"Contemplação.","C":"Preparação.","D":"Pré-contemplação."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-234385","number":"234385","sourceNumber":"234385","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Com referência a transtornos alimentares na adolescência:","options":{"A":"O risco de suicídio nos casos de anorexia nervosa é alto, sendo causa frequente de mortes\nprematuras em pessoas com este transtorno.","B":"Os episódios recorrentes de compulsão alimentar, seguidos de sentimentos de culpa e\nautodepreciação, destacam-se entre os critérios diagnósticos de anorexia nervosa.","C":"A obesidade é de etiologia genética caracterizada por condição inflamatória e hipertrofia de\nadipócitos, com discreta influência de fatores externos.","D":"A acantose nigricans, hiperpigmentação grosseira de dobras cutâneas, quando observada em\nadolescentes obesos, sugere o diagnóstico de hipotiroidismo."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-254297","number":"254297","sourceNumber":"254297","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Renata é médica da UBS e começou a acompanhar dona Rosa, de 62 anos,\nrecentemente. Durante a consulta, Renata percebe\nque a paciente é tabagista, fumando cerca de\n30 maços-ano de cigarro comum. Tentando abordar este assunto, a médica questiona sobre o que\ndona Rosa acha da ideia de participar do grupo de cessação de tabagismo, ao qual a paciente\nresponde: \"doutora, eu adoraria participar, porque sei que tenho que parar, mas acho muito difícil\ndevido à ansiedade que eu sinto\". Pensando na entrevista motivacional como instrumento de\nabordagem para mudanças de comportamento, a melhor conduta para a senhora Rosa, nesta\nconsulta, seria:","options":{"A":"Abordar as situações de risco de recaída e como lidar com as mesmas.","B":"Orientar sobre estratégias para diminuir ou interromper o uso do cigarro.","C":"Considerar farmacoterapia (adesivo de nicotina e/ou bupropriona).","D":"Encaminhar à pneumologia para tomada de decisão compartilhada."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-246613","number":"246613","sourceNumber":"246613","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Com relação ao Transtorno de Ansiedade, assinale a alternativa correta.","options":{"A":"As abordagens como acupuntura, florais de Bach e fitoterápicos mostram evidências suficientes\npara serem recomendadas.","B":"É 2 (duas) vezes mais frequente em pessoas do sexo masculino e 5 (cinco) vezes mais\nfrequente em pessoas com histórico de ansiedade.","C":"É 2 (duas) vezes mais frequente em pessoas do sexo feminino e 10 (dez) vezes mais em\nindivíduos com história familiar de ansiedade.","D":"Os exames complementares são muito eficientes nos quadros de ansiedade.","E":"Em relação aos psicoterápicos, não há evidências de que as diferentes modalidades são\neficazes."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-202626","number":"202626","sourceNumber":"202626","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O uso de flumazenil é indicado na reversão dos efeitos sistêmicos:","options":{"A":"Do propofol.","B":"Do fentanil.","C":"Da cetamina.","D":"Da midazolam."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-202714","number":"202714","sourceNumber":"202714","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O achado mais comum no delirium é:","options":{"A":"agressividade.","B":"alucinações auditivas.","C":"convulsões.","D":"desatenção."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-201719","number":"201719","sourceNumber":"201719","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Umas das principais causas de morbidade e mortalidade iatrogênicas é a desatenção\nem relação às interações medicamentosas. Em um\npaciente realizando tratamento para transtorno\nbipolar com lítio, pode-se incorrer em grave intoxicação pelo mesmo mediante a prescrição de:","options":{"A":"Diuréticos tiazídicos e anti-inflamatórios não hormonais.","B":"Diuréticos de alça e betabloqueadores.","C":"Antidepressivos e bloqueadores de canal de cálcio.","D":"Antipsicóticos e benzodiazepínicos."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-202704","number":"202704","sourceNumber":"202704","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente do sexo feminino, de 45 anos, empresária, previamente hígida, desconhece\ncasos de transtornos mentais na família, abre\nquadro de rebaixamento do humor vital, ruminações\npessimistas e ideias de suicídio. Sem história de abuso de drogas. Exame físico sem alterações.\nHemoglobina e TSH normais. Foi diagnosticada com episódio depressivo maior. Qual é o dado\nclínico a ser pesquisado que fará maior diferença na determinação da melhor escolha terapêutica\nfarmacológica?","options":{"A":"Padrão de sono e apetite (se aumentados ou diminuídos).","B":"Presença de ansiedade patológica e ataques de pânico.","C":"Presença de outro episódio depressivo no passado.","D":"Episódio prévio de hipertimia com aumento de energia corporal."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-214140","number":"214140","sourceNumber":"214140","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O quadro denominado de Delirium tremens é um estado confusional, podendo haver\nalucinações, tremores, arriitmia cardíaca, sudorese, hipertermia e convulsões, que está associado à\nabstinência ao uso de:","options":{"A":"Crack.","B":"Cocaína.","C":"Heroína.","D":"Bebidas alcoólicas."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-216575","number":"216575","sourceNumber":"216575","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Segundo dados da Organização Mundial da Saúde (OMS), o tabagismo é a principal\ncausa de morte prevenível no mundo. Sendo\nresponsável por aproximadamente 6 milhões de morte\npor ano no mundo, devendo alcançar mais de 10 milhões de mortes anuais em 2030. Em relação à\nabordagem desta condição crônica, tem-se o seguinte:","options":{"A":"Apesar de todas as campanhas e políticas relacionadas ao tabagismo, o Brasil não conseguiu a\nredução de sua prevalência.","B":"Aconselhamento e tratamento medicamentoso são eficazes, entretanto, a combinação de ambos\napresenta eficácia superior.","C":"Em relação ao tratamento não farmacológico (aconselhamento), já foi demonstrado que a\nabordagem em grupo apresenta maior eficácia que a individual.","D":"Em relação ao tratamento farmacológico (nicotínicos e não nicotínicos), de um modo geral,\ndeve-se recorrer inicialmente à terapia combinada, pois apresenta maior eficácia."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-216645","number":"216645","sourceNumber":"216645","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Leia o texto a seguir, extraído do livro Medicina Ambulatorial: Condutas de Atenção\nPrimária Baseadas em Evidências (DUNCAN & cols, 4ª\nedição). A depressão é uma condição\nmédica relativamente comum, de curso crônico e recorrente. Está muitas vezes associada à\nincapacitação funcional e comprometimento da saúde física. Pessoas deprimidas apresentam\nlimitação das suas atividades e comprometimento do bem-estar, além de utilizarem mais os\nserviços de saúde. No entanto, a depressão segue sendo subdiagnosticada e subtratada. Entre 30\ne 60% dos casos de depressão não são detectados pelo médico em Atenção Primária à Saúde\n(APS). Muitas vezes, os pacientes deprimidos também não recebem tratamentos suficientemente\nadequados e específicos. Em APS, a mediana de prevalência de depressão está acima de 10%.\n\nEm populações específicas, como a de pacientes com infarto recente, é de 33%, chegando a 47%\nnos pacientes com câncer. A prevalência de\ndepressão é aproximadamente 2x maior em mulheres\ndo que em homens. Sobre transtorno depressivo, verifica-se o seguinte:","options":{"A":"A depressão é uma doença comum na população em geral e compromete muito a qualidade de\nvida das pessoas, porém é incomum em pacientes com outras doenças clínicas.","B":"Existem evidências de que os antidepressivos são eficazes na depressão aguda moderada a\ngrave, no entanto, não mostraram vantagens em relação ao placebo em depressões leves.","C":"O suicídio está entre as 10 principais causas de morte no mundo e o transtorno depressivo é um\nimportante fator de risco para tal; portanto, é importante salientar que perguntar sobre suicídio\ninduz estes pacientes a pensar em suicídio.","D":"Os transtornos depressivos também são condições altamente prevalentes na infância e na\nadolescência e, diante do diagnóstico, o tratamento não difere muito do adulto, porém na\ndepressão maior deve-se preferir o uso de tricíclicos."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-216508","number":"216508","sourceNumber":"216508","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Ana Luiza, 5 anos, chega ao consultório do pediatra a pedido da professora da escola\nonde estuda, com quadro de problemas na\nescola, em especial, com a sua professora. A criança\nperde a paciência com muita frequência, discute com adultos com facilidade, culpa os outros pelos\nseus erros, de forma proposital incomoda outras crianças a seu redor, além de demonstrar ira,\nressentimento, sentimento de vingança e rancor em muitos momentos. Os pais relatam o mesmo\ncomportamento em casa e fora da escola. A professora e os pais apresentam hematomas em\nregião de membros inferiores, devido às agressões constantes da criança. A mãe relata que teve\ngravidez sem intercorrências e o parto transcorreu sem problemas, porém admite ter feito uso de\ntabaco durante a gravidez. Relata que a filha sempre foi assim, imatura, parecia não aprender com\nas experiências, envolve-se com brincadeiras perigosas. O pai relata que a criança é lábil\nemocionalmente, não tolera as frustrações. Seu pai é usuário de substâncias ilícitas. Ao exame\npsíquico, mostra-se bem apresentada, consciente, agressiva, orientada, impaciente, atenção\nespontânea aumentada e voluntária diminuída, memória preservada, inteligência dentro do\nesperado, sem alterações da sensopercepção, psicomotricidade aumentada e crítica diminuída. De\nacordo com este quadro clínico, a hipótese mais provável é:","options":{"A":"Transtorno de deficit de atenção e hiperatividade.","B":"A paciente apresenta fragilidade emocional, devido à falta de limite imposto pelos pais desde\nprimeira infância, não configurando qualquer patologia.","C":"Transtorno opositor desafiante.","D":"Transtorno de ansiedade."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-173551","number":"173551","sourceNumber":"173551","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A.G.M., de 23 anos, do sexo feminino, apresenta grande preocupação em relação ao\nseu peso corporal. Diz que nos últimos\nmeses não tem conseguido se desligar desses\npensamentos e quer muito emagrecer. Apesar de seus familiares e amigos dizerem que ela está\ncom um peso adequado e o corpo muito bonito, ela se acha muito gorda e tenta seguir dietas muito\nrestritivas sem, no entanto, conseguir mantê-las por mais de dois ou três dias. Geralmente, após\num breve período de restrição alimentar, acaba tendo episódios nos quais perde o controle sobre a\nquantidade de alimentos ingeridos, come uma quantidade excessiva, se arrepende em seguida e\nusa métodos laxativos ou provoca vômitos para tentar não absorver aquelas ?calorias?. Nos\núltimos seis meses, esses episódios têm ocorrido de uma a duas vezes por semana. Ao exame:\npeso de 67 kg e altura de 160 cm. Qual é o diagnóstico da paciente, levando em consideração os\ncritérios atuais da Associação Psiquiátrica Americana (DSM-5)?","options":{"A":"Transtorno de compulsão alimentar periódica.","B":"Anorexia nervosa.","C":"Bulimia nervosa.","D":"Transtorno alimentar restritivo evitativo."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-174172","number":"174172","sourceNumber":"174172","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Qual é o sintoma que, ao ocorrer no início do quadro clínico, contraria o diagnóstico de\nanorexia nervosa em uma paciente com muito baixo peso?","options":{"A":"Distorção da imagem corporal.","B":"Perda de apetite.","C":"Episódios de compulsão alimentar.","D":"Prática de purgação."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-173556","number":"173556","sourceNumber":"173556","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um senhor de 45 anos dá entrada no pronto atendimento com um quadro de agitação\npsicomotora, agressividade e irritabilidade. Quebrou vários objetos em casa e necessitou de\ncontenção física, feita por policiais, para ser levado até o atendimento médico. Familiares relatam\nque o quadro se iniciou logo após ele ter feito grande ingesta de bebida alcóolica. A não ser nesses\nmomentos, ele não apresenta alterações de comportamento. Qual é o medicamento de uso\nparenteral adequado para o tratamento de agitação psicomotora, nesse caso?","options":{"A":"Prometazina.","B":"Clorpromazina.","C":"Diazepam.","D":"Haloperidol."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-174182","number":"174182","sourceNumber":"174182","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"L.S., de 26 anos, registro feito como do sexo masculino, geneticamente XY, diz que não\nse identifica com este gênero. Relata ter a\ncerteza de ser uma mulher e que, portanto, irá se alistar\npara fazer uma cirurgia de mudança de sexo. Trabalha como economista, tem vida social ativa,\nmora só, é independente economicamente. Queixa-se de ter sofrido muito preconceito no decorrer\nda vida, principalmente quando passou a usar roupas femininas depois dos 24 anos de idade. Só\nsente atração sexual por mulheres, com as quais mantém relações sexuais prazerosas. Trate-se de\num caso de:","options":{"A":"travestismo fetichista.","B":"transtorno delirante.","C":"transexualidade.","D":"orientação sexual egodistônica."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-185162","number":"185162","sourceNumber":"185162","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em idosos, a perda de peso involuntária pode ser causada por diversas condições,\nincluindo as psicogênicas. Entre as causas psicogênicas, destaca-se:","options":{"A":"depressão","B":"abandono social","C":"institucionalização","D":"rede de suporte fraca"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-185205","number":"185205","sourceNumber":"185205","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Juan, 57 anos, tabagista há vinte anos, um maço de cigarros/dia, sem comorbidades,\ncomparece à Unidade Básica de Saúde com\ndesejo de parar de fumar. Após avaliá-lo, médico e\npaciente optam, em decisão compartilhada, por utilizar o adesivo de nicotina. Sobre este\ntratamento, sabe-se que:","options":{"A":"as doses de nicotina devem ser reduzidas cada 2-4 semanas.","B":"é recomendado seu uso a partir do momento que o paciente começa a reduzir o número de\ncigarros/dia.","C":"é indicado em pacientes com teste de Fargerstrom menor que cinco.","D":"o adesivo deve ser aplicado sobre a pele e trocado a cada doze horas."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-178830","number":"178830","sourceNumber":"178830","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A depressão não é apenas tristeza e não é inerente ao processo de envelhecimento; é\numa doença que deve ser tratada. Entre as pessoas idosas, a depressão talvez seja o exemplo\nmais comum de uma doença com apresentação clínica inespecífica e atípica. O tratamento da\ndepressão nem sempre é fácil, por ser multifatorial, mas a farmacologia é um elo dos fatores para\ntratamento. Sobre o tratamento farmacológico da depressão em idosos, são os principais\nantidepressivos utilizados, exceto:","options":{"A":"inibidores seletivos de receptação de serotonina.","B":"antidepressivos tricíclicos.","C":"inibidores de monoaminoxidase.","D":"inibidores seletivos da recaptação de noradrenalina.","E":"inibidores seletivos de receptação de dopamina."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-150750","number":"150750","sourceNumber":"150750","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente do sexo feminino, de 53 anos, solteira, procedente do interior de Goiás, vem à\nconsulta queixando-se de problemas de pele e sentindo-se triste por ser vítima de ?preconceito?.\n\nConta que as pessoas têm se afastado dela achando que ela tem hanseníase. Relata que, há mais\nde três anos, vem apresentando lesões\nespalhadas por todo o corpo (membros, tronco e face)\nacompanhadas de intenso prurido. Diz que há pequenos ?insetos? vivendo sob sua pele e que eles\ncausam dor e coceira, além de levarem ao aparecimento de grandes lesões que chegam a sangrar.\nDiz que passa horas do dia se coçando, o que, com frequência, leva ao aparecimento de lesões\nque sangram. Ao exame, nota-se escoriações em membros, tórax, abdome e face, assim como\nlesões ulceradas recentes e presença de múltiplas cicatrizes de tamanho semelhante às ulcerações\natuais. Em locais do dorso, onde a paciente não alcança, a pele encontra-se completamente\níntegra. Biópsia realizada previamente mostra lesões cicatriciais e atividade inflamatória\ninespecífica. Relatório de um dermatologista que a atendeu há doze meses relata a hipótese de\ndermatite factícia. O quadro clínico acima é compatível com qual diagnóstico?","options":{"A":"Simulação.","B":"Transtorno obsessivo-compulsivo.","C":"Transtorno de escoriações (dermatotilexomania).","D":"Transtorno delirante persistente."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-150284","number":"150284","sourceNumber":"150284","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O transtorno obsessivo-compulsivo (TOC) é uma condição psiquiátrica de grande\nimportância epidemiológica, chegando a afetar mais de\n2% da população, segundo alguns estudos.\nO TOC:","options":{"A":"pode se manifestar com a ocorrência de imagens ou impulsos recorrentes, intrusivos e\negodistônicos. Muito frequentemente, inicia-se na infância ou adolescência e responde a\ntratamentos diversos, como, por exemplo, a psicocirurgia e o uso do antidepressivo tricíclico\nclomipramina.","B":"manifesta-se clinicamente com ideias obsessivas e rituais compulsivos. Tem etiologia\nneurobiológica bem determinada, mas responde melhor à terapia cognitivo-comportamental\nassociada a inibidores seletivos de recaptura de serotonina. Não melhora com o uso de\nantidepressivos tricíclicos.","C":"é uma condição psicologicamente determinada e deve ser tratada primordialmente com o uso de\npsicoterapia. O uso de antidepressivos promove ação ansiolítica, mas não é capaz de controlar a\nocorrência de pensamentos obsessivos.","D":"é uma doença mais prevalente entre as mulheres. Inicia-se habitualmente após os 30 anos de\nidade. Pode ser tratada com terapia cognitivo-comportamental, com psicocirurgia ou com\nantidepressivos sem ação noradrenérgica."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-150758","number":"150758","sourceNumber":"150758","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A amitriptilina é um medicamento pertencente à classe dos antidepressivos tricíclicos.\nEntre as principais indicações desse\nmedicamento, encontra-se o transtorno depressivo maior, a\ncefaleia tensional, a migrânea, a fibromialgia e a neuropatia periférica. Essa droga:","options":{"A":"É contraindicada para pacientes com infarto agudo do miocárdio e portadores de bloqueio de\nramo. A atividade antimuscarínica, antialfa-1 adrenérgica e a capacidade de bloquear canais de\nsódio no miocárdio a tornam uma droga potencialmente prejudicial para vários pacientes.","B":"Tem ação antialfa-2 adrenérgica, histamínica e antimuscarínica. A utilização na população idosa\ncom depressão é benéfica, pois está associada à melhora do sono, apetite e cognição.","C":"Modula vias noradrenérgicas, sendo essa a causa da melhora dos quadros álgicos, sem inibir a\nrecaptação de serotonina ou dopamina. É contraindicada em cardiopatas e no íleo paralítico pela\nação anticolinérgica.","D":"É contraindicada para diabéticos, hipertensos e idosos devido à capacidade de levar a ganho de\npeso, constipação intestinal, sonolência e picos hipertensivos. Apesar disso, a atividade\nnoradrenérgica e serotoninérgica a fazem um potente antidepressivo."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-149268","number":"149268","sourceNumber":"149268","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em relação ao tratamento da dependência à nicotina, aponte a afirmativa CORRETA:","options":{"A":"A bupropiona não é contraindicada em pacientes com histórico de convulsões.","B":"Deve-se oferecer terapia de reposição de nicotina e bupropiona a todos os indivíduos que\ninformam fumar logo após o despertar.","C":"Após o estabelecimento de obstrução grave ao fluxo aéreo, ou após os 65 anos de vida, a\ninterrupção do tabagismo não oferece mais benefício.","D":"A abordagem cognitivo-comportamental deve ser realizada em todos os fumantes\nindependentemente do escore de Fagerström."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-149283","number":"149283","sourceNumber":"149283","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um paciente de 71 anos, obeso e hipertenso, vem ao consultório informando que\nprecisa de ajuda para parar de fumar. A\nanamnese permite identificar que o paciente fuma uma\nmédia de trinta cigarros ao dia, sendo o primeiro logo após acordar pela manhã, havendo\nconcentração do maior número de cigarros neste período do dia. Ele também tem dificuldade de\nficar sem fumar em lugares onde o fumo é proibido. Com relação a esse caso, é CORRETO afirmar\nque:","options":{"A":"As informações descritas são insuficientes para avaliar o grau de dependência do paciente.","B":"O paciente não teria benefício significativo em deixar de fumar devido à sua idade.","C":"O tratamento para esse paciente não deve incluir a prescrição de bupropiona.","D":"A realização de consultas semanais de aconselhamento com o médico durante um mês\naumentaria a chance do paciente\n\nabandonar o fumo."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-160474","number":"160474","sourceNumber":"160474","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Queixas relacionadas à saúde mental são cada vez mais presentes nos consultórios de\natenção primária. Sobre a abordagem e tratamento destas, sabe-se que","options":{"A":"o uso de antidepressivos na distimia é desaconselhado.","B":"a presença de um quadro psicótico exclui a possibilidade de ser um episódio depressivo.","C":"antidepressivos não mostraram vantagens em relação ao placebo no tratamento de episódios\ndepressivos leves.","D":"a esquizofrenia é mais comum após os cinquenta anos de idade."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-157032","number":"157032","sourceNumber":"157032","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mesmo sendo considerado um importante problema de saúde pública, o alcoolismo\ncostuma em seus estágios finais ser\nidentificado apenas quando já ocorreram grandes perdas e as\nchances de reabilitação do indivíduo são menores. O consumo de álcool é, em geral, socialmente\naceito, o que provoca grande dificuldade na classificação do estado em que se encontram os\nusuários. A alternativa que define o padrão e as implicações do consumo de álcool é:","options":{"A":"A vulnerabilidade individual à dependência do álcool se desenvolve em função de fatores\ngenéticos.","B":"A definição de um bebedor-problema está associada às repercussões sociais, profissionais e\nfamiliares do uso do álcool.","C":"A quantidade de doses de álcool que identifica uma mulher como bebedora excessiva é maior\nque a definida para os homens.","D":"O uso nocivo é definido pelos fenômenos fisiológicos, comportamentais e cognitivos\nassociados a prioridade no uso de bebidas alcoólicas pelos indivíduos."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-150268","number":"150268","sourceNumber":"150268","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Durante a consulta pediátrica, a mãe de um adolescente de 13 anos refere que ele tem\nacordado durante a madrugada emitindo gritos, apresentando sudorese e choro de início abrupto,\npor cerca de dois minutos. Apesar de ser consolado, não se acalma. Na maioria das vezes, dorme\nnovamente como se nada tivesse acontecido, não se lembrando do fato ao despertar. Qual é o\ntranstorno do sono caracterizado pela descrição apresentada?","options":{"A":"Dissonia.","B":"Despertar confusional.","C":"Sonambulismo.","D":"Terror noturno."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-157343","number":"157343","sourceNumber":"157343","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A saúde mental não está dissociada da saúde geral, portanto faz-se necessário\nreconhecer que as demandas de saúde mental\nestão presentes em diversas queixas relatadas\npelos pacientes que chegam aos serviços de saúde, em especial da atenção básica. A atual política\nde saúde mental brasileira é resultado da mobilização de usuários, familiares e trabalhadores da\nsaúde iniciada na década de 1980 com o objetivo de mudar a realidade dos manicômios onde\nviviam mais de 100 mil pessoas com transtornos mentais. As práticas em saúde mental na atenção\nbásica podem e devem ser realizadas por todos os profissionais de saúde, fato que unifica o\nobjetivo dos profissionais para cuidado em saúde mental. São ações que podem ser realizadas por\ntodos os profissionais da atenção básica, nos mais diversos dispositivos de cuidado na saúde\nmental, EXCETO:","options":{"A":"Proporcionar ao usuário do serviço de saúde um momento para pensar/refletir.","B":"Exercer boa comunicação e exercitar a habilidade de empatia com o usuário do serviço de\nsaúde.","C":"Lembrar-se de escutar o que o usuário precisa dizer.","D":"Acolher o usuário e suas queixas emocionais como legítimas.","E":"Oferecer suporte de forma parcial, na medida certa, ou seja, numa medida em que o usuário se\ntorne dependente de um profissional com a finalidade de manter e estabelecer o vínculo."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-140612","number":"140612","sourceNumber":"140612","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente de 47 anos, trabalhador rural, homem, chega ao consultório com quadro de\nhumor deprimido, anedonia, pensamentos de morte e insônia há mais de 03 meses. Relata uso de\nmedicações para hipertensão, arritmia e diabetes. Considerando o quadro e comorbidades deste\npaciente, qual das medicações a seguir deve ser evitada?","options":{"A":"Amtriptilina","B":"Venlafaxina","C":"Sertralina","D":"Bupropiona"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-127712","number":"127712","sourceNumber":"127712","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente do sexo feminino, de 28 anos, apresenta sobrepeso. Queixou-se de\ndesenvolver, há um ano, \"compulsão alimentar\"\ne aumento de peso, principal razão da consulta.\nNota-se que, nesse período, apresenta humor depressivo (porém com reatividade a estímulos\npositivos), aumento de apetite, ansiedade patológica, hipersonia, dificuldade de concentração,\nlentificação psicomotora, preocupação excessiva com o ganho de peso e pensamentos suicidas\ntransitórios. Houve um período curto (menos de uma semana) em que apresentou vários sintomas\ntípicos de hipomania. Nega uso de drogas ou de medicamentos para emagrecer. TSH e T4 livre\nnormais, hemograma normal. A melhor proposta terapêutica é:","options":{"A":"Sibutramina e psicoterapia.","B":"Fluoxetina e acompanhamento nutricional.","C":"Lítio e psicoterapia.","D":"Topiramato e acompanhamento nutricional."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-127718","number":"127718","sourceNumber":"127718","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O uso de antidepressivos é feito em larga escala. A respeito do seu emprego em clínica\nmédica, pode-se afirmar o seguinte:","options":{"A":"A bupropiona é indicada em pacientes com bulimia, pois, além de diminuir a compulsão\nalimentar, causa perda de peso e melhora da autoestima.","B":"Os inibidores seletivos de recaptura de serotonina são considerados a primeira escolha no\ntratamento do transtorno depressivo maior pela eficácia superior aos tricíclicos.","C":"A sertralina, a paroxetina e a escitalopram são a primeira escolha no tratamento de alguns\ntranstornos de ansiedade, como a agorafobia, a fobia específica e a fobia social.","D":"Os pacientes com anorexia nervosa, que apresentam grave perda de peso e se recusam a\nalimentar, beneficiam-se do uso da fluoxetina."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-138187","number":"138187","sourceNumber":"138187","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O delírio é um dos temas mais estudados da psicopatologia. Sabe-se que o delírio","options":{"A":"é patognomônico da esquizofrenia paranoide quando, na ausência de alterações do humor, é de\ntemática persecutória.","B":"pode ser tanto do tipo auditivo quanto do visual, sendo o primeiro mais comum da esquizofrenia\ne o último mais comum das encefalopatias\nagudas que repercutem com delirium.","C":"é definido como verdadeiro (primário) quando for bem sistematizado e com coerência interna.","D":"é diferente do delirium, que é uma síndrome com rebaixamento de nível de consciência, pois ele\né uma alteração do juízo que ocorre mesmo com manutenção do nível consciência."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-136966","number":"136966","sourceNumber":"136966","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Situações envolvendo a saúde mental são bastante corriqueiras no dia a dia da atenção\nprimária à saúde. Em relação a esses casos, constitui indicação de encaminhamento ao\nespecialista focal (psiquiatra):","options":{"A":"Pacientes com episódio depressivo moderado ou grave.","B":"Refratariedade ao tratamento ou dúvida diagnóstica.","C":"Pacientes com quadros psicóticos agudos ou crônicos.","D":"Pacientes em uso de múltiplas substâncias psicoativas."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-136975","number":"136975","sourceNumber":"136975","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"As campanhas contra o tabagismo e a diminuição da publicidade a favor deste têm\nlevado pessoas a buscarem tratamento na atenção primária para cessar o uso do cigarro. Nesse\ncontexto e em relação ao tratamento medicamentoso do tabagismo:","options":{"A":"Recomenda-se iniciar o tratamento com bupropiona uma semana antes da data programada\npara a cessação.","B":"Recomenda-se iniciar o uso de adesivos de nicotina dez dias antes da data marcada para a\ncessação.","C":"O tratamento com bupropiona deve ser iniciado na data esperada para deixar o cigarro.","D":"A presença de transtornos de ansiedade ou depressão maior contraindicam o uso de\nbupropiona."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-110220","number":"110220","sourceNumber":"110220","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"No tratamento ao tabagismo dispomos de diversas técnicas (abordagem breve,\nentrevista motivacional, grupos operativos e\natendimento ambulatorial). Sobre estas técnicas,\nsabe-se que:","options":{"A":"A abordagem breve somente pode ser realizada na equipe de saúde da família pelo médico e\npelo enfermeiro;","B":"o estágio da pré-contemplação é o momento em que o profissional deve ser mais atuante e\ndiretivo com o paciente para a cessação do tabagismo;","C":"grupos operativos têm mostrado resultados inferiores ao tratamento individual ambulatorial;","D":"recaídas são esperadas e o paciente deve ser preparado para enfrentá-las."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-101189","number":"101189","sourceNumber":"101189","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sr. Everaldo, 38 anos, dá entrada em unidade de pronto atendimento acompanhado de\nsua esposa. Ela se queixa de que, há cerca de\ndois dias, o paciente está ?estranho?, pois tem tido\npercepções que não são compartilhadas pelo restante da família, tais como ouvir vozes de pessoas\nque não estão presentes e ver bichos andando pelas paredes. Na entrevista, o paciente reclama de\nhaver um fio enrolado em suas pernas e passa o tempo todo tentando desenrolá-lo. O fio é, no\nentanto, inexistente. Diz ainda que está dentro de uma igreja e fora levado ali para se confessar. A\nesposa nega que ele tenha tido sintomas psiquiátricos previamente e nega outros problemas de\nsaúde. Nega tabagismo, fez uso esporádico de maconha na adolescência e nos últimos anos tem\nbebido cerca de um litro de bebida destilada diariamente. A acompanhante diz, entretanto, que há\ncerca de uma semana ele reduziu bastante o consumo, na tentativa de abandonar o vício. Ao\nexame, apresenta-se com mucosas normocoradas; anictérico; acianótico; desidratado +/4+;\nsudoreico; desorientado no tempo e espaço, confuso e ansioso. Pressão arterial é de 150 x 96\nmmHg; frequência cardíaca de 130 bpm e frequência respiratória de 24 irpm. Glicemia capilar\n(HGT): 71 mg/dl. A principal hipótese diagnóstica e a conduta terapêutica adequada são,\nrespectivamente:","options":{"A":"Delirium tremens. Prescrever haloperidol 5 mg por via intramuscular, soro glicosado por via\nintravenosa e encaminhar para unidade psiquiátrica para manejo adequado dos sintomas\npsicóticos.","B":"Desidratação sobreposta à esquizofrenia paranoide. Prescrever soro fisiológico por via\nintravenosa, haloperidol 5 mg, por via oral, e\nencaminhar para tratamento psiquiátrico ambulatorial\napós estabilização do quadro de desidratação.","C":"Síndrome de abstinência alcoólica. Prescrever diazepam 10 mg por via oral, a cada hora (até o\nmáximo de 60 mg por dia), soro fisiológico via intravenosa, tiamina 100 mg por via intramuscular e\nmanter o paciente em unidade clínica devido à gravidade do quadro clínico.","D":"Transtorno psicótico agudo induzido por álcool. Prescrever haloperidol 5 mg por via\nintramuscular, soro fisiológico por via intravenosa, tiamina 100 mg por via intramuscular e\n\nencaminhar para unidade psiquiátrica."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-109347","number":"109347","sourceNumber":"109347","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"L.I.L.S., do sexo masculino, de 18 anos, estudante universitário, se diz \"assombrado\npor imagens e pensamentos de machucar, ferir,\nagredir outras pessoas\" e teme realizá-los. Diz que\neles são recorrentes, incontroláveis e desprovidos de contexto. \"Não tenho motivos para querer\nagredir determinada pessoa e, de repente, me vem aquele impulso de bater nela, o que me deixa\nmuito angustiado\". \"É como se eu me visse batendo nos outros, podendo ser minha mãe, minha\nnamorada ou até um desconhecido na rua. Sofro muito para tirar isso da cabeça e não fazer\naquilo\". Diz que tem rezado muito após a emergência do quadro como forma de tentar o alívio, já\nque isso tem trazido muito sofrimento e prejuízo tanto na sua vida social quanto na acadêmica por\nserem intensos e frequentes. O quadro se iniciou há mais de um ano e vem piorando\nprogressivamente. A descrição clínica é compatível com:","options":{"A":"delírios primários, indicando a esquizofrenia paranoica de como principal hipótese diagnóstica.","B":"alucinações visuais, indicando a necessidade de exames complementares, como ressonância\nmagnética de crânio, pela possibilidade de apresentar alguma doença cerebral (neoplasia, por\nexemplo).","C":"obsessões e compulsões, indicando o transtorno obssessivo-compulsivo como principal hipótese\ndiagnóstica.","D":"perda de controle dos impulsos, indicando algum subtipo de transtorno de controle dos impulsos\n(como o transtorno explosivo intermitente) como principal hipótese diangóstica."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-109171","number":"109171","sourceNumber":"109171","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O rebaixamento do nível de consciência é caracteristicamente observado no seguinte\ntranstorno mental:","options":{"A":"Esquizofrenia;","B":"Delirium;","C":"Depressão;","D":"Demência."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-109362","number":"109362","sourceNumber":"109362","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"As evidências disponíveis, baseadas em estudos clínico e epidemiológicos, em relação\nao comportamento suicida, indicam que:","options":{"A":"a indagação de pensamentos suicidas a alguém que procura atendimento médico por um motivo\nqualquer é desconselhável, caso o paciente não o tenha relatado espontaneamente, sob risco de\nfazer com que ele passe a ver no suicídio uma possível saída para seus problemas.","B":"as pessoas que falam muito sobre ter vontade de se matar para familiares e amigos apresentam\npouco risco de cometer suicídio,\nsugerindo-se que esse comportamento seja provavelmente pela\nnecessidade de chamar atenção para si.","C":"a determinação de uma causa única para a maioria das tentativas de suicídio é possível.\n\nEntretanto, sabe-se serem ineficazes as medidas de prevenção de novas tentativas.","D":"o número de mortes por suicídio, no Brasil, é maior em homens do que em mulheres, embora\nocorram mais tentativas em mulheres."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-103721","number":"103721","sourceNumber":"103721","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O abandono do tabagismo é uma recomendação muito importante na prevenção da\ndoença cardiovascular, cerebrovascular e renal.\nSobre o manejo de tabagistas, é CORRETO\nafirmar que:","options":{"A":"o objetivo do tratamento farmacológico é minimizar os sintomas da síndrome de abstinência.","B":"fumantes que fumam o primeiro cigarro depois de uma hora ao acordar devem receber\ntratamento medicamentoso no início do acompanhamento.","C":"muitas vezes a monoterapia não é eficaz, e a pessoa necessita utilizar mais de uma droga para\nobter êxito no tratamento.","D":"os medicamentos de primeira escolha são a nortriptilina e a clonidina."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-85777","number":"85777","sourceNumber":"85777","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Com relação ao diagnóstico de depressão, qual dos sintomas abaixo é fundamental?","options":{"A":"Perda de prazer ou interesse.","B":"Concentração e atenção reduzidas.","C":"Autoestima reduzida.","D":"Ideação suicida.","E":"Ideias de culpa ou inutilidade."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-78115","number":"78115","sourceNumber":"78115","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sabe-se que o anestesiologista, quando comparado a outros especialistas, sofre maior\nincidência das seguintes patologias:","options":{"A":"cefaleia, distúrbios do sono e úlcera gastroduodenal.","B":"conjuntivite, artrite e otite.","C":"febre, tuberculose e hepatite.","D":"precordial, gastroenterocolite e varizes."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-85778","number":"85778","sourceNumber":"85778","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um menino de 9 anos de idade é sempre rejeitado pelos companheiros. Ninguém quer\nsentar-se perto dele. Ele nunca é convidado para as festas de aniversário. Às vezes se indispõe\ncom os colegas dado seu comportamento agressivo. Faz comentários satíricos e diz gracejos dos\nquais ninguém ri. Frequentemente se autoelogia e fica agressivo quando em desacordo com um\ncolega. Qual das formas seguintes de tratamento tem mais probabilidade de ser eficaz para essa\ncriança?","options":{"A":"Metilfenidato.","B":"Treinamento de Sociabilidade.","C":"Psicoterapia.","D":"Modificação Comportamental.","E":"Colônia de Férias."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-78149","number":"78149","sourceNumber":"78149","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A esquizofrenia afeta cerca de 1% da população em todas as classes sociais e tem\nnotável impacto na vida dos pacientes acometidos\ne de seus familiares. Seu diagnóstico é clínico, e\nos sintomas que melhor a descrevem são:","options":{"A":"ilusões auditivas, frouxidão de associações, rebaixamento do nível de consciência e afeto\nembotado.","B":"ilusões auditivas e visuais, pensamento delirante, pragmatismo comprometido e labilidade do\nhumor.","C":"alucinações auditivas, nível de consciência preservado, pensamento delirante e abulia.","D":"alucinações auditivas e visuais, rebaixamento do nível de consciência, pensamento empobrecido\ne afeto embotado."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-78150","number":"78150","sourceNumber":"78150","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A síndrome neuroléptica maligna é uma complicação associada ao uso de\nantipsicóticos. Embora rara, é considerada grave e\nsua ocorrência está associada a uma taxa de\nmortalidade entre 20 e 30%. Constitui um sintoma tipicamente encontrado em pacientes nesta\ncondição:","options":{"A":"hiperpirexia","B":"ideação suicida","C":"agranulocitose","D":"diarreia profusa"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-85796","number":"85796","sourceNumber":"85796","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"No diagnóstico diferencial de Delirium é correto dizer que:","options":{"A":"Seu início tende a ser insidioso.","B":"Tem um curso progressivo.","C":"O paciente apresenta memória intacta.","D":"É comum a psicose.","E":"Mantém normal o estado de consciência e orientação."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-78077","number":"78077","sourceNumber":"78077","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Os transtornos mentais de maior prevalência, segundo estudos epidemiológicos\nrealizados na população que frequenta os\nserviços de atenção básica no Brasil, são os:","options":{"A":"depressivos.","B":"psicóticos.","C":"somatóformes.","D":"relacionados ao álcool."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-62729","number":"62729","sourceNumber":"62729","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Os transtornos de ansiedade têm elevada prevalência na população geral e podem\nlevar a significativo comprometimento\nsócio-ocupacional nos indivíduos acometidos. Dentre esses\ntranstornos, o do pânico:","options":{"A":"acomete homens e mulheres na mesma proporção.","B":"caracteriza-se pela presença de ataques de pânico espontâneos e recorrentes.","C":"tem na agorafobia um critério fundamental para seu diagnóstico.","D":"tem o tratamento medicamentoso limitado ao uso de benzodiazepínicos associados à\npsicoterapia."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-62739","number":"62739","sourceNumber":"62739","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"No Transtorno de Estresse Pós-Traumático (TEPT),","options":{"A":"os sintomas têm resolução espontânea em, no máximo, um mês após o evento traumático.","B":"a presença da amnésia de partes importantes do evento traumático exclui o diagnóstico","C":"o componente ambiental (trauma) é fundamental para o seu surgimento.","D":"a psicoterapia apresenta baixa eficácia no tratamento."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-61800","number":"61800","sourceNumber":"61800","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O Plano Integrado de Enfrentamento ao Crack e outras Drogas, com vistas à prevenção\ndo uso, ao tratamento e à reinserção social de\nusuários e ao enfrentamento do tráfico de crack e\noutras drogas ilícitas tem como objetivos:","options":{"A":"Estruturar, integrar, articular e ampliar as ações voltadas à prevenção do uso, tratamento e\nreinserção social de usuários de crack e outras drogas, contemplando a participação dos familiares\ne a atenção aos públicos vulneráveis, entre outros, crianças, adolescentes e população em\nsituação de rua;","B":"Estruturar, ampliar e fortalecer as redes de atenção à saúde e de assistência social para\nusuários de crack e outras drogas, por meio\nda articulação das ações do Sistema Único de Saúde -\nSUS em detrimento das ações do Sistema Único de Assistência Social I SUAS;","C":"Capacitar, de forma continuada, os atores governamentais e não governamentais envolvidos\napenas nas ações voltadas à prevenção do uso e ao tratamento de usuários de crack e outras\ndrogas e ao enfrentamento do tráfico de drogas ilícitas;","D":"Restringir os limites de participação comunitária nas políticas e ações de prevenção do uso,\ntratamento, reinserção social e ocupacional de usuários de crack e outras drogas e fomentar a\nmultiplicação de boas práticas;","E":"Fortalecer as ações de enfrentamento ao tráfico de crack e outras drogas ilícitas em todo o\nterritório nacional, com ênfase nos grandes centros urbanos."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-61833","number":"61833","sourceNumber":"61833","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Com relação aos quadros de delirium, podemos afirmar que:","options":{"A":"São quadros de instalação insidiosa, geralmente relacionados a processos degenerativos do\nSNC.","B":"Nos quadros de delirium o nível de consciência está preservado.","C":"São quadros irreversíveis.","D":"São causados por processos infecciosos, distúrbios metabólicos e hidroeletrolíticos.","E":"São secundários a lesões focais do tronco encefálico."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-48503","number":"48503","sourceNumber":"48503","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Toxicômano dá entrada na emergência com crise convulsiva. O médico que o atende\nsuspeita de intoxicação aguda por cocaína, porque há concomitantemente:","options":{"A":"Hipotermia e nistagmo.","B":"Arritmia cardíaca e nistagmo.","C":"Arritmia cardíaca e hipertermia.","D":"Hipotermia e hipertensão arterial.","E":"Hipotermia e hipotensão arterial."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-47704","number":"47704","sourceNumber":"47704","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Um paciente comparece ao consultório psiquiátrico alegando ter um problema, pois\nsofre, há anos, prejuízos em compras que faz\nem lojas, supermercados etc. Se compra\nmercadorias das quais se arrepende ou se elas têm algum defeito, não consegue voltar à loja para\ndevolvê-las ou reclamar, porque isso lhe gera tremendo desconforto, ansiedade e insegurança.\n\nDiante dessa queixa, o psiquiatra deve ter, como primeira hipótese diagnóstica:","options":{"A":"Transtorno de ansiedade generalizada.","B":"Distimia.","C":"Transtorno afetivo bipolar, com comprar compulsivo.","D":"Fobia social."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-34052","number":"34052","sourceNumber":"34052","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Quanto a efeitos dos psicofármacos, constata-se que:","options":{"A":"Os chamados antipsicóticos atípicos exercem, em sua maioria, ações agonistas dopaminérgica e\nserotoninérgica.","B":"Os efeitos dopaminérgicos centrais da modafinila são mais difusos se comparados aos do\nmetilfenidato.","C":"A mirtazapina exerce bloqueio de receptores alfa-2,\n5HT-2 e 5HT-3.","D":"Os efeitos dos antidepressivos tricíclicos sobre a neurotransmissão noradrenérgica são mais\npotentes entre as aminas terciárias do que entre as secundárias."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-35655","number":"35655","sourceNumber":"35655","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Adolescente de 15 anos procura médico com queixa de amenorreia há 4 meses. Refere\nperda de 20 kg ( peso anterior de 60 kg )\nno último ano, após iniciar regime alimentar. Apesar da\nperda de peso, acha que ainda precisa perder ??mais uns quilinhos?? para chegar ao seu peso\nideal. A respeito desse caso podemos afirmar que:","options":{"A":"Deve-se investigar o uso de fórmulas de emagrecimento, além de outros comportamentos\norientados à perda de peso.","B":"Provavelmente trata-se de um quadro de depressão psicótica caracterizada por idéias de menos\nvalia acerca do seu corpo.","C":"É importante investigar a ocorrência pregressa de surtos psicóticos e a história familiar de\nesquizofrenia para a elucidação diagnóstica.","D":"Deve-se inicialmente afastar a hipótese de tumor hipofisário, uma vez que estes se apresentam\ncom grande frequência em adolescentes do sexo\nfeminino.","E":"É importante investigar insuficiência ovariana, que poderia ser responsável pela perda de peso\ninicial e pela amenorreia."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-35679","number":"35679","sourceNumber":"35679","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher de 33 anos é trazida ao Pronto Socorro pelo marido com agitação psicomotora\nhá doze horas. O marido relata que ela tem\nestado muito irritada há dois dias por acreditar que vem\nsendo traída. Conta que sempre foi uma pessoa normal e que nunca chegou a ficar da maneira que\nse encontra agora (chegou a jogar objetos domésticos, como pratos e copos, pela janela). Por fim\nrelata estarem passando por uma crise no casamento. A paciente diz ter certeza da traição pelo\nfato do marido ter passado a chegar todo dia mais cedo em casa. A melhor conduta inicial, neste\ncaso, seria:","options":{"A":"Conversar reservadamente com o marido a fim de investigar se ele de fato tem um\nrelacionamento extraconjugal, o que explicaria a reação da paciente.","B":"Administrar diazepam 5 mg por via intramuscular e aguardar que a paciente se acalme para\nproceder à anamnese.","C":"Explicar ao casal que crises de ciúmes são comuns e encaminhá-los para terapia de casal.","D":"Instituir tratamento com antidepressivos e encaminhá-la para psicoterapia de apoio.","E":"Estabelecer investigação clínica para afastar quadro psiquiátrico de origem orgânica."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-23034","number":"23034","sourceNumber":"23034","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Leia o caso clínico a seguir. Mulher de 28 anos de idade, casada, mãe de duas filhas,\nencaminhada ao psiquiatra pelo dermatologista após a terceira vez que compareceu ao consultório\ndesse profissional. As consultas foram motivadas pelo aparecimento de lesões erosivas nos\njoelhos, que após exames inconclusivos ou negativos para as hipóteses diagnósticas aventadas e,\nmesmo após prescrição de cicatrizantes, estavam piorando. Na última consulta, pressionada pelo\nmarido que a flagrara ajoelhando-se repetidamente em chão áspero, contou a seguinte história: ela,\ncatólica devota desde criança, três anos antes da consulta começou a ter a mente invadida por\nimagens em que se via tendo relações sexuais com esculturas de Cristo e dos santos existentes na\nigreja. Inicialmente, isso só acontecia pouco e só quando se encontrava na igreja. Aumentou\ngradativamente e, por fim, as imagens intrusas entravam em sua mente centenas de vezes ao dia,\nem qualquer lugar. A única coisa que lhe aliviava a culpa era pedir perdão a Deus, de joelhos,\nrepetidamente. Já não conseguia mais cumprir sua agenda doméstica, tantas eram as interrupções.\nEscondeu o problema das pessoas, de medo que a julgassem louca. Ajoelhava-se tanto nos\núltimos meses, que feriu os joelhos, o que chamou a atenção do marido, que a levou ao\ndermatologista. O quadro clínico descrito preenche os critérios para:","options":{"A":"Transtorno esquizofreniforme.","B":"Transtorno de estresse pós-traumático.","C":"Transtorno obsessivo-compulsivo.","D":"Transtorno delirante crônico."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-23035","number":"23035","sourceNumber":"23035","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Do ponto de vista da psicopatologia fenomenológica, a recusa em se alimentar, que\nnormalmente é acompanhada de perda significativa de peso, que ocorre principalmente em\npacientes esquizofrênicos, sob a justificativa de que querem envenená-los, recebe o nome de:","options":{"A":"Anorexia mental.","B":"Sitiofobia.","C":"Bulimia nervosa.","D":"Percepção delirante."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-26992","number":"26992","sourceNumber":"26992","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Transtorno do Déficit de Atenção é frequentemente diagnosticado durante a vida\nescolar. Isto se deve ao fato de:","options":{"A":"A doença se iniciar normalmente após os 7 anos de idade.","B":"A doença determinar regressão do desenvolvimento neuropsicomotor.","C":"A doença cursar com baixo rendimento escolar, a despeito da inteligência ser habitualmente\nnormal.","D":"As escolas aplicarem testes específicos para este diagnóstico no ato na matrícula escolar.","E":"Incapacidade da criança de desenvolver habilidades esportivas."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-22974","number":"22974","sourceNumber":"22974","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A Terapia Comunitária, sistematizada há mais de 20 (vinte) anos no Ceará, pelo\npsiquiatra Adalberto Barreto, hoje presente em\nvários cenários da saúde pública brasileira, possui\ncomo pilar teórico a:","options":{"A":"antropologia cultural.","B":"teoria da gestalt de Fritz Pearls.","C":"pedagogia piagetiana.","D":"psicanálise freudiana."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-23038","number":"23038","sourceNumber":"23038","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Uma adolescente de 14 anos, do sexo feminino, procura atendimento médico,\nacompanhada de sua mãe, devido à perda de peso\nexcessiva. A mãe relata que a adolescente\npermanecia longos períodos no banheiro para induzir vômitos. A adolescente confirma a história e\nrefere uso de laxante. Ciclo menstrual irregular com amenorreia há quatro meses. Exame físico:\npeso: 35 Kg (< p3), Estatura: 168 cm (p 90), IMC: 12,41 Kg/m2 (<p3), PA 100/70 mmHg, FC: 70\nbpm. Considerando a provável hipótese diagnóstica, o principal sinal de gravidade é a:","options":{"A":"hiponatremia.","B":"alcalose hiperclorêmica.","C":"acidose hipoclorêmica.","D":"hipopotassemia."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-9272","number":"9272","sourceNumber":"9272","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O diagnóstico de transtorno de personalidade baseia-se, fundamentalmente:","options":{"A":"no quadro psicopatológico.","B":"na curva de vida + exames complementares.","C":"na curva de vida.","D":"na avaliação realizada pelo exame neuropsicológico."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-9275","number":"9275","sourceNumber":"9275","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A mania e a hipomania não justificadas por doenças orgânicas ou uso de drogas\ncaracterizam o transtorno do humor bipolar. Com grande frequência, pacientes com esse\ndiagnóstico tendem a apresentar:","options":{"A":"sintomatologia mista, com agitação e pensamentos negativistas.","B":"comportamento de risco.","C":"vulnerabilidade aumentada ao transtorno esquizofrênico.","D":"pseudoalucinações visuais com zoopsias e micropsias."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-9291","number":"9291","sourceNumber":"9291","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O artigo ?Prevalência de Distúrbios Psiquiátricos Menores (DPM) na cidade de Pelotas\n\n- RS?, publicado na Revista Brasileira de Epidemiologia, vol. 5 n.2, 2002, apresenta, conforme a\ntabela abaixo, os seguintes resultados:\n\nDos dados da tabela, conclui-se que: (VER IMAGEM)","options":{"A":"o consumo de álcool, por pacientes que responderam sim, ingerem menos de 30 g/dia, quando\ncomparados com pacientes que não consomem álcool, é um fator de proteção para DPM e é\nestatisticamente significante.","B":"a classe social ?D? apresenta maior risco de DPM do que a classe social ?C? e é\nestatisticamente significante.","C":"o ex-fumante tem maior risco de apresentar DPM do que os pacientes que não fumam e é\nestatisticamente significante.","D":"os pacientes com obesidade apresentam maior risco de DPM do que os pacientes com\nsobrepeso e é estatisticamente significante."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":["question_bank/media/medcurso/medcurso-psiquiatria-psi-unico/9291.png"],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-9277","number":"9277","sourceNumber":"9277","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Na visão analítica, o sofrimento mental que pode ser prevenido na vida adulta do\nconcepto por meio do planejamento familiar,\nde cuidados afetivos à gestante, de assistência afetiva\nao parto, ao puerpério e à relação mãe-bebê nas primeiras semanas de vida, refere-se à:","options":{"A":"ansiedade generalizada.","B":"esquizofrenia.","C":"histeria.","D":"neurose obsessivo-compulsiva."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-273974","number":"273974","sourceNumber":"273974","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem idoso apresentou quadro de agitação associado a um episódio de delirium\nhiperativo, no hospital, e melhorou após ter\nrecebido 2 mg de haloperidol EV. Dois dias após esse\nepisódio, o paciente seguia em uso de Haloperidol 1 mg VO duas vezes ao dia e encontrava-se\ndesorientado quanto a data, porém orientado no espaço, sem sinais de déficit de atenção ou\ndesorganização de pensamento. A despeito disso, o paciente apresenta-se bastante inquieto a\nponto de não conseguir ficar deitado no leito e desejar ficar em pé ou andando continuamente. Qual\né a conduta MAIS APROPRIADA nesse momento?","options":{"A":"Suspender o uso do haloperidol.","B":"Substituir o haloperidol por quetiapina 25 mg VO à noite.","C":"Manter o haloperidol na sua dose atual e adicionar lorazepam 1 mg VO à noite.","D":"Titular a dose do haloperidol por via EV com doses de ataque de 0,5 mg e depois realizar a\nconversão para dose de manutenção oral."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-250194","number":"250194","sourceNumber":"250194","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre o manejo de depressão e transtornos de ansiedade na atenção primária à saúde,\nassinale a alternativa INCORRETA:","options":{"A":"O tratamento medicamentoso da depressão deve ser mantido por pelo menos 6 meses, na\nmesma dose que alcançou resposta terapêutica,\npara evitar recorrências.","B":"A avaliação do paciente com ansiedade generalizada não se resume ao número, gravidade e\nduração dos sintomas, mas também ao grau de sofrimento e prejuízo funcional do indivíduo.","C":"A psicoeducação ofertada para pacientes com depressão deve focar no ponto em que a\ndepressão tem sintomas emocionais e físicos\ne que o tratamento diminui o tempo e a intensidade\ndos sintomas.","D":"Os pacientes que preenchem os critérios do DSM-V para depressão leve e ansiedade\ngeneralizada respondem melhor se iniciado\nantidepressivo tricíclico o mais precoce possível."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-216337","number":"216337","sourceNumber":"216337","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"As doenças psiquiátricas vêm ganhando destaque ao longo da última década, com\nalguns levantamentos epidemiológicos apontando, por\nexemplo, a prevalência de transtorno de\nansiedade superior a 25% em populações adultas. Nesse contexto, passa a ser importante para o\nclínico saber abordar alguns sintomas, que passaram a se tornar mais frequentes nos ambulatórios.\nReferente à semiologia da insônia podemos afirmar que:","options":{"A":"Insônia inicial é mais sugestiva de depressão, sendo a terminal mais sugestiva de ansiedade.","B":"Insônia inicial é mais sugestiva de fatores ambientais, enquanto a terminal sugere transtorno de\nansiedade.","C":"Insônia terminal é mais sugestiva de fatores ambientais, enquanto a insônia inicial sugere\ntranstorno de ansiedade.","D":"Insônia terminal é mais sugestiva de depressão e insônia inicial mais sugestiva de ansiedade."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-176147","number":"176147","sourceNumber":"176147","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre os conceitos presentes no Caderno de Atenção Básica de Sáude Mental,\nassinale a alternativa CORRETA.","options":{"A":"O uso abusivo de álcool difere da dependência por conta da quantidade de ingesta.","B":"O cuidado em saúde mental na atenção básica deve ser executado, principalmente, pelo\nmédico.","C":"A proposta de redução de danos é uma ferramenta usada exclusivamente no CAPS álcool e\ndrogas.","D":"O conceito de sofrimento mental comum envolve exclusivamente sintomas ansiosos e\ndepressivos.","E":"As crises psíquicas são suportadas, muitas vezes, por igrejas. terreiros e outras formas\nculturais.\n\nSomente parte delas é tratada pela Psiquiatria."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-62704","number":"62704","sourceNumber":"62704","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Vários autores têm chamado a atenção para o fenômeno da depressão em crianças e\nadolescentes que, além de ter seu reconhecimento estabelecido, parece estar mais frequente e\nocorrendo cada vez mais cedo, sendo que, em alguns estudos, os adultos com depressão maior\nrelataram o primeiro episódio da doença ocorrendo antes dos dezoito anos de idade. Dentre os\nsintomas de depressão maior, assinale a alternativa INCORRETA.","options":{"A":"Humor deprimido ou irritável e interesse ou prazer acentuadamente diminuído;","B":"Perda ou ganho significativo de peso e diminuição ou aumento de apetite;","C":"Insônia ou hipersonia, agitação ou retardo psicomotor e fadiga ou perda de energia;","D":"Não faz distinção entre experiências reais e imaginárias, não pensa de forma lógica e não possui\nrespostas emocionais normais;","E":"Sentimento de inutilidade ou culpa excessiva e inadequada, capacidade diminuída de pensar, ou\nconcentrar-se ou indecisão."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-308646","number":"308646","sourceNumber":"308646","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Na abordagem do paciente com intoxicação por cocaína e suas manifestações\ncardiovasculares, tem contraindicação relativa:","options":{"A":"nitroglicerina.","B":"nitroprussiato.","C":"lidocaína.","D":"betabloqueadores.","E":"benzodiazepinicos."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-311533","number":"311533","sourceNumber":"311533","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"É característica da síndrome de Munchausen:","options":{"A":"Deixar sequelas físicas e psíquicas, com a criança assumindo o papel de doente, frágil e\ndependente de seu agressor.","B":"Agressor com psicopatologia diagnosticada, compulsivo, que utiliza a criança para seus rituais\nsadomasoquistas.","C":"Forma de autoagressão, com a simulação de doença para obtenção de vantagens financeiras,\ncomo salário por invalidez.","D":"Classificada como transtorno somatoforme, em que a criança simula a doença para chamar a\natenção dos pais e do meio médico.","E":"Todas as questões acima."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-308695","number":"308695","sourceNumber":"308695","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre a esquizofrenia em crianças pré-púberes, o súbito aparecimento da psicose na\ncriança é tratada como uma emergência médica devendo-se, além da avaliação psicológica e das\nalterações do estado mental, investigar as prováveis causas clínicas. Nesse contexto, assinale a\nopção em que a entidade clínica não é prioritária na investigação.","options":{"A":"Dermatite atópica.","B":"Distúrbios da tireóide.","C":"Porfiria.","D":"Lúpus eritematoso sistêmico.","E":"Doença de Wilson."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-281501","number":"281501","sourceNumber":"281501","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente jovem procura o setor de emergência por quadro psicótico agudo. Foi\nmedicado com haloperidol intramuscular e encaminhado ao psiquiatra. Retorna ao setor de\nemergência após 48 h com piora da agitação e ansiedade, esfregando as mãos e ficando em pé\nbalançando corpo de um lado para outro. A melhor conduta para o caso é:","options":{"A":"Realizar imediatamente exame de imagem para diagnóstico.","B":"Aumentar dose haloperidol.","C":"Administrar benzodiazepínico ou prometazina e trocar antipsicótico.","D":"Realizar eletroconvulsoterapia.","E":"Associar medicação anticolinérgica."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-278937","number":"278937","sourceNumber":"278937","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente feminina, 24 anos, universitária, vem em consulta médica com relato de\ndesmaio durante a segunda aula seguida de\ncrossfit no dia anterior. O namorado relata que,\nmesmo com o peso dentro da normalidade, a paciente mostra-se insatisfeita e preocupada com seu\npeso corporal. Refere, também, que era comum crises de choro e ansiedade seguidas de consumo\nexagerado de comida. Explicita, ainda, que, no dia do ocorrido na academia, eles tiveram uma séria\ndiscussão e a paciente consumiu, sozinha, uma lasanha tamanho família e um litro de refrigerante.\nEm se tratando do caso ora referido, a paciente se enquadra, clinicamente, no diagnóstico de:","options":{"A":"Anorexia nervosa.","B":"Bulimia nervosa.","C":"Transtorno de compulsão alimentar.","D":"Transtorno alimentar restritivo alimentar.","E":"Transtorno do comer compulsivo."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-218051","number":"218051","sourceNumber":"218051","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Com relação ao uso da maconha, qual a afirmação verdadeira?","options":{"A":"Podem ocorrer sintomas psicóticos, que desaparecem completamente após a desintoxicação.","B":"As alterações de humor e de apetite são devido às ações da substância nos gânglios da base.","C":"A ocorrência dos sintomas não sofre nenhuma influência do contexto.","D":"Sua toxicidade é muito baixa, sendo pouco provável a busca por um serviço de emergência\npsiquiátrica devido ao seu uso.","E":"A interrupção abrupta do uso diário não traz risco de desencadear síndrome de abstinência."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-160376","number":"160376","sourceNumber":"160376","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sob a ótica da promoção da saúde, o Ministério da Saúde criou o Programa Nacional\nde Controle do Tabagismo. Como é conhecido o\nproduto do número de maços utilizados em dia\npelo número de anos que o paciente fumou?","options":{"A":"Carga tabágica.","B":"Produto de fumo.","C":"Nível de dependência de nicotina.","D":"Nível de dependência do alcatrão.","E":"Índice de Fagerström."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-160373","number":"160373","sourceNumber":"160373","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Qual das seguintes opções se refere à manifestação hematológica que mais\ncomumente decorre do abuso crônico do álcool?","options":{"A":"Macrocitose","B":"Microcitose","C":"Leucopenia","D":"Trombocitose","E":"Hemoconcentração"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-160375","number":"160375","sourceNumber":"160375","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em saúde mental, os transtornos cujas queixas físicas não se associam nem com\nalterações do exame físico nem dos exames complementares e que não preenchem critério\ndiagnóstico algum são denominados transtornos:","options":{"A":"De humor.","B":"Neuróticos.","C":"De ansiedade.","D":"Psicóticos.","E":"Somatoformes."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-154379","number":"154379","sourceNumber":"154379","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Na intoxicação por Metilenodioximetanfetamina - MDMA (ecstasy), a principal\nintervenção terapêutica será no sentido de prevenir:","options":{"A":"Hiponatremia e hipercalcemia.","B":"Hiponatremia e hipertermia.","C":"Hiponatremia e hipotermia.","D":"Hipercalcêmica e hipotermia.","E":"Hipertermia e hipercalcemia."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-89233","number":"89233","sourceNumber":"89233","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A causa mais comum de encaminhamentos para Psiquiatria Infantil é:","options":{"A":"TDAH - Transtorno do Déficit de Atenção e Hiperatividade","B":"Autismo","C":"Depressão","D":"Transtorno bipolar","E":"Esquizofrenia"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-308318","number":"308318","sourceNumber":"308318","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O delirium é uma manifestação neuropsiquiátrica de doença orgânica, que acomete,\nprincipalmente, pacientes idosos, especialmente os hospitalizados. Sobre essa importante\ncondição, assinale a afirmativa correta.","options":{"A":"Tem início agudo e curso não flutuante, estável, facilitando muito o seu diagnóstico.","B":"Caracteriza-se por apresentar distúrbios na cognição, atenção e consciência, no ciclo\nsono-vigília e no comportamento psicomotor.","C":"O comportamento psicomotor encontra-se alterado, podendo ocorrer um estado de\nhiperatividade. Em idosos, não ocorre o delirium na forma hipoativa.","D":"Pacientes que desenvolvem delirium podem cursar com pior prognóstico na vigência de uma\ninternação, entretanto não apresentam maior taxa de institucionalização e mortalidade após alta\nhospitalar."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-313413","number":"313413","sourceNumber":"313413","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 37 anos, hipertenso e diabético LADA, queixando-se de sensação de vazio e\nfalta de interesse em realizar atividades prazerosas há cerca de 3 meses, acompanhado de\ncompulsão alimentar com ganho ponderal, irritabilidade esonolência excessiva diurna. Diante desse\nperfil, a terapia farmacológica mais indicada seria:","options":{"A":"Sertralina;","B":"Duloxetina;","C":"Amitriptilina;","D":"Bromazepam."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-313417","number":"313417","sourceNumber":"313417","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 21 anos, vem para consulta trazido por acompanhantes que referem que o\nmesmo vem apresentando dificuldade de\nexpressar emoções e sentimentos associado com\nagitação, confusão e alucinações auditivas há cerca de 6 meses. Qual melhor alternativa para dar\ninício ao seu tratamento?","options":{"A":"Amítriptilina;","B":"Haloperidol;","C":"Carbamazepina;","D":"Prometazina."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-313424","number":"313424","sourceNumber":"313424","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente de 17 anos de idade, faiodérmica, estudante, portadora de depressão e\ntentativa prévia de suicídio foi encontrada\npor seus familiares desacordada há pelo menos 4 horas\nem sua residência apósdiscussão com sua mães Ao seu lado há uma cartela vazia de 20\ncomprimidos de diazepam 10 mg. No momento encontra-se com o nível de consciência rebaixado,\ncom 13 pontos na escala de Glasgow (abertura ocular 3, resposta verbal 4, resposta motora6), sem\noutros achados relevantes. Qual a melhor conduta frente a este caso?","options":{"A":"Intubação orotraqueal imediata;","B":"Observação clínica e neurológica;","C":"Sonda nasogástrica e lavagem gástrica;","D":"Lavagem gástrica seguida de carvão ativado."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-267295","number":"267295","sourceNumber":"267295","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente, sexo feminino, 80 anos, é internada na enfermaria de clínica médica com\nquadro de pneumonia bacteriana grave. Tem\nantecedente de Hipertensão Arterial Sistêmica (HAS)\nem uso de losartana 50 mg/dia. É lúcida, independente para as atividades básicas de vida diária e\nreside sozinha. No período noturno do primeiro dia de internação, apresenta quadro de agitação,\nretira o acesso venoso, desesperando-se de medo e não respondendo às perguntas. Em relação\nao quadro apresentado, assinale a afirmativa correta.","options":{"A":"São critérios diagnósticos dessa condição: mudança aguda do estado mental, pensamento\ndesorganizado e manutenção da atenção.","B":"O diagnóstico provável é de síndrome demencial de início agudo devido ao quadro de\npneumonia grave.","C":"O diagnóstico é estado confusional agudo ou delirium, que acomete 5% dos pacientes muito\nidosos com pneumonia grave.","D":"O diagnóstico é estado confusional agudo caracterizado por síndrome cerebral orgânica de início\nagudo com curso flutuante e transitório."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-283990","number":"283990","sourceNumber":"283990","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 37 anos, hipertenso e diabético LADA, queixando-se de sensação de vazio e\nfalta de interesse em realizar atividades prazerosas há cerca de 3 meses, acompanhado de\ncompulsão alimentar com ganho ponderal, irritabilidade e sonolência excessiva diurna. Diante\ndesse perfil, a terapia farmacológica mais indicada seria:","options":{"A":"sertralina","B":"duloxetina","C":"amitriptilina","D":"bromazepam"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-244796","number":"244796","sourceNumber":"244796","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A Organização Mundial da Saúde (OMS) estima que 1 pessoa morre por suicídio a\ncada 40 segundos, totalizando mais de\n800.000 mortes por ano em todo o mundo. A OMS\nestabeleceu como meta reduzir em 10% o número de mortes por suicídio globalmente até 2020,\nenfatizando que suicídio é uma causa de morte evitável. A respeito do suicídio e sua prevenção,\nassinale a alternativa correta:","options":{"A":"Leis que restringem o acesso a métodos letais de suicídio, como armas de fogo e pesticidas, não\nreduzem as taxas de suicídio","B":"Perguntar ao paciente sobre ideação suicida é inadequado, pois a pergunta pode ser\ninterpretada como incitação ao ato","C":"Tentativas de suicídio repetidas no mesmo indivíduo indicam baixa probabilidade de morte por\nsuicídio em tentativas futuras","D":"Estudos do tipo autópsia psicológica evidenciam a presença de transtornos mentais em cerca de\n90% das pessoas que se suicidaram","E":"Mulheres fazem uso de métodos com mais alta letalidade comparadas aos homens"},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-255350","number":"255350","sourceNumber":"255350","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Foi observado em pacientes com idade média de 72 anos e constatou aumento\nsignificativo de IAM, morte súbita e AVE em fumantes em comparação a não fumantes. Não\npodemos aceitar que:","options":{"A":"A exposição a longos períodos de tabagismo passivo não aumenta o risco de desenvolver\nDoença Arterial Coronariana.","B":"O risco relativo de desenvolver doença coronariana aumentou para as mulheres expostas ao\nfumo.","C":"A exposição ocasional ao cigarro aumentou seu risco relativo.","D":"A exposição regular aumentou o risco relativo."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-221067","number":"221067","sourceNumber":"221067","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A.M.S., mulher 63 anos, é admitida na emergência com quadro de desorientação de\ninício há 3 dias, caráter flutuante e\nsonolência há pouco mais de 24 horas. Ao exame físico: PA =\n100 x 50 mmHg; FC = 62 bpm; FR = 18 irpm; ACV RCR 2T; AR: MVUA com estertores crepitantes\nem ambas as bases; abdome flácido, indolor, peristáltico, sem visceromegalias palpáveis; MMII\ncom edema frio com cacifo 1+/4+ bilateralmente em porção distal. Exame neurológico: MEEM = 17,\npares cranianos sem alterações, reflexos tendíneos presentes e simétricos universalmente,\ndesatenção e pensamento desorganizado. HPP: doença de Parkinson há 18 meses, HAS com\ncontrole medicamentoso. A respeito do caso, analise as assertivas a seguir: I - Condições como\ninsuficiência cardíaca, hipóxia, hipercapnia, alterações tireoidianas, infecções, insuficiência\nrenal e\ninsuficiência hepática devem ser corrigidas, a fim de melhorar o funcionamento cerebral visto\n\ntratar-se de delirium. II - Doença de Alzheimer é a principal hipótese devido ao processo\ndegenerativo com acometimento inicial do\nhipocampo caracterizado por alterações\ncognitivas/comportamentais e preservação motora/sensorial nas fases avançadas. III - Redução\ndopaminérgica da doença de Parkinson também pode comprometer a atenção, as principais\ncaracterísticas são lentificação cognitiva, apatia, comprometimento da memória e das funções\nexecutivas desde o início da doença. IV - Devido à redução da mobilidade da caixa torácica,\nelasticidade pulmonar, pressão ins e expiratória máximas, consequente ineficiência de tosse e\nmobilidade dos cílios do epitélio respiratório, facilita quadro de pneumonia. Estão CORRETAS as\nassertivas.","options":{"A":"I, III e IV, apenas.","B":"I e IV, apenas.","C":"II e III, apenas.","D":"II, III e IV, apenas."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-214016","number":"214016","sourceNumber":"214016","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre transtornos de ansiedade, julgue as afirmativas abaixo: I) São condições que\npodem mimetizar transtornos de ansiedade:\nAngina e IAM, Asma, hipertireoidismo,\nfeocromocitoma, cocaína, maconha, álcool, anti-hipertensivos, uremia e deficiência de vitamina\nB12; II)Dentre os transtornos de ansiedade mais comuns na APS estão: TOC; transtorno do pânico,\nfobia específica, mania, transtorno de ansiedade generalizada; transtornos de estresse\n\npós-traumático; III) Na abordagem dos sintomas de ansiedade é importante fazer o diagnóstico\ndiferencial com inquietação, euforia e irritabilidade; e também, esclarecer que ansiedade é o\nproblema principal ou parte do transtorno subjacente; IV) Os medicamentos mais indicados no\ntratamento são os inibidores seletivos de recaptação de serotonina.","options":{"A":"I e II estão corretas;","B":"I, III e IV estão corretas.","C":"II e IV estão corretas.","D":"Todas estão corretas."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-217975","number":"217975","sourceNumber":"217975","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Pedro, sexo masculino, adulto jovem de 25 anos, filho único, estudante de nível\nsuperior e heterossexual. Apresentava\nqueixa de ansiedade em diversas situações, dificuldade em\nrealizar seu trabalho de conclusão de curso e na escolha profissional. Ele considerava-se uma\ncriança tímida. Tinha alguns amigos, mas deixava que eles o procurassem para falar e interagir,\nsendo mais quieto. Na sala de aula do colégio em que estudava, procurava sentar nas cadeiras que\nficavam próximos à parede, para que não chamasse muito atenção. No início da adolescência, o\npaciente teve uma drástica mudança no estilo de vida, devido a sérias dificuldades financeiras da\nfamília e à separação de seus pais, que ocorreram em tempo próximo. Neste período da\nadolescência o paciente foi se isolando e refugiando-se em seu quarto e evitando ao máximo sair\nde casa. Apresentava medo excessivo ao lidar com as pessoas e situações adversas. Já na\nuniversidade tinha dificuldades para buscar estágios, sentindo-se muito ansioso em seleções\nprofissionais. E também na vida pessoal Pedro relatou dificuldades de se aproximar de meninas por\nmedo de não conseguir conversar, pois acreditava que não as agradaria. No final da\nadolescência/início da idade adulta, tentou ter relações sexuais, mas sentiu-se ansioso e não teve\nêxito. Paciente não relatou doença clínica importante, somente crises de ansiedade em várias\nsituações cotidianas. Dentre as intervenções farmacológicas abaixo referidas, a melhor opção para\no tratamento do transtorno de Pedro é:","options":{"A":"Lítio 300 mg 3 x ao dia.","B":"Amitriptilina 25 mg à noite.","C":"Clonazepam 2 mg à noite.","D":"Escitalopram 10 mg ao dia."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-185211","number":"185211","sourceNumber":"185211","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente de 28 anos esquizofrênico sem tratamento apresenta comportamento bizarro,\nagitação psicomotora, alucinações auditivas e ideias delirantes persecutórias. A mãe, cuidadora,\nseparada, deixou de administrar as medicações do filho há 3 meses devido a mobilidade reduzida\npor cirurgia no fêmur. Sobre o manejo do caso, assinale a alternativa CORRETA:","options":{"A":"Administrar antipsicóticos de longa ação disponíveis em preparações de depósito é mais efetivo\ndo que as formulações orais na prevenção de\nrecidivas.","B":"Associar neurolépticos com ansiolíticos ou antidepressivos é uma estratégia bastante utilizada\nna prática clínica que proporciona mais\nbenefícios do que riscos.","C":"Após a escolha do fármaco, deve-se avaliar a resposta depois de seis meses do uso do agente\nem doses adequadas.","D":"Administrar antipsicóticos típicos pois possuem eficácia superior aos atípicos no tratamento das\nmanifestações agudas e na prevenção de recaídas dos sintomas.","E":"Ao optar por antipsicóticos de alta potência devemos sempre associar antiparkinsonianos para\ncontrole de efeitos adversos neurológicos."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-181104","number":"181104","sourceNumber":"181104","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem, 21 anos, vem para consulta trazido por acompanhantes que referem que ele\nvem apresentando dificuldade de expressar emoções e sentimentos associados com agitação,\nconfusão e alucinações auditivas há cerca de 6 meses. Qual a melhor alternativa para dar início ao\nseu tratamento?","options":{"A":"Amitriptilina.","B":"Haloperidol.","C":"Carbamazepina.","D":"Prometazina."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-309786","number":"309786","sourceNumber":"309786","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Adolescente, sexo masculino, 16 anos, é trazido à consulta relatando dor no peito e\ndificuldade para dormir. Anamnese: bom aluno, estuda pela manhã, ambiente familiar bem\nestruturado e tem hábito de jogar ''games'' antes de dormir. Utiliza a internet e smartphones por 5\nhoras/dia. Exame físico: sem alterações, ACV: normal. A orientação deve ser:","options":{"A":"Instalar um aplicativo que controle sua ansiedade.","B":"Investir em games para aumentar a inteligência e memória.","C":"Procurar apoio psicoterápico visando diminuir a hiperatividade.","D":"Criar regras sobre o uso do celular desligando duas horas antes de dormir.","E":"Nenhuma das alternativas anteriores"},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-286098","number":"286098","sourceNumber":"286098","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre o delírio primário e secundário, assinale a alternativa que melhor explique a\ndiferença entre os dois:","options":{"A":"No delírio primário o indivíduo tem uma convicção extraordinária, enquanto no delírio secundário\nessa convicção é passível de modificação em\nqualquer tempo por experiência objetiva (provas de\nrealidade funcionam).","B":"O delírio secundário é uma forma gradualmente mais grave do que o delírio primário, mais\nfrequentemente presente em transtornos mentais mais graves, como por exemplo, na psicose.","C":"O delírio primário se origina de alteração do pensamento e juízo, e o delírio secundário se\norigina de alterações em outras atividades mentais (afetividade, nível de consciência, etc.) que\ndepois produzem juízos falsos.","D":"No delírio primário as ideias se desenvolvem em torno de um só conteúdo, já o delírio\nsecundário engloba vários temas ao mesmo tempo e com conteúdos diversos.","E":"O delírio primário tem caráter mutável, observado nas fases iniciais das psicoses, enquanto o\ndelírio secundário é fixo e irremovível, cristalizado em fases mais avançadas da doença."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-286099","number":"286099","sourceNumber":"286099","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Assinale a alternativa que melhor explique a diferença entre ideias obsessivas e ideias\ndelirantes:","options":{"A":"Diferente das ideias obsessivas, as ideias delirantes não são introduzidas de forma repetida e\nrecorrente, já que o indivíduo é capaz de ter maior controle e consciência dos momentos que as\nideias delirantes aparecem.","B":"Nas ideias delirantes o indivíduo apresenta pensamentos com características e conteúdos\nespecíficos, já as ideias obsessivas possuem\ntemas variados ligados à compulsão previamente\napresentada pelo indivíduo.","C":"As ideias delirantes são exclusivas da esquizofrenia, e as ideias obsessivas podem estar\npresentes em diversos transtornos mentais psicóticos e não psicóticos.","D":"Nas ideias delirantes o indivíduo não reconhece o pensamento como absurdo, já nas ideias\nobsessivas o indivíduo reconhece os pensamentos como absurdos, mas não consegue se livrar\ndeles.","E":"As ideias delirantes podem se apresentar com conteúdos diversos, normalmente paranoico,\nenquanto as ideias obsessivas são de conteúdo religioso-demoníaco."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-284216","number":"284216","sourceNumber":"284216","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"A influência do tabagismo no idoso ocorre pelas alterações anatômicas e fisiológicas de\num processo acumulativo que:","options":{"A":"Leva a disfunção endotelial, redução da adesividade plaquetária, diminuição do colesterol de\nlipoproteínas de alta densidade (HDL-c) e aumento do colesterol de lipoproteínas de baixa\ndensidade (LDL-c), entre outras alterações.","B":"Leva a disfunção endotelial, aumento da adesividade plaquetária, diminuição do colesterol de\nlipoproteínas de alta densidade (HDL-c) e redução do colesterol de lipoproteínas de baixa\ndensidade (LDL-c), entre outras alterações.","C":"Leva a disfunção endotelial, aumento da adesividade plaquetária, diminuição do colesterol de\nlipoproteínas de alta densidade (HDL-c) e aumento do colesterol de lipoproteínas de baixa\ndensidade (LDL-c), entre outras alterações.","D":"Não leva a disfunção endotelial, e sim ao aumento da adesividade plaquetária, diminuição do\ncolesterol de lipoproteínas de alta densidade (HDL-c) e aumento do colesterol de lipoproteínas de\nbaixa densidade (LDL-c), entre outras alterações."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-243737","number":"243737","sourceNumber":"243737","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O uso de substâncias psicoativas é um importante problema de saúde pública no Brasil.\nO II Levantamento Domiciliar sobre Uso de\nDrogas Psicotrópicas, feito em 2005, pelo Centro\nBrasileiro de Informações sobre Drogas Psicotrópicas (CEBRID), abrangendo 108 cidades\nbrasileiras com mais de 200 mil habitantes, identificou que o uso de qualquer droga ilícita, ao\nmenos uma vez na vida, foi de 22,8% da população. Considerando as orientações das políticas\npúblicas de saúde do Brasil para o cuidado de pessoas que fazem uso de substâncias psicoativas,\na abordagem considerada adequada no cuidado a esse público pressupõe que:","options":{"A":"o objetivo principal do tratamento é que a pessoa abandone o consumo da substância psicoativa","B":"o tratamento farmacológico tem papel decisivo no tratamento da dependência das substâncias\npsicoativas","C":"a internação é a principal intervenção terapêutica em pessoas que fazem uso de substâncias\npsicoativas e que desejam cessar o uso","D":"a discussão de formas de uso com menor risco pode ser eficiente com usuários que não\ndesejam cessar o uso de drogas ampliando possibilidades no acompanhamento longitudinal"},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-243741","number":"243741","sourceNumber":"243741","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Kaya, 31 anos, chega ao consultório médico pela primeira vez, mostrando-se ansiosa e\nangustiada. Conta que perdeu o marido, falecido por infarto há 1 ano, e desde então está se\nsentindo triste, agressiva e muito agitada. Brigou no trabalho por estar impaciente, foi demitida\ne, a\npartir daí, perdeu a vontade de fazer as tarefas de casa. Quer passar o dia na cama, alimenta-se\npouco, apresenta dificuldade para dormir e não cuida de sua aparência. Em situações de estresse,\nmesmo que pequenos, tem sensação de palpitação. Durante o relato apresenta-se chorosa e diz\nestar chorando todos os dias e sem motivo. Em certos momentos se acha inútil e já pensou em tirar\na própria vida. O diagnóstico mais provável e o quadro clínico compatível são, respectivamente:","options":{"A":"ansiedade / preocupação excessiva, inquietação, humor deprimido, tremores, tensão muscular,\nirritabilidade, pensamento de morte","B":"transtorno mental comum / humor deprimido, palpitações, anedonia, insônia, sentimento de\nperda de valor, tristeza e agitação psicomotora","C":"luto / humor deprimido, perda de interesse, sono pertur- bado, apetite diminuído, idéias de culpa\ne inutilidade, idéias ou atos autolesivos ou\nsuicídio","D":"depressão / humor deprimido, perda de interesse, sono perturbado, apetite diminuído, ideias de\nculpa e inutilidade, ideias ou atos autolesivos ou suicídio"},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-247071","number":"247071","sourceNumber":"247071","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O tabagismo continua sendo um problema social importante consumindo muitos\nrecursos da saúde devido a suas\nconsequências, entre elas as doenças cardiovasculares. Com\nrelação ao assunto, é correto afirmar que.","options":{"A":"a Vareniclina é um agonista de receptor nicotínico, que possui a vantagem de poder ser utilizada\nem gestantes e em mulheres amamentando.","B":"o tabagismo se relaciona com diversos tipos de câncer como pulmão, laringe, faringe, boca;\nporém, é fator de proteção para câncer de bexiga e colorretal.","C":"a nicotina em adesivos ou goma de mascar é indicada como adjuvante no tratamento do\ntabagismo, inclusive nos casos de fase aguda do\ninfarto agudo do miocárdio (menos de 15 dias do\nevento).","D":"avaliar a motivação do paciente para parar de fumar é fundamental, o modelo PAAPA\n(Perguntar/Avaliar/Aconselhar/Preparar/Acompanhar) é um dos modelos mais simples e eficazes\nno tratamento do tabagismo, além do tratamento farmacológico que, com uso de terapias\ncombinadas, podem chegar até 60% de abstinência ao cigarro e seus derivados.","E":"a bupropiona pode gerar boca seca, insônia, constipação e tremores, mas possui a vantagem de\npoder ser utilizada com segurança na gestação e na amamentação."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-216811","number":"216811","sourceNumber":"216811","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente de 80 anos, independente para atividades básicas de vida diária, hipertenso,\nem uso de enalapril 5 mg ao dia. Encaminhado à\nenfermaria de clínica médica para tratamento de\ninfecção urinária. Chegou desidratado e oligúrico, sendo passada sonda vesical de demora para\ncontrole de diurese. Segundo familiar, no segundo dia de internação começou a apresentar\ndesatenção, alternância de períodos de sonolência com períodos de agitação e pensamento\ndesorganizado. Dentre as alternativas abaixo, qual NÃO representa fator predisponente para o\ndiagnóstico feito após a admissão do paciente?","options":{"A":"Idade.","B":"Sondagem vesical de demora.","C":"Infecção.","D":"Anti-hipertensivo."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-214094","number":"214094","sourceNumber":"214094","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre o Delirium, assinale a alternativa correta.","options":{"A":"Não está relacionado ao aumento da mortalidade.","B":"O tratamento principal é o uso de Haloperidol, Quetiapina ou Risperidona.","C":"Não há a necessidade de se realizar testes para o diagnóstico.","D":"Pode ser desencadeado por sondagem vesical de demora, contenção física polifarmácia.","E":"Tem como características fundamentais para seu diagnóstico: distúrbio da atenção e agitação\npsicomotora."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-214084","number":"214084","sourceNumber":"214084","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher, 63 anos, viúva, aposentada, procurou a Unidade Básica de Saúde\n\nqueixando-se de ''cabeça vazia'', muitas dores pelo corpo, falta de apetite, fraqueza, dificuldades\nde\nconcentração e um medo intenso de que pudesse estar com algum tipo de câncer. Nos últimos\nmeses, refere que não tem disposição para realizar suas atividades habituais, abandonou as\ncaminhadas pela manhã e, também, não participa mais do clube de dança dos idosos do município.\nReclama também de queda de cabelo intensa e de constipação intestinal. Refere tratamento para\nquadro de um ''problema de coração'' e glaucoma. Ao exame físico, observou-se a paciente com\nfrequência cardíaca = 60 bpm; pressão arterial = 100 x 70 mmHg; sem febre, sem alterações em\nausculta cardiopulmonar. Considerando o diagnóstico de Transtorno Depressivo Maior, quais\nexames devem ser solicitados para descartar um importante diagnóstico diferencial?","options":{"A":"Urina 1 e urocultura.","B":"Hemocultura.","C":"Ureia e creatinina.","D":"Perfil de ferro.","E":"TSH e T4 livre."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-177909","number":"177909","sourceNumber":"177909","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Considera-se o delirium como um transtorno mental de origem orgânica. Sobre essa\npatologia, pode-se afirmar que:","options":{"A":"É descrito rebaixamento do nível de consciência.","B":"Há prejuízo progressivo da memória de fixação.","C":"Ocorre ideia delirante sistematizada.","D":"A orientação espacial encontra-se conservada.","E":"Cursa com alteração primária do humor."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-187407","number":"187407","sourceNumber":"187407","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O Centro de Apoio Psicossocial (CAPS) tem o papel de acolher as demandas de uma\ndeterminada localidade por meio de uma intervenção interdisciplinar. Além disso, é papel deste\ndispositivo:","options":{"A":"Promover a reinserção social do indivíduo por meio do acesso ao trabalho, lazer, exercício dos\ndireitos civis e fortalecimento dos laços familiares e comunitários.","B":"Prestar atendimento em regime emergencial e encaminhar pessoas para internações em\nhospitais psiquiátricos caso o quadro clinico não seja compatível com manutenção em ambiente\naberto.","C":"Promover o afastamento social intermitente das pessoas com transtornos mentais por meio de\nações intersetoriais.","D":"Acolher e atender as pessoas com transtornos mentais leves e instáveis em regime de\ntratamento do tipo Hospital-dia, procurando preservar os laços sociais do usuário.","E":"Manter todos os pacientes graves em atendimento no serviço, mesmo que estes estejam\nestáveis pois a reabilitação se dá a longo prazo."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-187411","number":"187411","sourceNumber":"187411","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Considerando a Reforma Psiquiátrica no Brasil que dispõem sobre o reordenamento do\nmodelo assistencial as pessoas com sofrimento psíquico. Assinale a alternativa CORRETA:","options":{"A":"A atual Política Nacional em Saúde Mental visa melhorar as condições dos leitos em Hospitais\npsiquiátricos. Diminuindo o número de leitos por enfermaria e humanizando a assistência.","B":"Crianças e adolescentes com transtornos mentais severos são atendidos pelo CAPS\n\nInfanto-juvenil. Entretanto os adolescentes usuários de álcool e drogas devem estar em serviço\ndiferenciado.","C":"As pessoas atendidas nos Centros de Atenção Psicossocial (CAPS) são aquelas que\napresentam intenso sofrimento psíquico, que lhes\nimpossibilita de viver e realizar seus projetos de\nvida. Não devendo ser a prática de acompanhamento exclusivamente ambulatorial a vigente\nnesses serviços.","D":"As pessoas atendidas nos CAPS são apenas aquelas que apresentam sofrimento psíquico leve\ne moderado, que lhes possibilitam viver em\nsociedade.","E":"Os CAPS III funcionam 24h por dia, mas só recebem pacientes para acolhimento noturno até as\n19h. Após as 19h, os pacientes devem ser encaminhados a outros equipamentos da Rede de\nAtenção a Saúde."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-183487","number":"183487","sourceNumber":"183487","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher de 28 anos de idade chega à unidade de saúde da família apresentando quadro\nde contração muscular tônica dolorosa do\npescoço, cabeça inclinada para o lado, protusão da\nlíngua, sialorreia e olhar fixado para cima. Ela assumiu essa posição algumas horas após tomar sua\nmedicação psiquiátrica. Nesse caso, qual a conduta CORRETA?","options":{"A":"Determinar a glicemia e administrar glicose.","B":"Pedir um eletroencefalograma e administrar naltrexona.","C":"Administrar haloperidol intramuscular.","D":"Administrar biperideno intramuscular.","E":"Administrar prometazina intramuscular."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-151089","number":"151089","sourceNumber":"151089","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O tabagismo é doença crônica (F17.2) cuja oferta de tratamento traz grandes\nbenefícios e impactos na qualidade de vida.\nOs melhores resultados são alcançados quando:","options":{"A":"Associada ao aconselhamento comportamental.","B":"Paciente está (ou é) motivado a parar de fumar.","C":"Médico tem atitude empática, de acolhimento.","D":"Todas as opções acima estão corretas."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-151091","number":"151091","sourceNumber":"151091","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em relação ao tratamento do tabagismo, qual a melhor prática na conduta terapêutica a\nser adotada?","options":{"A":"Terapia considerada pelas diretrizes como primeira linha, Terapia de Reposição Nicotínica\n(TRN), Bupropiona e Vareniclina são eficazes no\ntratamento do tabagista motivados para o\nabandono.","B":"O tratamento medicamentoso deve acompanhar-se sempre de TCC.","C":"A Nortriptilina - medicação de segunda linha é recomendada quando há falha nas demais, tem\ncusto baixo e pode ser considerada em situações individuais para tratamento inicial.","D":"Todas as opções acima estão corretas."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-111794","number":"111794","sourceNumber":"111794","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Masculino, 53 anos, médico, tabagista há 40 anos, 30 cigarros/dia, Hipertensão Arterial\nSevera, antecedente de Infarto Agudo do Miocárdio (IAM) há dois anos, parou de fumar apenas\ndurante a internação, depressivo, não aceitou tratamento naquela época. Novo IAM, apresenta\nsíndrome de abstinência severa na UTI, além de depressão. Assinale a recomendação\nINCORRETA, no manejo do tabagismo durante hospitalização.","options":{"A":"Terapia de Reposição Nicotínica (TRN) + Bupropiona + Vareniclina.","B":"Terapia Cognitiva Comportamental (TCC) + Bupropiona + Benzodiazepínico.","C":"Prover assistência após a alta, sempre que possível com TCC, a mais prolongada possível\nencaminhando-o a centros especializados em tratamento do tabagismo.","D":"Terapia de reposição nicotínica em menor dose + Bupropiona + Vareniclina.","E":"Bupropiona + Nortriptilina."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-81226","number":"81226","sourceNumber":"81226","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Analise as afirmativas abaixo e assinale a alternativa incorreta:","options":{"A":"Lítio é medicação estabilizadora de humor.","B":"A esquizofrenia é uma síndrome heterogênea caracterizada por perturbação da linguagem,\npercepção, pensamento, atividade social, afeto e volição.","C":"Transtornos de personalidade são padrões típicos de pensamento, sentimento e comportamento\ninterpessoal relativamente inflexíveis e que causam prejuízo funcional significativo ou desconfortos\nsubjetivos para o indivíduo.","D":"No transtorno de somatização o paciente apresenta múltiplas queixas físicas referentes a\ndiversos órgãos que não podem ser explicadas por afecções clínicas.","E":"Os antidepressivos tricíclicos não causam aumento do intervalo QT no eletrocardiograma."},"answer":"E","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-83407","number":"83407","sourceNumber":"83407","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre o Delirium em cuidados intensivos, podemos afirmar:","options":{"A":"Epidemiologicamente sabe-se que ocorre em 20 a 80% dos pacientes durante a hospitalização,\nsendo que 40% destes internados possuem mais de\n65 anos; ocorre em até 82% dos pacientes\nsubmetidos à ventilação mecânica, e a mortalidade associada é de 10 a 65%.","B":"Atualmente é um marcador prognóstico da ocorrência de menor tempo de hospitalização devido\nà alta mortalidade, maior custo e maior\ndeclínio cognitivo.","C":"Sua fisiopatologia ainda é desconhecida e, dentre as hipóteses, discute-se alteração na\npermeabilidade da barreira hematoencefálica, aumento no metabolismo oxidativo cerebral,\ndiminuição da atividade do eixo hipotalâmico-hipofisário, anormalidades de neurotransmissores e\nresposta inflamatória com aumento das citocinas.","D":"Dentre as apresentações clínicas, a forma hipoativa é a mais diagnosticada devido à diminuição\nda atividade psicomotora e apatia intensa.","E":"O diagnóstico é essencialmente clínico, quando o quadro se apresenta com início insidioso, ao\nlongo de horas ou dias, com curso flutuante nas 24 horas, com períodos de lucidez e falta de\natenção com dificuldade de manter a conversação ou seguir comandos."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-83424","number":"83424","sourceNumber":"83424","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Escolar, 7 anos, masculino, é encaminhado para avaliação do pediatra. Segundo a\nprofessora, a criança tem dificuldade de concentração. Ao avaliar o menor, você desconfia que se\ntrate de transtorno de déficit de atenção e hiperatividade. Dentre as alternativas abaixo, é\nCORRETO afirmar:","options":{"A":"Para confirmar o diagnóstico, apenas a anamnese é suficiente.","B":"Além da história clínica, deve solicitar cariotipagem genética.","C":"Solicitar tomografia de crânio e associar com dados clínicos.","D":"Solicitar exames laboratoriais (função tireoidiana) e tomografia de crânio.","E":"Deve solicitar tomografia de crânio, cariotipagem e história clínica."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-60195","number":"60195","sourceNumber":"60195","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"São manifestações típicas do subtipo catatônico de esquizofrenia:","options":{"A":"Estupor, alucinações cinestésicas e desagregação do pensamento.","B":"Agitação psicomotora, negativismo e estereotipias.","C":"Desagregação do pensamento, respostas afetivas inapropriadas e isolamento social.","D":"Delírios persecutórios, alucinações auditivas e agitação psicomotora.","E":"Estupor, embotamento afetivo e delírios de influência."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-62319","number":"62319","sourceNumber":"62319","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Quanto à intoxicação aguda/abuso por crack, assinale a alternativa incorreta:","options":{"A":"As complicações cardiovasculares decorrentes do uso de cocaína são as mais frequentes entre\nas não psiquiátricas, sendo a angina do\npeito a que atinge maior taxa, presente em 10% dos\nusuários.","B":"A convulsão, a complicação neurológica mais comum, atinge uma pequena parte dos usuários\nde cocaína que procuram as salas de emergência.","C":"Usuários de crack que procuram atendimento médico imediatamente após consumirem crack\napresentam sintomas psiquiátricos com frequência.","D":"Apesar do usuário de crack habitualmente utilizar menos álcool que o usuário de cocaína\ninalada, o seu uso prediz gravidade e mau prognóstico.","E":"Os sintomas ansiosos secundários ao consumo são os mais prevalentes dentre as complicações\npsiquiátricas."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-64861","number":"64861","sourceNumber":"64861","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher de 55 anos, etilista de longa data, é admitida na enfermaria da clínica médica\ncom diagnóstico de pneumonia lobar. A paciente\napresentou melhora após 36 horas de internação,\nbasicamente com hidratação adequada e antibioticoterapia parenteral. Porém, evoluiu com\nimportante agitação, confusão mental, dor torácica e alucinações caracterizadas por cobras e\naranhas rastejando pelas paredes e balões amarrados na sua cabeceira. Ao exame físico: PA de\n170 x 100 mmHg; pulso de 140 bpm e sudorese importante. Isso considerado, a paciente deve ser\ntratada com:","options":{"A":"Ácido acetilsalicílico e diazepam.","B":"Haloperidol, diazepam e captopril.","C":"Diazepam e haloperidol.","D":"Ácido acetilsalicílico e propranolol.","E":"Ácido acetilsalicílico e captopril."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-64932","number":"64932","sourceNumber":"64932","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Jovem de 16 anos é trazido ao pronto-socorro com história de ingestão de álcool e uso\nde crack, apresentando-se agitado,\nagressivo, sudoreico, taquicardíaco e com palidez importante.\nAo exame físico, apresenta frequência cardíaca de 150 bpm e pressão arterial de 190 x 110 mmHg.\nAo ser monitorizado, apresenta o seguinte traçado (VER IMAGEM): O paciente deve ser\ninicialmente tratado com:","options":{"A":"Propranolol e Diazepam.","B":"Nitroprussiato de sódio e Haloperidol.","C":"Manobra vagal e Propranolol.","D":"Adenosina e Diazepam.","E":"Manobra vagal e Haloperidol."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-34517","number":"34517","sourceNumber":"34517","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Considerando que as alterações do estado mental correspondem a 30% das avaliações\nde emergência nos paciente idosos, não podemos\nafirmar que:","options":{"A":"O estado mental frequentemente serve como parâmetro da saúde geral do idoso e, geralmente,\né o único sintoma de doenças subjacentes\ngraves.","B":"O delirium, síndrome clínica caracterizada por distúrbio agudo da atenção e da cognição, não\ndependente de fatores predisponentes e tem como patogênese exclusiva desarranjos globais por\ndiminuição generalizada da atividade cortical, com falha da transmissão colinérgica em pacientes\nidosos internados.","C":"As características principais do delirium incluem o início agudo e a desatenção, além de\ndesorganização do pensamento, alteração do nível de consciência, retardo ou agitação\npsicomotora, alucinações, e inversão do ciclo sono-vigília.","D":"Depressão e distúrbios psicóticos não orgânicos são diagnósticos diferenciais do delirium.","E":"Em geral, devem ser utilizadas as abordagens não farmacológicas em todos os pacientes com\ndelirium e as farmacológicas devem ser reservadas apenas para os pacientes nos quais os\nsintomas de delirium possam resultar na interrupção das terapias médicas ou ameaçar a segurança\nde si ou de outrem."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-22644","number":"22644","sourceNumber":"22644","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente de 40 anos, internado por pneumonia bacteriana, sem história de doença\npsiquiátrica, apresenta lentificação das\nfunções psíquicas, fatigabilidade, diminuição da capacidade\nde concentração, desorientação temporoespacial, flutuação do nível de consciência e incoerência\ndo pensamento. O diagnóstico psiquiátrico provável é:","options":{"A":"Síndrome depressiva.","B":"Esquizofrenia.","C":"Delirium.","D":"Síndrome de autismo psicótico.","E":"Transtorno de pânico."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-301200","number":"301200","sourceNumber":"301200","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente masculino de 49 anos, em tratamento medicamentoso há seis meses para\ntranstorno depressivo maior grave, sem sintomas\npsicóticos, compareceu para atendimento na\nUBS, relatando remissão total dos sintomas e recuperação de sua capacidade funcional. Em sua\nhistória pregressa, relata diagnóstico de depressão aos 20 anos de idade após falecimento de sua\nmãe. Na época, recebeu alta por cura sem fazer uso de medicamentos. No início do episódio atual\napresentou pensamentos de autoextermínio, sem planejamento. Em sua família há histórico de\ntranstornos mentais e um tio faleceu por suicídio. Dentre as condutas abaixo, qual a MAIS\nADEQUADA para esse caso?","options":{"A":"Manter o tratamento medicamentoso com a mesma dose que levou à remissão dos sintomas até\ncompletar 12 meses ou mais, levando-se em consideração o risco de recorrência","B":"Reduzir a dose do antidepressivo e manter tratamento por mais 12 semanas","C":"Suspender a medicação antidepressiva e compartilhar o caso com o psicólogo do Núcleo de\nApoio à Saúde da Família para inserir paciente em grupo de psicoterapia","D":"Suspender o tratamento farmacológico e dar alta, pois houve remissão total dos sintomas e o\npaciente completou 6 meses de acompanhamento"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-301202","number":"301202","sourceNumber":"301202","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O alcoolismo é um problema prevalente e complexo. Os profissionais que atuam nas\nUnidades Básicas de Saúde são os mais indicados para a detecção precoce e para realizar alguma\nintervenção em relação ao uso abusivo do álcool. Identifique a forma CORRETA sobre essa\nabordagem na atenção primária à saúde:","options":{"A":"A equipe de saúde, coordenada pelo médico, deve desenvolver campanhas alertando sobre os\nriscos do consumo de álcool e implementar estratégias para diminuir a comercialização deste na\nsua área de atuação","B":"A Intervenção Breve é uma técnica de motivação para a mudança de comportamentos de saúde,\ndirecionada, principalmente, para pessoas que fazem uso abusivo de álcool ou outras drogas","C":"O médico deve prescrever tratamento medicamentoso a todo paciente que faz uso abusivo de\nálcool, buscando gerar um efeito aversivo, diminuindo assim seu consumo","D":"Sempre que identificado, o paciente com problemas relacionados ao álcool deve ser\nencaminhado para atendimento especializado"},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-301207","number":"301207","sourceNumber":"301207","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em relação à abordagem para cessação do tabagismo no âmbito do Sistema Único de\nSaúde, analise as afirmativas abaixo como Verdadeiras (V) ou Falsas (F) e, em seguida, assinale a\nalternativa que apresenta a sequência CORRETA. I. O uso de adesivos transdérmicos de nicotina\npode ser iniciado enquanto o paciente ainda estiver fumando, como forma de motivação para o\nabandono do hábito de fumar. II. A terapia cognitivo-comportamental consiste em fornecer\ninformações sobre os riscos do tabagismo e os benefícios de parar de fumar, e no estímulo ao\nautocontrole ou auto-manejo para que os indivíduos possam administrar o ciclo da dependência. III.\nÉ recomendado que pacientes tabagistas que relatam história pregressa de transtorno psiquiátrico\nao profissional de saúde que o recebe, sejam encaminhados (caso ainda não tenham sido) para\navaliação de profissional de saúde mental. IV. O acompanhamento médico deve ser semanal por\ntrês meses, em seguida, quinzenal por mais dois meses, e mensal até um ano. Entre os critérios de\nprescrição de apoio medicamentoso, estão os fumantes com escore do teste de Fagerström< 4.","options":{"A":"I ( V ); II ( F ); III ( F ); IV ( V )","B":"I ( V ); II ( V ); III ( F ); IV ( V )","C":"I ( F ); II ( V ); III ( V ); IV ( F )","D":"I ( F ); II ( F ); III ( V ); IV ( F )"},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-127518","number":"127518","sourceNumber":"127518","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em se tratando dos medicamentos ultilizados em Neuropsiquiatria, assinale a\nalternativa ERRADA:","options":{"A":"A oxcarbazepina, utilizada no tratamento da neuralgia do trigêmeo, pode, eventualmente,\ndesencadear a Síndrome de Secreção\nInapropriada do Hormônio Antidiurético.","B":"As indesejáveis manifestações extrapiramidais são mais comuns em usuários crônicos de\nneurolépticos como a clozapina e a quetiapina do que em usuários do haloperidol.","C":"Entre os efeitos adversos do carbonato de lítio inclui-se o hipotireoidismo secundário.","D":"O ácido valproico é ultilizado como anticonvulsivante e, em substituição ao carbonato de lítio,\ncomo estabilizador do humor em paciente com distúrbio afetivo bipolar."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-127559","number":"127559","sourceNumber":"127559","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Assinale a alternativa ERRADA:","options":{"A":"O nexo causal entre transtornos mentais e a organização do trabalho está nas dificuldades pelas\nquais perpassa o campo da saúde mental e o trabalho.","B":"No Brasil, os transtornos mentais, entre eles o alcoolismo crônico, estão entre os principais\nproblemas de saúde que afetam o trabalho.","C":"Dentre os principais sintomas advindos dos denominados transtornos somatoformes estão a\nfadiga, a irritabilidade e as alterações do sono.","D":"O estado de stress pós-traumático manifesta-se imediatamente após o acontecimento do evento\nou a situação provocadora do adoecimento."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-78431","number":"78431","sourceNumber":"78431","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Em se tratando da prescrição de psicotrópicos, são válidas as seguintes afirmativas,\nEXCETO:","options":{"A":"O carbonato de lítio e o divalproato podem ser prescritos como estabilizadores do humor em\npacientes com distúrbio afetivo bipolar.","B":"O neuroléptico quetiapina, ao contrário do haloperidol, tem a vantagem de não incluir, entre seus\nefeitos colaterais, o surgimento indesejável de manifestações extrapiramidais.","C":"Por razões várias, incluída a possibilidade de conduzirem seu usuário à dependência, a\nparoxetina e a clomipramina estão contraindicadas em pacientes com Síndrome do Pânico.","D":"Por seu efeito anticolinérgico, os antidepressivos tricíclicos não devem ser prescritos para\nidosos\ncom hipertrofia prostática avançada."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-60208","number":"60208","sourceNumber":"60208","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Os transtornos alimentares na adolescência, em particular a anorexia nervosa e a\nbulimia, são cada vez mais diagnosticados. Qual dentre as características abaixo é encontrada,\nprincipalmente, nos anoréxicos?","options":{"A":"Compulsão alimentar à qual se segue forte sentimento de culpa.","B":"Ocorrência mais frequente em adolescentes mais velhos e adultos jovens.","C":"Os sintomas podem ser ocultados por anos.","D":"São obstinados, falam muito pouco e são orgulhosos de seus sintomas."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-45236","number":"45236","sourceNumber":"45236","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem de 29 anos de idade, com história de etilismo pesado, foi trazido pela família ao\npronto-socorro porque estava muito sonolento e agitado há 2 dias. Ao exame, o paciente alternava\nagitação psicomotora com sonolência; estava desorientado; desatento; taquicárdico (102 bpm) e\napresentava sudorese; tremores de mãos; PA: 150 x 105 mmHg. Após instituir hidratação\nintravenosa e iniciar investigação da causa do quadro de delirium, qual é o medicamento prioritário\nneste caso?","options":{"A":"Clonidina VO (0,1-0,2 mg/dia).","B":"Dissulfiram VO (125-500 mg/dia).","C":"Lorazepam IV ou IM (1-4 mg/dia).","D":"Propranolol VO (20-80 mg/dia)."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-355391","number":"355391","sourceNumber":"355391","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Paciente, 40 anos, apresenta sintomas de tristeza profunda, perda de interesse nas\natividades diárias, alteração no apetite e no sono, falta de energia e desejo de morrer. Esses\nsintomas estão presentes há pelo menos duas semanas e causam significativo prejuízo em sua\nvida pessoal e profissional. Foram descartadas condições clínicas de diagnósticos diferenciais\n(tóxicas, infecciosas, metabólicas, estruturais), segundo anamnese pormenorizada, exame clínico\ncompleto e propedêutica laboratorial direcionada. Com base nesse caso clínico, qual o diagnóstico\nmais provável?","options":{"A":"Esquizofrenia.","B":"Transtorno de pânico.","C":"Transtorno depressivo maior.","D":"Transtorno de ansiedade generalizada."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-359312","number":"359312","sourceNumber":"359312","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Na tabela a seguir estão listados drogas antidepressivas e seus efeitos colaterais mais\ncomuns: Antidepressivos; I - amitriptilina; II - citalopram; III - sertralina; IV - bupropiona; V -\ntranilcipramina; Possíveis efeitos colaterais; ( ) a- interação droga-alimento grave; ( ) b-\nhipotensão\nortostática; ( ) c- prolongamento de segmento QT; ( ) d- sangramento gastrintestinal; ( ) e- crises\nconvulsivas; ( ) f- sedação; Assinale a alternativa com a associação CORRETA.","options":{"A":"I-f II-c III-d IV-e V-d","B":"I-b II-b III-e IV-c V-a","C":"I-f II-c III-d IV-e V-a","D":"I-b II-b III-e IV-c V-d"},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-340766","number":"340766","sourceNumber":"340766","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Pacientes oncológicos devem ser encorajados a parar de fumar e, portanto, devem\nreceber auxílio para tal. Sobre isso, podemos\nafirmar que:","options":{"A":"Não é indicado que o tratamento para a cessação do tabagismo seja iniciado o mais breve\npossível e a estratégia terapêutica inclua a associação de intervenções não farmacológicas e\nfarmacológicas.","B":"É indicado que o tratamento para a cessação do tabagismo seja iniciado o mais tarde possível e\na estratégia terapêutica inclua a associação de\nintervenções não farmacológicas e farmacológicas.","C":"É indicado que o tratamento para a cessação do tabagismo seja iniciado o mais breve possível e\na estratégia terapêutica inclua a associação de\nintervenções não farmacológicas e farmacológicas.","D":"É indicado que o tratamento para a cessação do tabagismo seja iniciado o mais breve possível e\na estratégia terapêutica inclua a associação de\nintervenções não farmacológicas e nunca\nfarmacológicas."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-340767","number":"340767","sourceNumber":"340767","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Alguns fatores psicossociais:","options":{"A":"Como o estresse no trabalho e na vida familiar, depressão, ansiedade, hostilidade e\npersonalidade tipo D, assim como o baixo nível\nsócio econômico e cultural, aumentam o risco para\nHA e consequentemente as doenças cardiovasculares (DCV) e diminuem a adesão ao estilo de\nvida saudável e ao tratamento medicamentoso.","B":"Como o estresse no trabalho e na vida familiar, depressão, ansiedade, hostilidade e\npersonalidade tipo D, assim como o baixo\nnível sócio econômico e não o cultural, aumentam o risco\npara HA e consequentemente as doenças cardiovasculares (DCV) e diminuem a adesão ao estilo\nde vida saudável e ao tratamento medicamentoso.","C":"Como o estresse no trabalho e na vida familiar, depressão, ansiedade, hostilidade e\npersonalidade tipo D, assim como o baixo nível\nsócio econômico e cultural, aumentam o risco para\nHA e consequentemente as doenças cardiovasculares (DCV) e aumentam a adesão ao estilo de\nvida saudável e ao tratamento medicamentoso.","D":"Como o estresse no trabalho e na vida familiar, depressão, ansiedade, hostilidade e\npersonalidade tipo D, assim como o baixo nível\nsócio econômico e cultural, aumentam o risco para\nHA e consequentemente as doenças cardiovasculares (DCV) e diminuem a adesão ao estilo de\nvida saudável e não ao tratamento medicamentoso."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-260530","number":"260530","sourceNumber":"260530","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O antidepressivo com maior risco de reações adversas em idosos é:","options":{"A":"Sertralina.","B":"Venlafaxina.","C":"Citalopram.","D":"Amitriptilina."},"answer":"D","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-278844","number":"278844","sourceNumber":"278844","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Sobre os fármacos recomendados para o tratamento de manifestações relacionadas à\nabstinência alcoólica na população pediátrica, assinale a alternativa que apresenta uma droga não\nindicada nesse caso.","options":{"A":"Propofol.","B":"Fenobarbital.","C":"Fenitoina.","D":"Diazepam."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-266584","number":"266584","sourceNumber":"266584","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Homem de 54 anos queixa-se de dor no andar superior do abdômen, muito intensa, há\ncerca de 5h, que apresenta piora após a alimentação e alívio parcial na posição sentada, associada\na náuseas e vômitos. É etilista há 15 anos, ingere 2L de destilados ao dia, e a última ingestão foi\nna\nnoite anterior. Desconhece ser portador de outras doenças. Ao exame físico, PA: 80x50mmHg, FC:\n123bpm, FR: 22ipm, SpO2 96% (em ar ambiente), Tax: 39,1ºC. A palpação abdominal é dolorosa,\nhá defesa voluntária e não há sinais de irritação peritoneal. O restante do exame não apresenta\nanormalidades. Exames de laboratório: Hg: 12g/dL, LG:22.450/µL, Neutrófilos\nsegmentados:19.080/µL, Neutrófilos bastonetes: 1.380/µL, Plaquetas: 137.000/µL, PCR: 210mg/dL,\nCreatinina: 1,5mg/dL, Ureia: 65mg/dL, Lipase: 450U/L (VR<120 U/L), Amilase: 340U/L (VR<80U/L),\nAST: 20U/L (VR<35U/L), ALT: 27U/L (VR<35U/L), Bilirrubinas totais: 1,0mg/dL. Foi realizada\nressuscitação volêmica com 1.500mL de cristaloides, infundidos ao longo de 45 minutos através de\ndois acessos venosos periféricos calibrosos. Em seguida, o paciente apresentou melhora do nível\nda consciência e da PA: 100 x 70mmHg. Após 3 dias da internação hospitalar, o paciente\napresentou agitação psicomotora durante toda a noite e 1 único episódio de crise tônico-clônica\ngeneralizada com 2 minutos de duração e recuperação espontânea. Ao exame físico, estava\ndesorientado no tempo e no espaço, apresentava agitação psicomotora. Apresentava sudorese na\nface e tremor nas extremidades. Os dados vitais eram PA: 160x80mmHg, FC: 123bpm, FR: 22ipm,\nSpO? 97% (em ar ambiente). Os exames de laboratório e a TC do crânio não revelaram\nanormalidades. Assinale a alternativa que apresenta o tratamento MAIS ADEQUADO para a\nintercorrência apresentada pelo paciente:","options":{"A":"Fenitoina IV.","B":"Haloperidol IM.","C":"Lorazepam IV.","D":"Propranolol VO."},"answer":"C","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-266596","number":"266596","sourceNumber":"266596","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Mulher de 83 anos apresenta perda de memória recente e desorientação temporal e\nespacial. Os sintomas iniciaram há cerca de 5 anos e apresentaram piora lenta e progressiva. A\nsenhora perdeu-se no bairro que morava há mais de 40 anos quando saiu para ir à padaria. Não\nconsegue fazer as compras e se esquece de tomar os seus medicamentos de uso diário. É\nportadora de hipertensão arterial sistêmica e de diabetes mellitus tipo II, com controle adequado.\nTeve sífilis secundária há 30 anos, tratada adequadamente com penicilina e o último VDRL era de\n1:4. O exame físico não apresenta anormalidades. A TC do crânio revela atrofia cerebral difusa\ncompatível com a idade e microangiopatia periventricular (leucoaralose). Exames de laboratório:\nVDRL 1:2; anti-HIV NR; TSH: 6,1µUI/mL (VR: 0,48-5,6µUI/mL); T4 livre: 1,42ng/dL (VR:\n\n0,89-1,76ng/dL); Vitamina B12: 456pg/mL (VR: 200 a 900pg/mL). A paciente foi internada por\ncausa de pneumonia e está em uso de\ncefepime. Durante a internação, apresentou períodos de\nagitação psicomotora, desorientação acentuada e alucinações visuais de insetos pequenos. Esse\nquadro ocorria aos finais da tarde e durante as noites, mas havia melhora pela manhã. Apresenta\nalimentação pela via oral, não apresenta evacuação há 8 dias, diurese presente na fralda,\nmantendo-se afebril. Assinale a alternativa que NÃO apresenta uma causa provável para o quadro\napresentado pela paciente durante a internação.","options":{"A":"Efeito colateral de medicamentos.","B":"Esquizofrenia.","C":"Fecaloma.","D":"Infecção."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-287654","number":"287654","sourceNumber":"287654","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"O aconselhamento médico para a cessação do fumo deve ser firme, com ênfase nos\nbenefícios em curto e médio prazos. Práticas agressivas relacionadas à suspensão do tabagismo\ndevem ser adotadas. Sendo correto o item:","options":{"A":"Com frequência, o sucesso na interrupção é obtido após um evento coronário agudo,\nagravamento de doença pulmonar\n\nobstrutiva crônica (DPOC) ou doença vascular periférica sintomática e limitante.","B":"O sucesso na interrupção nunca é obtido após um evento coronário agudo, agravamento de\ndoença pulmonar obstrutiva crônica\n\n(DPOC) ou doença vascular periférica sintomática e limitante.","C":"Com frequência, o sucesso na interrupção é obtido após um evento coronário agudo,\nagravamento de doença pulmonar obstrutiva crônica (DPOC) ou doença vascular periférica\nsintomática, mas não limitante.","D":"Raramente o sucesso na interrupção é obtido após um evento coronário agudo, agravamento de\ndoença pulmonar obstrutiva crônica (DPOC) ou\ndoença vascular periférica sintomática e limitante."},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-238632","number":"238632","sourceNumber":"238632","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Analise o caso clínico a seguir. Um homem de 65 anos de idade encontra-se internado\nno hospital no pós-operatório imediato a uma\nherniorrafia inguinal à direita. Seus exames\n\npré-operatórios apresentaram-se sem alterações. Às duas horas da madrugada, a técnica de\nenfermagem recorre ao médico plantonista,\npois o paciente é encontrado nu, recusa-se a colocar\nnovamente as roupas, fala coisas sem sentido e não reconhece o familiar que o acompanha. Sua\ncirurgia foi realizada na manhã anterior, sem intercorrências, tendo ele recebido meperidina após o\nprocedimento cirúrgico e metoclopramida devido a náuseas. Não se alimentou o dia todo e, ao\nexame físico, não se apresentaram alterações. O exame do seu estado mental mostra\ndesorientação, não atende pelo nome e não sabe onde está, além de estar hipotenso e um pouco\nsonolento. Diante desse quadro, o médico plantonista deve","options":{"A":"prescrever um benzodiazepínico intravenoso para a sedação do paciente e avaliar complicações\npós-operatórias.","B":"avaliar a necessidade das medicações em uso, colocar o paciente em um quarto com boa\niluminação e prescrever um antipsicótico, se constatada agitação psicomotora.","C":"conter fisicamente o paciente e iniciar sedação com midazolam intravenoso, enquanto aguarda\navaliação psiquiátrica.","D":"manter conduta expectante, dado que esses quadros regridem espontaneamente em poucas\nhoras, e prescrever um benzodiazepínico, se\nconstatada agitação psicomotora."},"answer":"B","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-psiquiatria-psi-unico-253911","number":"253911","sourceNumber":"253911","collectionBlock":"medcurso:medcurso-psiquiatria-psi-unico","collectionLabel":"Medcurso · PSI UNICO","documentBlock":"","area":"Psiquiatria","specialty":"Psiquiatria","topic":"PSI UNICO","subtopic":"","stem":"Qual das alterações hematológicas abaixo está mais relacionada à síndrome das\npernas inquietas?","options":{"A":"Anemia ferropriva","B":"Anemia megaloblástica por deficiência de vitamina B12","C":"Anemia megaloblástica por deficiência de folato","D":"Mieloma múltiplo"},"answer":"A","source":"Psiquiatria/PSI UNICO.txt","sourceLabel":"Medcurso · PSI UNICO","images":[],"optionImages":{},"commentImages":[],"tags":["Psiquiatria","PSI UNICO","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
